function normalizeEndkatalogVariant(variant) {
  if (typeof variant === "string") {
    return {
      typ: "standard",
      text: variant.trim()
    };
  }
  return {
    typ: String(variant?.typ || "standard").trim() || "standard",
    text: String(variant?.text || "").trim()
  };
}

function normalizeEndkatalogPair(pair) {
  return {
    ziel: String(pair?.ziel || "").trim(),
    massnahme: String(pair?.massnahme || "").trim(),
    evaluation: String(pair?.evaluation || "").trim()
  };
}

function normalizeEndkatalogSupportChains(entries) {
  return (entries || [])
    .map((entry) => {
      const istStandVarianten = (entry.istStandVarianten || [])
        .map(normalizeEndkatalogVariant)
        .filter((variant) => variant.text);
      const zielMassnahmePaare = (entry.zielMassnahmePaare || [])
        .map(normalizeEndkatalogPair)
        .filter((pair) => pair.ziel || pair.massnahme || pair.evaluation);
      const firstVariant = istStandVarianten[0]?.text || "";
      const firstPair = zielMassnahmePaare[0] || {};
      return {
        bereich: entry.bereich,
        klasse: entry.klasse || "",
        kompetenz: entry.kompetenz,
        gruppe: entry.gruppe || "",
        rating: entry.rating,
        istStand: firstVariant,
        istStandVarianten,
        ziel: firstPair.ziel || "",
        massnahme: firstPair.massnahme || "",
        evaluation: firstPair.evaluation || "",
        zielMassnahmePaare,
        source: "endkatalog"
      };
    })
    .filter((chain) => chain.bereich && chain.kompetenz && chain.rating && chain.istStand)
    .filter((chain) =>
      chain.rating === "gesichert"
      || chain.zielMassnahmePaare.some((pair) => pair.ziel && pair.massnahme && pair.evaluation)
    );
}

function normalizeEndkatalogSupportGroups(entries) {
  return uniqueSupportGroups((entries || []).flatMap((entry) =>
    (entry.gruppenSaetze || []).map((group) => ({
      bereich: group.bereich || entry.bereich,
      klasse: group.klasse || entry.klasse || "",
      gruppe: group.gruppe || entry.gruppe || "",
      istStandBundle: String(group.istStandBundle || "").trim(),
      hilfeSatz: String(group.hilfeSatz || "").trim()
    }))
  ));
}

function uniqueSupportGroups(groups) {
  const seen = new Set();
  return (groups || []).filter((group) => {
    if (!group.bereich || !group.gruppe) return false;
    const key = [
      group.bereich,
      group.klasse || "",
      group.gruppe,
      group.istStandBundle || "",
      group.hilfeSatz || ""
    ].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

