const emotionalFocusCompetenceTopics = [
  ...emotionalSet1CompetenceTopics,
  ...emotionalSet2CompetenceTopics,
  ...emotionalSet3CompetenceTopics
];

function normalizeEmotionalSet1Topic(topic = "") {
  const value = String(topic || "").trim();
  return emotionalSet1CompetenceTopics.includes(value) ? value : "";
}

function selectedEmotionalSet1Topics(entries = []) {
  const selected = new Set(activeComposerModuleEntries(entries.map((entry) => ({
    ...entry,
    area: "Emotionalität, Sozialverhalten"
  }))).map((entry) => String(entry.topic || "").trim()).filter(Boolean));
  const hasOpenTopic = [...selected].some((topic) => !emotionalSet1CompetenceTopics.includes(topic));
  if (hasOpenTopic) return [];
  return emotionalSet1CompetenceTopics.filter((topic) => selected.has(topic));
}

function normalizedEmotionalSet1TemplateTopics(template = {}) {
  return (template.topics || []).map(normalizeEmotionalSet1Topic).filter(Boolean);
}

function sameTopicCombination(left = [], right = []) {
  if (left.length !== right.length) return false;
  return left.every((topic, index) => topic === right[index]);
}

function matchingEmotionalSet1FocusTemplates(entries = []) {
  const selectedTopics = selectedEmotionalSet1Topics(entries);
  if (!selectedTopics.length) return [];
  return emotionalSet1FocusTemplateLibrary.filter((template) =>
    sameTopicCombination(normalizedEmotionalSet1TemplateTopics(template), selectedTopics)
  );
}

function selectedEmotionalSet1FocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingEmotionalSet1FocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function emotionalSet1FocusListSuggestion(items = []) {
  return (items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean)
    .map((item) => `- ${capitalizeListItemText(item)}`)
    .join("\n");
}

function emotionalSet1FocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedEmotionalSet1FocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedEmotionalSet1Topics(entries);
  const templateTopics = normalizedEmotionalSet1TemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: emotionalSet1FocusListSuggestion(template.ziele),
      massnahmen: emotionalSet1FocusListSuggestion(template.massnahmen),
      evaluation: emotionalSet1FocusListSuggestion(template.evaluation)
    }
  };
}

