const correctedEmotionalFrustrationSelfImageConflictIstStand = [
  "Bei Misserfolgen oder Konflikten reagiert _ noch häufig mit Verunsicherung oder Rückzug.",
  "_ benötigt Unterstützung, um Fehler zunehmend als Teil des Lernprozesses anzunehmen und Konflikte mithilfe vereinbarter Gesprächsschritte zu klären.",
  "Erreichbare Teilschritte und verlässliche Gesprächsstrukturen geben #ihm/ihr# Orientierung."
];

function isExactEmotionalFrustrationSelfImageConflictSelection(entries = []) {
  const expectedTopics = [
    "Frustrationstoleranz",
    "Selbstbild / Selbstwirksamkeit",
    "Konfliktverhalten"
  ];
  const active = activeComposerModuleEntries(entries);
  const selectedTopics = active.map((entry) => normalizeEmotionalFocusTopic(entry.topic));
  if (!sameTopicCombination(selectedTopics, expectedTopics)) return false;
  if (!active.every((entry) => entry.rating === "teilweise unsicher")) return false;

  const entryByTopic = new Map(active.map((entry) => [normalizeEmotionalFocusTopic(entry.topic), entry]));
  const frustrationDetails = normalizeCompetenceObservationEntry(
    entryByTopic.get("Frustrationstoleranz")?.observationDetails
  );
  const selfImageDetails = normalizeCompetenceObservationEntry(
    entryByTopic.get("Selbstbild / Selbstwirksamkeit")?.observationDetails
  );
  const conflictDetails = normalizeCompetenceObservationEntry(
    entryByTopic.get("Konfliktverhalten")?.observationDetails
  );

  return frustrationDetails.selected.includes("Misserfolg führt teilweise zu Rückzug.")
    && conflictDetails.selected.includes("Konfliktklärungen brauchen noch klare Begleitung.")
    && !selfImageDetails.selected.length
    && !selfImageDetails.custom;
}

function composeEmotionalFallbackSupportPlan(entries = [], gradeBand = "", variantOffset = 0) {
  const area = "Emotionalität, Sozialverhalten";
  const activeEntries = activeComposerModuleEntries(entries.map((entry) => ({
    ...entry,
    area,
    gradeBand
  }))).filter((entry) => emotionalFocusCompetenceTopics.includes(normalizeEmotionalFocusTopic(entry.topic)));
  if (!activeEntries.length) return null;

  const selectedFromEndkatalog = selectMatchingSupportChains(activeEntries, area, gradeBand, completeSupportChains);
  const selectedFallback = selectedFromEndkatalog.length
    ? selectedFromEndkatalog
    : selectMatchingSupportChains(activeEntries, area, gradeBand, fallbackSupportChains);
  const selected = applyObservationAwarePairs(applyComposerVariants(selectedFallback, variantOffset), area);
  if (!selected.length) return null;

  const composedIstStand = composeIstStandFromSupportGroups({
    area,
    gradeBand,
    selectedChains: selected
  });
  const observationIstStandSentences = emotionalObservationIstStandSentencesForChains(
    selected,
    variantOffset,
    composedIstStand.sentences
  );
  const finalIstStandSentences = removeBlockedIstStandStarts(observationIstStandSentences.length
    ? observationIstStandSentences
    : composedIstStand.sentences);
  const richIstStandSentences = smoothCompetenceIstStandSentences(area, ensureIstStandCoversActiveCompetenceNeeds(
    removeGradeBandReferencesFromIstStandSentences(finalIstStandSentences),
    selected
  ), selected);
  const smoothedIstStandSentences = isExactEmotionalFrustrationSelfImageConflictSelection(activeEntries)
    ? [...correctedEmotionalFrustrationSelfImageConflictIstStand]
    : richIstStandSentences.length
      ? richIstStandSentences
      : finalIstStandSentences;

  const activeTopicCount = activeEntries.length;
  const rawPairs = selectEmotionalComposerPairs(selected);
  const pairLimit = Math.min(4, Math.max(1, activeTopicCount));
  const pairs = prepareComposerPairs(ensureLinkedComposerPairs(rawPairs, {
    area,
    gradeBand,
    entries: activeEntries,
    variantOffset
  }), pairLimit);
  if (!smoothedIstStandSentences.length || !pairs.length) return null;

  const maxEvaluationSentences = Math.min(4, Math.max(1, pairs.length));
  const selectedTopics = sortEmotionalFocusTopics(activeEntries.map((entry) => entry.topic));
  const usedTopics = sortEmotionalFocusTopics(selected.map((chain) => chain.composerTopic || chain.kompetenz));
  const suggestion = {
    istStand: smoothedIstStandSentences.join(" "),
    ziele: formatComposerItems(pairs.map((chain) => chain.ziel), undefined, pairLimit),
    massnahmen: formatComposerItems(pairs.map((chain) => chain.massnahme), undefined, pairLimit),
    evaluation: formatComposerItems(
      pairs.map((chain) => chain.evaluation),
      "list",
      maxEvaluationSentences
    )
  };

  return {
    selectedTopics,
    visibleTopics: selectedTopics,
    usedTopics,
    selectedChains: selected,
    pairs,
    suggestion: checkComposerSuggestion({
      suggestion,
      istStandSentences: smoothedIstStandSentences,
      pairs,
      selectedChains: selected,
      bundledGroups: composedIstStand.bundledGroups,
      allowedIstStandExtras: [
        ...smoothedIstStandSentences,
        ...observationIstStandSentences,
        firstCustomObservationSentenceForChains(selected)
      ],
      maxEvaluationSentences,
      maxPairs: pairLimit
    })
  };
}
