function normalizeSpeechTermDisplayMode(value) {
  return speechTermDisplayModes.includes(value) ? value : "plain";
}

function storedSpeechTermDisplayMode() {
  try {
    return normalizeSpeechTermDisplayMode(localStorage.getItem(SPEECH_TERM_DISPLAY_MODE_KEY));
  } catch {
    return "plain";
  }
}

function speechTermMode() {
  return normalizeSpeechTermDisplayMode(plan?.speechTermDisplayMode || storedSpeechTermDisplayMode());
}

function speechTopicDisplayName(topic, mode = speechTermMode()) {
  const canonical = canonicalSpeechCompetenceTopic(topic);
  const entry = speechTermDisplayMap[canonical];
  return entry?.[normalizeSpeechTermDisplayMode(mode)] || canonical;
}

function speechTopicPhrase(topic, mode = speechTermMode()) {
  const canonical = canonicalSpeechCompetenceTopic(topic);
  const entry = speechTermDisplayMap[canonical];
  const normalizedMode = normalizeSpeechTermDisplayMode(mode);
  if (!entry) return `im Bereich ${canonical}`;
  if (normalizedMode === "technical") return entry.phraseTechnical || `im Bereich ${entry.technical}`;
  if (normalizedMode === "combined") return entry.phraseCombined || `im Bereich ${entry.combined}`;
  return `im Bereich ${entry.plain}`;
}

function moduleTopicDisplayName(area, topic) {
  if (area === "Sprache / Kommunikation") return speechTopicDisplayName(topic);
  if (area === "Lern- und Leistungsverhalten") return learningTopicDisplayName(topic);
  if (area === "Kognition") return cognitionTopicDisplayName(topic);
  return topic;
}

function competenceTopicDisplayName(area, topic) {
  if (area === "Sprache / Kommunikation") return speechTopicDisplayName(topic);
  if (area === "Lern- und Leistungsverhalten") return learningTopicDisplayName(topic);
  if (area === "Kognition") return cognitionTopicDisplayName(topic);
  return topic;
}

