function hiddenLegacyCompetenceTopic(area, topic) {
  const value = String(topic || "").trim();
  if (area === "Lern- und Leistungsverhalten") {
    return learningCompetenceTopicAliases[value] || learningCompetenceTopics.includes(value);
  }
  if (area === "Sprache / Kommunikation") {
    return speechCompetenceTopicAliases[value] || speechCompetenceTopics.includes(value);
  }
  if (area === "Wahrnehmung") {
    return perceptionCompetenceTopicExpansions[value]
      || perceptionCompetenceTopicAliases[value]
      || perceptionCompetenceTopics.includes(value);
  }
  if (area === "Kognition") {
    return cognitionCompetenceTopicAliases[value] || cognitionCompetenceTopics.includes(value);
  }
  return false;
}

function canonicalCompetenceTopics(area, topic) {
  const value = String(topic || "").trim();
  if (area === "Lern- und Leistungsverhalten") return [canonicalLearningCompetenceTopic(value)];
  if (area === "Sprache / Kommunikation") return [canonicalSpeechCompetenceTopic(value)];
  if (area === "Wahrnehmung") {
    if (perceptionCompetenceTopicExpansions[value]) return perceptionCompetenceTopicExpansions[value];
    return [canonicalPerceptionCompetenceTopic(value)];
  }
  if (area === "Kognition") return [canonicalCognitionCompetenceTopic(value)];
  if (area === "Deutsch") return [canonicalGerman34CompetenceTopic(value)];
  if (area === "Mathematik") {
    const math34Topic = canonicalMath34CompetenceTopic(value);
    if (mathCompetenceTopics34.includes(math34Topic)) return [math34Topic];
    return [canonicalMath12CompetenceTopic(value)];
  }
  return [value];
}

function canonicalCompetenceTopic(area, topic) {
  const value = String(topic || "").trim();
  return canonicalCompetenceTopics(area, value)[0] || "";
}

