function motorFocusTemplatePool() {
  return [...motorSet1FocusTemplates, ...motorSet2FocusTemplates, ...motorSet3FocusTemplates, ...motorSet4FocusTemplates];
}

function motorTopicOrderIndex(topic = "") {
  const index = motorCompetenceTopics.indexOf(String(topic || "").trim());
  return index === -1 ? Number.MAX_SAFE_INTEGER : index;
}

function normalizedMotorTemplateTopics(template = {}) {
  return (template.topics || [])
    .map((topic) => String(topic || "").trim())
    .filter((topic) => motorCompetenceTopics.includes(topic))
    .sort((left, right) => motorTopicOrderIndex(left) - motorTopicOrderIndex(right));
}

function selectedMotorTemplateTopics(entries = []) {
  return [...new Set((entries || [])
    .filter((entry) => entry.rating === "unsicher" || entry.rating === "teilweise unsicher")
    .map((entry) => String(entry.topic || "").trim())
    .filter((topic) => motorCompetenceTopics.includes(topic))
  )].sort((left, right) => motorTopicOrderIndex(left) - motorTopicOrderIndex(right));
}

function matchingMotorFocusTemplates(entries = []) {
  const selectedTopics = selectedMotorTemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const selectedKey = selectedTopics.join("|");
  return motorFocusTemplatePool()
    .map((template, index) => ({
      template,
      index,
      topicKey: normalizedMotorTemplateTopics(template).join("|")
    }))
    .filter((item) => item.topicKey === selectedKey)
    .sort((left, right) => left.index - right.index)
    .map((item) => item.template);
}

function selectedMotorFocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingMotorFocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function motorFocusTemplateFieldItems(template, fieldKey = "") {
  const value = template?.[fieldKey];
  const values = Array.isArray(value) ? value : [value];
  return values
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
}

function motorFocusListSuggestion(items = []) {
  return (items || [])
    .map((item) => bulletSuggestion(item))
    .filter(Boolean)
    .join("\n");
}

function motorFocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedMotorFocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedMotorTemplateTopics(entries);
  const templateTopics = normalizedMotorTemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: String(template.istStand || "").trim(),
      ziele: motorFocusListSuggestion(motorFocusTemplateFieldItems(template, "ziele")),
      massnahmen: motorFocusListSuggestion(motorFocusTemplateFieldItems(template, "massnahmen")),
      evaluation: motorFocusListSuggestion(motorFocusTemplateFieldItems(template, "evaluation"))
    }
  };
}

function motorFallbackChainsFromEntries(entries = []) {
  return selectedMotorTemplateTopics(entries)
    .map((topic) => (entries || []).find((entry) => String(entry.topic || "").trim() === topic))
    .filter(Boolean)
    .map((entry) => ({
      bereich: "Motorik",
      rating: entry.rating,
      kompetenz: entry.topic,
      composerTopic: entry.topic,
      observation: entry.observation,
      observationDetails: entry.observationDetails || {},
      selectedObservations: entry.selectedObservations || []
    }));
}

function fallbackTextFromMotorModules(fieldSelections = {}, fieldKey = "", formatOptions = plan.formatOptions) {
  const modules = fieldSelections?.[fieldKey]?.modules || [];
  const result = createTextFromSelectedModules(modules, fieldKey, formatOptions);
  return result.error ? "" : String(result.text || "").trim();
}

function fallbackMotorIstStand(entries = [], fieldSelections = {}, variantOffset = 0, formatOptions = plan.formatOptions) {
  const chains = motorFallbackChainsFromEntries(entries);
  const sentences = motorObservationIstStandSentencesForChains(chains, variantOffset);
  if (sentences.length) return removeExactRepeatedSentences(sentences).join(" ");
  return fallbackTextFromMotorModules(fieldSelections, "istStand", formatOptions);
}

function cleanMotorFallbackText(value = "") {
  return String(value || "")
    .replace(/\bVerglichen wird, ob\b/g, "Überprüft wird, ob")
    .replace(/\bVorlagen\b/g, "Ausgangstexte")
    .replace(/\bVorlage\b/g, "Ausgangstext")
    .replace(/\bBausteine?\b/g, "Texte")
    .replace(/\bFörderkette\b/g, "Förderplanung")
    .replace(/\bFallback\b/g, "Vorschlag")
    .trim();
}

function cleanMotorFallbackGoalText(value = "") {
  return cleanMotorFallbackText(value).replace(/^(\s*[–—•*-]\s*)([a-zäöü])/gmu, (_, prefix, firstLetter) =>
    `${prefix}${firstLetter.toLocaleUpperCase("de-DE")}`
  );
}

function composeMotorFallbackSupportPlan(entries = [], fieldSelections = {}, formatOptions = plan.formatOptions, variantOffset = 0) {
  const selectedTopics = selectedMotorTemplateTopics(entries);
  if (!selectedTopics.length) return null;
  const suggestion = {
    istStand: cleanMotorFallbackText(fallbackMotorIstStand(entries, fieldSelections, variantOffset, formatOptions)),
    ziele: cleanMotorFallbackGoalText(fallbackTextFromMotorModules(fieldSelections, "ziele", formatOptions)),
    massnahmen: cleanMotorFallbackText(fallbackTextFromMotorModules(fieldSelections, "massnahmen", formatOptions)),
    evaluation: cleanMotorFallbackText(fallbackTextFromMotorModules(fieldSelections, "evaluation", formatOptions))
  };
  if (!columns.every((column) => String(suggestion[column.key] || "").trim())) return null;
  return {
    selectedTopics,
    visibleTopics: selectedTopics,
    usedTopics: selectedTopics,
    suggestion
  };
}
