function learningCategoryForText(text = "", fallbackTopic = "") {
  const normalized = normalizeMatchValue(text);
  if (/aufgabenbeginn|start|arbeitsschritt|arbeitsauftrag|wartezeit|einstieg|offene aufgaben/.test(normalized)) {
    return "start";
  }
  if (/aufmerksamkeit|konzentr|ablenk|zeitabschnitt|erinnerung|umgebung|unterrichtsablauf/.test(normalized)) {
    return "attention";
  }
  if (/ausdauer|dranbleiben|weiterarbeit|teilschritt|pause|abschluss|durchhalten|beendet|schwierigkeit|längere arbeitsphase/.test(normalized)) {
    return "endurance";
  }
  if (/selbstständig|selbstständigkeit|rückversicherung|hilfekarte|hilfsmittel|routine|unsicherheit/.test(normalized)) {
    return "independence";
  }
  if (/material|arbeitsplatz|arbeitsmittel|ordnung|ablauf|aufgabenblatt|heft|übergang|reihenfolge|checkliste|aufräumen/.test(normalized)) {
    return "organization";
  }
  return learningTopicCategories[fallbackTopic] || "";
}

function learningPairScore(pair, chain) {
  const pairText = normalizeMatchValue([
    pair.ziel,
    pair.massnahme,
    pair.evaluation
  ].join(" "));
  const observationText = [
    ...(chain.observationDetails?.selected || []),
    chain.observationDetails?.custom || "",
    chain.observation || ""
  ].join(" ");
  const categories = [
    learningCategoryForText(observationText, chain.composerTopic || chain.kompetenz),
    learningTopicCategories[chain.composerTopic || chain.kompetenz] || ""
  ].filter(Boolean);
  let score = 0;
  categories.forEach((category) => {
    if (category === "start" && /start|arbeitsauftrag|arbeitsschritt|aufgabenbeginn|orientierung/.test(pairText)) score += 5;
    if (category === "attention" && /aufmerksamkeit|konzentration|ablenkung|arbeitsphase|timer|unterbrechung/.test(pairText)) score += 5;
    if (category === "endurance" && /aufgabe|weiterarbeit|teilschritt|pause|abschluss|ausdauer|vollständig/.test(pairText)) score += 5;
    if (category === "independence" && /hilfe|hilfekarte|checkliste|selbstständig|arbeitsschritt|nachfragen/.test(pairText)) score += 5;
    if (category === "organization" && /material|arbeitsplatz|ordnung|ablage|arbeitsablauf|checkliste|arbeitsschritt/.test(pairText)) score += 5;
  });
  const observationKeywords = normalizeMatchValue(observationText)
    .split(/[^a-zäöüß]+/i)
    .filter((word) => word.length >= 6);
  score += observationKeywords.reduce((sum, word) => sum + (pairText.includes(word) ? 1 : 0), 0);
  if (chain.rating === "unsicher") score += 2;
  return score;
}

function speechCategoryForText(text = "", fallbackTopic = "") {
  const normalized = normalizeMatchValue(text);
  if (/aussprache|artikulation|lautbildung|laut.*gebildet|lautersetzung|ausgelassen|verständlich|spontansprache/.test(normalized)) {
    return "articulation";
  }
  if (/reim|silb|anlaut|endlaut|inlaut|lautwahrnehmung|phonologisch|ähnlich.*laut|lautfolge/.test(normalized)) {
    return "phonology";
  }
  if (/arbeitsauftrag|auftrag|mehrschritt|schlüsselwort|visualisiert|arbeitsschritt|wiederholung|vormachen|erklärung|kurze.*sätze/.test(normalized)) {
    return "understanding";
  }
  if (/wortschatz|wort|begriff|fachbegriff|bildmaterial|umschreibung|wortbedeutung|sprachmuster/.test(normalized)) {
    return "vocabulary";
  }
  if (/satz|satzstruktur|satzanfang|satzmuster|verb|endung|fragesatz|satzverbindung|wortstellung|grammatik/.test(normalized)) {
    return "sentence";
  }
  if (/erzählen|erzähl|versprachlich|handlungsablauf|lösungsweg|reihenfolge|anfang|verlauf|thema/.test(normalized)) {
    return "narration";
  }
  if (/gespräch|zuhören|beitrag|abwarten|gruppe|regel|rückfrage|thema|beteiligung/.test(normalized)) {
    return "conversation";
  }
  if (/stimme|sprechweise|lautstärke|stimmlage|betonung|sprechmelodie|sprechtempo/.test(normalized)) {
    return "voice";
  }
  if (/redefluss|wortfindung|pause|füllwort|satzabbruch|formulieren|sprechtempo/.test(normalized)) {
    return "fluency";
  }
  return speechTopicCategories[fallbackTopic] || "";
}

