function germanCategoryForText(text = "", fallbackTopic = "", gradeBand = gradeBandForPlan()) {
  const normalized = normalizeMatchValue(text);
  if (/buchstabe|laut|silbe|lautierend|wort.*erles|wörter.*lesen|kurze sätze|lesetext|geraten|automatisiert.*wort/.test(normalized)) {
    return "reading-basic";
  }
  if (/leseflüssigkeit|stockend|lesetempo|satzgrenze|sinnabschnitt|vorlesen|längere wörter|automatisierung/.test(normalized)) {
    return "reading-fluency";
  }
  if (/leseverständnis|textverständnis|information|textfrage|nacherzähl|zusammenhang|unbekannte wörter|vorwissen|überblick/.test(normalized)) {
    return gradeBand === "Klasse 3/4" ? "text-comprehension" : "reading-comprehension";
  }
  if (/rechtschreibstrategie|verlängern|ableiten|silbier|fehlerwörter|merkwörter|eigene fehler|übungswörter/.test(normalized)) {
    return "spelling-strategy";
  }
  if (/lesestrategie|vor dem lesen|markier|fragen an den text|zusammenfass|nachschlag|strategie/.test(normalized)) {
    return "reading-strategy";
  }
  if (/lautgetreu|laut.*schreib|vokal|abhören|anlauttabelle|lautgebärde|verschrift|silbenklatsch/.test(normalized)) {
    return "phonetic-writing";
  }
  if (/abschreib|vorlage|tafel|abschrift|kontrollier|fehler.*kontroll/.test(normalized)) {
    return "copy-control";
  }
  if (/rechtschreibgrund|groß|klein|wortgrenze|satzzeichen|nomen|lernwörter|merkhilfe|rechtschreibmuster/.test(normalized)) {
    return "spelling-basic";
  }
  if (/eigene sätze|satzanfang|satzgrenze|satzmuster|bildimpuls|eigene gedanken|mündliche vorplanung/.test(normalized)) {
    return "sentence-writing";
  }
  if (/eigene texte|textaufbau|roter faden|schreibplanung|einleitung|hauptteil|schluss|textsort|satzstarter/.test(normalized)) {
    return "text-writing";
  }
  if (/wortart|satzglied|satzstruktur|grammatisch|sprachliche muster|regel und beispiel|sortieraufgabe/.test(normalized)) {
    return "grammar";
  }
  if (/texte kontrollieren|textkontrolle|überarbeitung|checkliste|rechtschreibfehler|rückmeldung|überarbeitungsphase/.test(normalized)) {
    return "text-control";
  }
  return germanTopicCategoriesForGrade(gradeBand)[fallbackTopic] || "";
}

function germanPairScore(pair, chain, gradeBand = gradeBandForPlan()) {
  const pairText = normalizeMatchValue([
    pair.ziel,
    pair.massnahme,
    pair.evaluation
  ].join(" "));
  const observationText = [
    ...(chain.observationDetails?.selected || []),
    chain.observationDetails?.custom || "",
    chain.observation || ""
  ].join(" ");
  const categories = [
    germanCategoryForText(observationText, chain.composerTopic || chain.kompetenz, gradeBand),
    germanTopicCategoriesForGrade(gradeBand)[chain.composerTopic || chain.kompetenz] || ""
  ].filter(Boolean);
  let score = 0;
  categories.forEach((category) => {
    if (category === "reading-basic" && /buchstabe|laut|silbe|wort|satz|lesen|erlesen|lautgetreu/.test(pairText)) score += 5;
    if (category === "reading-comprehension" && /verständnis|text|satz|frage|bild|information|nacherzähl/.test(pairText)) score += 5;
    if (category === "reading-fluency" && /leseflüss|lesetempo|vorlesen|wiederholt|sinnabschnitt|satzgrenze|automatis/.test(pairText)) score += 5;
    if (category === "text-comprehension" && /text|information|frage|markier|schlüssel|abschnitt|verständnis/.test(pairText)) score += 5;
    if (category === "reading-strategy" && /strategie|markier|frage|zusammenfass|vorwissen|nachschlag|leseschritt/.test(pairText)) score += 5;
    if (category === "phonetic-writing" && /laut|silbe|vokal|abhör|anlaut|lautgetreu|schreib/.test(pairText)) score += 5;
    if (category === "copy-control" && /abschreib|vorlage|kontroll|fehler|vergleich|markier/.test(pairText)) score += 5;
    if (category === "spelling-basic" && /rechtschreib|nomen|groß|klein|satzzeichen|wortgrenze|lernwörter|merkwort/.test(pairText)) score += 5;
    if (category === "spelling-strategy" && /strategie|verlänger|ableit|silbier|merkwort|fehler|kontroll/.test(pairText)) score += 5;
    if (category === "sentence-writing" && /satz|satzanfang|bild|wortkarte|formulier|schreib/.test(pairText)) score += 5;
    if (category === "text-writing" && /text|schreibplan|aufbau|einleitung|hauptteil|schluss|überarbeit|satzanfang/.test(pairText)) score += 5;
    if (category === "grammar" && /wortart|satzglied|grammatik|regel|beispiel|sortier|sprache/.test(pairText)) score += 5;
    if (category === "text-control" && /kontroll|überarbeit|checkliste|fehler|satzzeichen|rückmeldung/.test(pairText)) score += 5;
  });
  const observationKeywords = normalizeMatchValue(observationText)
    .split(/[^a-zäöüß]+/i)
    .filter((word) => word.length >= 6);
  score += observationKeywords.reduce((sum, word) => sum + (pairText.includes(word) ? 1 : 0), 0);
  if (chain.rating === "unsicher") score += 2;
  return score;
}

function mathCategoryForText(text = "", fallbackTopic = "", gradeBand = gradeBandForPlan()) {
  const normalized = normalizeMatchValue(text);
  if (/zahlverständnis|zahlvorstellung|menge|zahlbild|ziffer|zahlwort|zahlenreihe|zahlordnung|vorgänger|nachfolger|zahlenstrahl|zahlbeziehung|zahlenraum|rundung|nachbarzahl/.test(normalized)) {
    return "number";
  }
  if (/stellenwert|einer|zehner|hunderter|tausender|bündel|stellenwerttafel|ziffer.*wert|zahlaufbau|sprechweise/.test(normalized)) {
    return "place";
  }
  if (/zerleg|ergänzen bis 10|partnerzahl|zerlegungshaus|wendeplättchen/.test(normalized)) {
    return "decomposition";
  }
  if (/zehnerübergang|zehnerfeld|rechenrahmen|zwischenschritt|zweite zahl/.test(normalized)) {
    return "transition";
  }
  if (/addition|subtraktion|plus|minus|additions|subtraktions|wegnehmen|tauschaufgabe|verdoppl|übergang|rechenaufgabe/.test(normalized)) {
    return "operation";
  }
  if (/strategie|kopfrechnen|hilfsaufgabe|rechenweg|zählend|zählen|aufgabenstruktur|zahlbeziehung|automatisiert/.test(normalized)) {
    return "strategy";
  }
  if (/schriftlich|übertrag|untereinander|verfahren|einzelschritt|stellen.*schreiben/.test(normalized)) {
    return "written";
  }
  if (/multiplikation|division|einmaleins|aufteilen|verteilen|kernaufgabe|ableitung/.test(normalized)) {
    return "multiplication";
  }
  if (/sachaufgabe|rechengeschichte|information|rechenoperation|antwort|frage|skizze|tabelle|textaufgabe/.test(normalized)) {
    return "word";
  }
  if (/größe|größen|maßeinheit|einheit|umwandlung|schätzen|messen|geld|zeit|länge|gewicht/.test(normalized)) {
    return "measurement";
  }
  if (/geometr|form|muster|lage|figur|körper|zeichnung|räumlich|symmetrie|messen und zeichnen/.test(normalized)) {
    return "geometry";
  }
  if (/daten|tabelle|diagramm|achse|legende|überschrift|angabe/.test(normalized)) {
    return "data";
  }
  if (/material|handlung|anschauung|plättchen|zahlkarte|rechenmaterial/.test(normalized)) {
    return "material";
  }
  return mathTopicCategoriesForGrade(gradeBand)[fallbackTopic] || "";
}

function mathPairScore(pair, chain, gradeBand = gradeBandForPlan()) {
  const pairText = normalizeMatchValue([
    pair.ziel,
    pair.massnahme,
    pair.evaluation
  ].join(" "));
  const observationText = [
    ...(chain.observationDetails?.selected || []),
    chain.observationDetails?.custom || "",
    chain.observation || ""
  ].join(" ");
  const categories = [
    mathCategoryForText(observationText, chain.composerTopic || chain.kompetenz, gradeBand),
    mathTopicCategoriesForGrade(gradeBand)[chain.composerTopic || chain.kompetenz] || ""
  ].filter(Boolean);
  let score = 0;
  categories.forEach((category) => {
    if (category === "number" && /zahl|menge|zahlenstrahl|zahlbeziehung|ordnen|vergleichen|darstellen/.test(pairText)) score += 5;
    if (category === "place" && /stellenwert|stellenwerttafel|bündel|zerleg|einer|zehner|hunderter|tausender/.test(pairText)) score += 5;
    if (category === "decomposition" && /zerleg|partnerzahl|ergänz|schüttelbox|zerlegungshaus/.test(pairText)) score += 5;
    if (category === "operation" && /plus|minus|addition|subtraktion|rechenaufgabe|rechenweg|aufgaben/.test(pairText)) score += 5;
    if (category === "transition" && /zehnerübergang|zehner|teilschritt|zerleg/.test(pairText)) score += 5;
    if (category === "strategy" && /strategie|kopfrechen|zahlbeziehung|rechenweg|verdopp|nachbar|zählend|aufgabenbeziehung/.test(pairText)) score += 5;
    if (category === "mental" && /kopfrechen|automatis|zahlbeziehung|hilfsaufgabe|zerleg|verdopp|aufgabenbeziehung/.test(pairText)) score += 5;
    if (category === "written" && /schriftlich|verfahren|übertrag|stellenwert|schrittkarte|kontroll/.test(pairText)) score += 5;
    if (category === "multiplication" && /multiplikation|division|einmaleins|kernaufgabe|umkehraufgabe|malaufgabe/.test(pairText)) score += 5;
    if (category === "word" && /sachaufgabe|sachsituation|frage|daten|rechnung|antwort|skizze|tabelle|information/.test(pairText)) score += 5;
    if (category === "measurement" && /größe|einheit|messen|schätzen|geld|zeit|länge|gewicht|material/.test(pairText)) score += 5;
    if (category === "geometry" && /geometr|form|körper|muster|lage|eigenschaft|raster|material/.test(pairText)) score += 5;
    if (category === "data" && /daten|tabelle|diagramm|darstellung|markier|leitfrage/.test(pairText)) score += 5;
    if (category === "material" && /material|handlung|bild|rechnung|anschauung|darstell/.test(pairText)) score += 5;
  });
  const observationKeywords = normalizeMatchValue(observationText)
    .split(/[^a-zäöüß]+/i)
    .filter((word) => word.length >= 6);
  score += observationKeywords.reduce((sum, word) => sum + (pairText.includes(word) ? 1 : 0), 0);
  if (chain.rating === "unsicher") score += 2;
  return score;
}

function emotionalPairScore(pair, chain) {
  const pairText = normalizeMatchValue([
    pair.ziel,
    pair.massnahme,
    pair.evaluation
  ].join(" "));
  const observationText = [
    ...(chain.observationDetails?.selected || []),
    chain.observationDetails?.custom || "",
    chain.observation || ""
  ].join(" ");
  const categories = [
    emotionalCategoryForText(observationText, chain.composerTopic || chain.kompetenz),
    emotionalTopicCategories[chain.composerTopic || chain.kompetenz] || ""
  ].filter(Boolean);
  let score = observationPairScore(pair, chain) * 3;
  categories.forEach((category) => {
    if (category === "regulation" && /gefühl|beruhig|belast|rückzug|rückkehr|handlungsfähig|skala|reflexion/.test(pairText)) score += 4;
    if (category === "frustration" && /fehler|misserfolg|frustration|teilschritt|weiterarbeit|aufgabe|rückkehr/.test(pairText)) score += 4;
    if (category === "conflict" && /konflikt|gespräch|hilfe|klärung|streit|rollenspiel|satz/.test(pairText)) score += 4;
    if (category === "rules" && /regel|erinner|übergang|absprach|verhalten/.test(pairText)) score += 4;
    if (category === "contact" && /kontakt|partner|gruppe|rolle|gespräch|beteilig/.test(pairText)) score += 4;
    if (category === "cooperation" && /partner|gruppe|rolle|absprache|kooperativ|zusammenarbeit/.test(pairText)) score += 4;
  });
  if (chain.rating === "unsicher") score += 2;
  return score;
}

function selectEmotionalComposerPairs(chains) {
  const limit = emotionalGoalLimitForChains(chains);
  const pairs = [];
  const usedTopics = new Set();
  activeEmotionalChains(chains).forEach((chain) => {
    if (pairs.length >= limit) return;
    const topicKey = normalizeMatchValue(chain.composerTopic || chain.kompetenz);
    if (topicKey && usedTopics.has(topicKey)) return;
    const supportPairs = supportPairsForChain(chain);
    if (!supportPairs.length) return;
    const selectedPair = supportPairs
      .map((pair, index) => ({
        pair,
        index,
        score: emotionalPairScore(pair, chain)
      }))
      .sort((left, right) =>
        right.score - left.score
        || left.index - right.index
      )[0]?.pair;
    if (!selectedPair?.ziel || !selectedPair?.massnahme) return;
    const repeatedGoal = isRepeatedSuggestion(selectedPair.ziel, pairs.map((pair) => pair.ziel));
    const repeatedMeasure = isRepeatedSuggestion(selectedPair.massnahme, pairs.map((pair) => pair.massnahme));
    if (repeatedGoal || repeatedMeasure) return;
    pairs.push({
      ...chain,
      ziel: selectedPair.ziel,
      massnahme: selectedPair.massnahme,
      evaluation: selectedPair.evaluation
    });
    if (topicKey) usedTopics.add(topicKey);
  });
  return pairs;
}

