function selectedPerceptionTopicsFromEntries(entries = []) {
  return [...new Set(entries
    .filter((entry) => entry.rating === "unsicher" || entry.rating === "teilweise unsicher")
    .map((entry) => canonicalPerceptionCompetenceTopic(entry.topic))
    .filter((topic) => perceptionCompetenceTopics.includes(topic))
  )].sort((left, right) => perceptionTopicOrderIndex(left) - perceptionTopicOrderIndex(right));
}

function perceptionChainsFromEntries(entries = []) {
  return entries
    .filter((entry) => entry.rating === "unsicher" || entry.rating === "teilweise unsicher")
    .map((entry) => {
      const topic = canonicalPerceptionCompetenceTopic(entry.topic);
      return {
        bereich: "Wahrnehmung",
        kompetenz: topic,
        composerTopic: topic,
        gruppe: topic,
        rating: entry.rating,
        observation: entry.observation || "",
        observationDetails: entry.observationDetails || { selected: [], custom: "", relatedRating: "" },
        index: entry.index || 0
      };
    })
    .filter((chain) => perceptionCompetenceTopics.includes(chain.composerTopic))
    .sort((left, right) =>
      perceptionTopicOrderIndex(left.composerTopic) - perceptionTopicOrderIndex(right.composerTopic)
      || left.index - right.index
    );
}

function perceptionSuggestionMeta(entries = [], pairs = []) {
  const selectedTopics = selectedPerceptionTopicsFromEntries(entries);
  const pairTopics = [...new Set(pairs
    .map((pair) => canonicalPerceptionCompetenceTopic(pair.composerTopic || pair.kompetenz))
    .filter((topic) => perceptionCompetenceTopics.includes(topic))
  )].sort((left, right) => perceptionTopicOrderIndex(left) - perceptionTopicOrderIndex(right));
  const missingTopics = selectedTopics.filter((topic) => !pairTopics.includes(topic));
  const notes = [];
  if (selectedTopics.length > 6) {
    notes.push("Es wurden viele Wahrnehmungsbereiche ausgewählt. Für einen klaren Förderplan ist eine Schwerpunktsetzung sinnvoll.");
  }
  if (selectedTopics.length > 3) {
    notes.push("Die ausgewählten Bereiche wurden thematisch gebündelt, aber nicht ausgelassen.");
  }
  if (missingTopics.length) {
    notes.push(`Für diese Bereiche fehlen noch verknüpfte Vorschlagspaare: ${missingTopics.join(", ")}.`);
  }
  return {
    selectedTopics,
    usedTopics: pairTopics,
    missingTopics,
    notes,
    summary: selectedTopics.length
      ? `Für diesen Vorschlag wurden ${pairTopics.length} von ${selectedTopics.length} ausgewählten Bereichen berücksichtigt.`
      : ""
  };
}

function assertPerceptionSuggestionCoverage(meta) {
  if (!meta?.missingTopics?.length) return;
  console.warn("Wahrnehmungsvorschlag nicht vollständig abgedeckt:", {
    selectedTopics: meta.selectedTopics,
    usedTopics: meta.usedTopics,
    missingTopics: meta.missingTopics
  });
}

