function applyObservationAwarePairs(chains, area) {
  if (area !== "Emotionalität, Sozialverhalten") return chains;
  return chains.map((chain) => {
    if (!chain.observation && !competenceObservationHasContent(chain.observationDetails)) return chain;
    const pairs = supportPairsForChain(chain);
    if (pairs.length < 2) return chain;
    const bestPair = pairs
      .map((pair, index) => ({ pair, index, score: observationPairScore(pair, chain) }))
      .sort((left, right) => right.score - left.score || left.index - right.index)[0];
    if (!bestPair || bestPair.score <= 0) return chain;
    return {
      ...chain,
      ziel: bestPair.pair.ziel || chain.ziel || "",
      massnahme: bestPair.pair.massnahme || chain.massnahme || "",
      evaluation: bestPair.pair.evaluation || chain.evaluation || ""
    };
  });
}

function formatComposerItems(items, displayMode, limit = 4) {
  const sentences = removeRepeatedSentences(
    items.map((item) => String(item || "").trim()).filter(Boolean)
  ).slice(0, limit);
  return displayMode === "text"
    ? sentences.join(" ")
    : sentences.map((sentence) => `– ${capitalizeListItemText(sentence)}`).join("\n");
}

