const unsuitableComposerGoalPatterns = [
  /\bverbessert\s+(?:sein|ihr|#sein\/ihr#)\s+verhalten\b/i,
  /\barbeitet\s+besser\s+mit\b/i,
  /\bsteigert\s+(?:seine|ihre|#seine\/ihre#)\s+leistung\b/i,
  /^_\s+wird\s+sicherer\.?$/i,
  /\bsoll\s+sich\s+mehr\s+konzentrieren\b/i,
  /^Sicherheit im Bereich .+ erweitern\.?$/i
];

function normalizeComposerSentence(value) {
  return cleanSuggestionSentence(value).replace(/#seinen\/ihren#/g, "#sein/ihr#");
}

function polishComposerGoal(value) {
  const sentence = normalizeComposerSentence(value)
    .replace(/^_ soll\s+/i, "_ ")
    .replace(/^#er\/sie# soll\s+/i, "_ ");
  return composerGoalReplacements.get(sentence) || sentence;
}

function polishComposerMeasure(value) {
  return composerMeasureReplacements.get(normalizeComposerSentence(value)) || normalizeComposerSentence(value);
}

function polishComposerEvaluation(value) {
  return composerEvaluationReplacements.get(normalizeComposerSentence(value)) || normalizeComposerSentence(value);
}

function composerPairIsUsable(pair) {
  const goal = polishComposerGoal(pair?.ziel || "");
  const measure = polishComposerMeasure(pair?.massnahme || "");
  const evaluation = polishComposerEvaluation(pair?.evaluation || "");
  if (!goal || !measure || !evaluation) return false;
  if (unsuitableComposerGoalPatterns.some((pattern) => pattern.test(goal))) return false;
  if (composerHasInvalidPlaceholder([goal, measure, evaluation].join(" "))) return false;
  if (/^(?:Beobachtung im Unterricht|Rückmeldung der Lehrkraft|Gespräch mit Eltern|Überprüfung der Mitarbeit)\.?$/i.test(evaluation)) return false;
  return true;
}

function polishComposerPair(chain) {
  return {
    ...chain,
    ziel: polishComposerGoal(chain.ziel),
    massnahme: polishComposerMeasure(chain.massnahme),
    evaluation: polishComposerEvaluation(chain.evaluation)
  };
}

function prepareComposerPairs(pairs = [], limit = 4) {
  const prepared = [];
  pairs.forEach((pair) => {
    if (prepared.length >= limit || !composerPairIsUsable(pair)) return;
    const polished = polishComposerPair(pair);
    const repeatedGoal = isRepeatedSuggestion(polished.ziel, prepared.map((item) => item.ziel));
    const repeatedMeasure = isRepeatedSuggestion(polished.massnahme, prepared.map((item) => item.massnahme));
    if (repeatedGoal || repeatedMeasure) return;
    prepared.push(polished);
  });
  return prepared;
}

function uniqueCompleteIstStandSentences(sentences = []) {
  return removeRepeatedSentences(
    sentences
      .map((sentence) => String(sentence || "").trim())
      .filter((sentence) => isCompleteStoredIstStand(sentence))
  );
}

function additionalIstStandVariants(chain, limit = 1, excludedTexts = [chain?.istStand || ""]) {
  const excluded = new Set(excludedTexts.map((text) => normalizeMatchValue(text)));
  return uniqueCompleteIstStandSentences(
    istStandVariantsForChain(chain)
      .map((variant) => variant.text)
      .filter((text) => !excluded.has(normalizeMatchValue(text)))
  ).slice(0, limit);
}

function needFocusedIstStandSentence(chain) {
  if (chain.rating !== "unsicher") return chain.istStand;
  const variants = istStandVariantsForChain(chain);
  return variants.find((variant) => variant.typ === "foerderbedarf")?.text
    || variants.find((variant) => /fällt|erschwer|braucht|benötigt|noch|unsicher|nicht/i.test(variant.text))?.text
    || chain.istStand;
}

function supportFocusedIstStandVariant(chain, excludedTexts = [chain?.istStand || ""]) {
  return additionalIstStandVariants(chain, 4, excludedTexts).find((sentence) =>
    /unterstütz|hilf|orientierung|struktur|visualis|klar|überschaubar|material|rückmeldung|anleitung|schritt/i.test(sentence)
  ) || additionalIstStandVariants(chain, 1, excludedTexts)[0] || "";
}

