function completeAnchorSentence(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  return /[.!?]$/.test(raw) ? raw : `${raw}.`;
}

function pickCompleteVariant(primary, variants = [], variantOffset = 0, index = 0) {
  const options = removeRepeatedSentences(
    [primary, ...(Array.isArray(variants) ? variants : [])]
      .map(completeAnchorSentence)
      .filter(Boolean)
  );
  if (!options.length) return "";
  const selectedIndex = ((variantOffset + index) % options.length + options.length) % options.length;
  return options[selectedIndex];
}

function emotionalObservationAnchor(text, variantOffset = 0, index = 0) {
  const raw = String(text || "").trim();
  const anchor = emotionalObservationIstStandAnchors[raw];
  if (!anchor) {
    return {
      istStand: completeAnchorSentence(raw),
      bedingung: "",
      entwicklung: ""
    };
  }
  if (typeof anchor === "string") {
    return {
      istStand: completeAnchorSentence(anchor),
      bedingung: "",
      entwicklung: ""
    };
  }
  return {
    istStand: pickCompleteVariant(anchor.istStand, anchor.istStandVarianten, variantOffset, index),
    bedingung: pickCompleteVariant(anchor.bedingung, anchor.bedingungVarianten, variantOffset, index),
    entwicklung: pickCompleteVariant(anchor.entwicklung, anchor.entwicklungVarianten, variantOffset, index)
  };
}

