function customObservationSentence(text) {
  const raw = String(text || "").trim();
  if (!raw) return "";
  const sentence = /[.!?]$/.test(raw) ? raw : `${raw}.`;
  return `Eigene Unterrichtsbeobachtung: ${sentence}`;
}

function istStandTargetLengthBySeverity(active = []) {
  const activeChains = active.filter((chain) =>
    chain.rating === "teilweise unsicher" || chain.rating === "unsicher"
  );
  const activeCount = activeChains.length;
  if (!activeCount) return 0;
  const insecureCount = activeChains.filter((chain) => chain.rating === "unsicher").length;
  const hasCustomObservation = activeChains.some((chain) =>
    normalizeCompetenceObservationEntry(chain.observationDetails).custom.trim()
  );

  let baseTarget = 3;
  if (activeCount === 1) {
    baseTarget = insecureCount ? 4 : 3;
  } else if (activeCount === 2) {
    baseTarget = insecureCount ? 6 : 5;
  } else {
    baseTarget = insecureCount >= 2 ? 8 : 7;
  }
  return Math.min(9, baseTarget + (hasCustomObservation ? 1 : 0));
}

function compactComposerIstStandTargetLength(active = []) {
  const activeChains = active.filter((chain) =>
    chain.rating === "teilweise unsicher" || chain.rating === "unsicher"
  );
  const activeCount = activeChains.length;
  if (!activeCount) return 0;
  const hasUnsicher = activeChains.some((chain) => chain.rating === "unsicher");
  const hasCustomObservation = activeChains.some((chain) =>
    normalizeCompetenceObservationEntry(chain.observationDetails).custom.trim()
  );
  let baseTarget = 3;
  if (activeCount === 1) {
    baseTarget = hasUnsicher ? 4 : 3;
  } else if (activeCount === 2) {
    baseTarget = hasUnsicher ? 5 : 4;
  } else {
    baseTarget = hasUnsicher ? 6 : 5;
  }
  return Math.min(7, baseTarget + (hasCustomObservation ? 1 : 0));
}

