function polishIstStandSentence(sentence) {
  return istStandPolishReplacements[sentence] || sentence;
}

function completeBundleVariants(map, key, variantOffset = 0) {
  const variants = map[key] || map.general || [];
  const complete = removeRepeatedSentences(
    (Array.isArray(variants) ? variants : [])
      .map(completeAnchorSentence)
      .map(polishIstStandSentence)
      .filter(Boolean)
  );
  if (complete.length <= 1) return complete;
  const shift = ((variantOffset % complete.length) + complete.length) % complete.length;
  return [...complete.slice(shift), ...complete.slice(0, shift)];
}

function layeredObservationIstStandSentences({
  target,
  main = [],
  concrete = [],
  condition = [],
  custom = "",
  perspective = [],
  extra = []
}) {
  const sentences = [];
  const baseLimit = custom ? Math.max(0, target - 1) : target;
  const contentLimit = target >= 8
    ? Math.min(4, Math.max(1, baseLimit - 2))
    : Math.min(3, Math.max(1, baseLimit - 2));
  const add = (sentence, limit = baseLimit) => {
    const value = polishIstStandSentence(completeAnchorSentence(sentence));
    if (!value) return;
    if (sentences.some((existing) => normalizeMatchValue(existing) === normalizeMatchValue(value))) return;
    if (sentences.length < limit) sentences.push(value);
  };
  add(main[0], contentLimit);
  if (target >= 7) add(main[1], contentLimit);
  add(concrete[0], contentLimit);
  if (target >= 6) add(concrete[1], contentLimit);
  add(condition[0]);
  add(perspective[0]);
  if (target >= 8 && sentences.length < 6) add(perspective[1]);
  if (custom) {
    const value = completeAnchorSentence(custom);
    if (value && !sentences.some((existing) => normalizeMatchValue(existing) === normalizeMatchValue(value))) {
      sentences.push(value);
    }
  }
  return removeRepeatedSentences(sentences).slice(0, target);
}

function targetIstStandSentenceLimitForChains(chains = []) {
  const active = activeSupportChainsForIstStand(chains);
  if (active.length <= 2) return 4;
  if (active.length <= 4) return 5;
  return 6;
}

function smoothCompetenceIstStandSentences(area, sentences = [], chains = []) {
  const target = targetIstStandSentenceLimitForChains(chains);
  const cleaned = removeGradeBandReferencesFromIstStandSentences(sentences)
    .map(completeAnchorSentence)
    .map(polishIstStandSentence)
    .filter(Boolean);
  return reduceIstStandRepetitions(cleaned, target);
}

function istStandSentenceFamilies(sentence = "") {
  const text = normalizeMatchValue(sentence);
  const families = new Set();
  const addIf = (family, pattern) => {
    if (pattern.test(text)) families.add(family);
  };
  addIf("new-content", /\b(neue?|unbekannt|ungewohnt|verändert|offen)\b/);
  addIf("content", /\b(inhalt|inhalte|lerninhalte|anforderung|anforderungen|aufgabe|aufgaben)\b/);
  addIf("strategies", /\b(strateg|vorgehensweise|lösungsweg|verfahren)\b/);
  addIf("support", /\b(unterstütz|hilfe|hilfen|begleitung|orientierung|anleitung|impuls|rückmeldung)\b/);
  addIf("repetition", /\b(wiederhol|abruf|übung|üben|geübt|sichern|gesichert)\b/);
  addIf("visual-structure", /\b(visualis|sichtbar|struktur|schritt|karte|symbol|markier|checkliste)\b/);
  addIf("uncertainty", /\b(unsicher|nicht sicher|nicht durchgängig|fällt schwer|erschwer|verliert|gehen verloren)\b/);
  addIf("need", /\b(benötigt|braucht|muss|müssen|angewiesen)\b/);
  addIf("development", /\b(zunehmend|schrittweise|sicherer|besser|leichter)\b/);
  addIf("material", /\b(material|beispiel|darstellung|bild|tabelle|zahlenstrahl|zehnerfeld)\b/);
  return families;
}

function istStandSentenceOverlapScore(left = new Set(), right = new Set()) {
  return [...left].filter((family) => right.has(family)).length;
}

function sentenceIsIstStandIntro(sentence = "") {
  return /^(?:Im Bereich|Im Fach|Im Unterricht|Im Lern-|Beim|Bei)\b/.test(String(sentence || "").trim());
}

function sentenceIsCustomObservation(sentence = "") {
  return /^Eigene Unterrichtsbeobachtung:/i.test(String(sentence || "").trim());
}

function istStandWorkAutonomyOverlap(left = "", right = "") {
  const normalize = (value) => normalizeMatchValue(value)
    .replace(/\beigenständig\w*/g, "selbstständig")
    .replace(/\bselbständig\w*/g, "selbstständig");
  const first = normalize(left);
  const second = normalize(right);
  const workPattern = /\b(aufgabenbeginn|bearbeitung|arbeitsschritt|arbeitsverhalten|arbeitsaufgabe|aufgabe|aufgaben)\b/;
  const autonomyPattern = /\b(selbstständig|orientierung|start|ansatz|ansätze|fortführen|beginnt|einstieg)\b/;
  return workPattern.test(first) && workPattern.test(second)
    && autonomyPattern.test(first) && autonomyPattern.test(second);
}

function reduceIstStandRepetitions(sentences = [], target = 6) {
  const cleaned = removeBlockedIstStandStarts(sentences);
  if (cleaned.length <= 2) return cleaned.slice(0, target);
  const introIndex = cleaned.findIndex(sentenceIsIstStandIntro);
  const ordered = introIndex > 0
    ? [cleaned[introIndex], ...cleaned.filter((_, index) => index !== introIndex)]
    : cleaned;
  const selected = [];
  const familyCounts = new Map();
  const addSentence = (sentence, relaxed = false) => {
    const value = completeAnchorSentence(sentence);
    if (!value || selected.some((existing) => normalizeMatchValue(existing) === normalizeMatchValue(value))) return false;
    if (selected.length >= target) return false;
    const families = istStandSentenceFamilies(value);
    const isCustom = sentenceIsCustomObservation(value);
    const repeatedFamilies = [...families].filter((family) => (familyCounts.get(family) || 0) >= 2);
    const contentFamilies = new Set(["new-content", "content", "strategies", "support", "repetition", "visual-structure"]);
    const tooSimilar = selected.some((existing) => {
	    const existingFamilies = istStandSentenceFamilies(existing);
	    const overlap = istStandSentenceOverlapScore(families, existingFamilies);
	    const sharesContent = [...families].some((family) => contentFamilies.has(family) && existingFamilies.has(family));
	    return overlap >= 3 || (overlap >= 2 && sharesContent) || istStandWorkAutonomyOverlap(value, existing);
	  });
    if (!relaxed && !isCustom && (tooSimilar || (selected.length >= 2 && repeatedFamilies.length >= 1))) {
      return false;
    }
    selected.push(value);
    families.forEach((family) => familyCounts.set(family, (familyCounts.get(family) || 0) + 1));
    return true;
  };

  ordered.forEach((sentence) => addSentence(sentence));
  if (selected.length < Math.min(3, target)) {
    ordered.forEach((sentence) => addSentence(sentence, true));
  }
  return selected.slice(0, target);
}

