const observationConditionPatterns = [
  { pattern: /wiederhol|visualis|strategiekarte|merkhilfe|symbol|abruf/i, text: "Wiederholungen, Visualisierungen, Strategiekarten und kurze Abrufübungen" },
  { pattern: /start|arbeitsschritt|startimpuls|checkliste|arbeitsauftrag/i, text: "klare Startimpulse, sichtbare Arbeitsschritte und kurze Rückmeldungen" },
  { pattern: /silbe|laut|buchstabe|markier|lese|schreib|wort/i, text: "Markierungen, wiederholtes Üben und übersichtliches Wort- oder Textmaterial" },
  { pattern: /material|zahlenstrahl|zehnerfeld|rechenrahmen|plättchen|darstellung/i, text: "strukturiertes Material und sichtbar gemachte Rechenwege" },
  { pattern: /bild|wortkarte|satzmuster|visualis|sprache|begriff/i, text: "Bildmaterial, Wortkarten, Satzmuster und wiederholte Anwendungssituationen" },
  { pattern: /ruhig|regel|konflikt|gefühl|begleitung|rolle/i, text: "ruhige Begleitung, klare Absprachen und vorhersehbare Abläufe" }
];

function topicDisplayName(topic = "") {
  const speechTopic = canonicalSpeechCompetenceTopic(topic);
  if (speechCompetenceTopics.includes(speechTopic) && speechTermMode() !== "plain") {
    return speechTopicDisplayName(speechTopic);
  }
  return competenceTopicDisplayAliases[topic] || topic;
}

function topicPhrase(topic = "") {
  const speechTopic = canonicalSpeechCompetenceTopic(topic);
  if (speechCompetenceTopics.includes(speechTopic) && speechTermMode() !== "plain") {
    return speechTopicPhrase(speechTopic);
  }
  return competenceTopicPhraseAliases[topic] || `bei ${topicDisplayName(topic)}`;
}

function joinGermanList(items = []) {
  const clean = items.map((item) => String(item || "").trim()).filter(Boolean);
  if (!clean.length) return "";
  if (clean.length === 1) return clean[0];
  return `${clean.slice(0, -1).join(", ")} und ${clean[clean.length - 1]}`;
}

function selectedSpeechTopicsFromEntries(entries = []) {
  const topics = [...new Set((entries || [])
    .filter((entry) => entry.rating !== "nicht einschätzbar")
    .map((entry) => canonicalSpeechCompetenceTopic(entry.topic))
    .filter((topic) => speechCompetenceTopics.includes(topic)))];
  return topics.sort((left, right) =>
    speechCompetenceTopics.indexOf(left) - speechCompetenceTopics.indexOf(right)
  );
}

function applySpeechTermDisplayToText(value, mode = speechTermMode()) {
  const normalizedMode = normalizeSpeechTermDisplayMode(mode);
  if (normalizedMode === "plain") return String(value || "");
  let text = String(value || "");
  speechCompetenceTopics.forEach((topic) => {
    const phrase = speechTopicPhrase(topic, normalizedMode);
    const phraseUpper = capitalizeFirst(phrase);
    const legacyPhrase = competenceTopicPhraseAliases[topic] || "";
    text = text
      .replaceAll(`Im Bereich ${topic}`, phraseUpper)
      .replaceAll(`im Bereich ${topic}`, phrase)
      .replaceAll(`Bei ${topic}`, phraseUpper)
      .replaceAll(`bei ${topic}`, phrase);
    if (legacyPhrase && legacyPhrase !== phrase) {
      text = text
        .replaceAll(capitalizeFirst(legacyPhrase), phraseUpper)
        .replaceAll(legacyPhrase, phrase);
    }
  });
  return text;
}

function applySpeechTermDisplayToSuggestion(suggestion, entries = [], mode = speechTermMode()) {
  const normalizedMode = normalizeSpeechTermDisplayMode(mode);
  if (normalizedMode === "plain") return suggestion;
  const keepPilotIstStand = Boolean(suggestion?._meta?.pilotIstStandPattern);
  const topics = selectedSpeechTopicsFromEntries(entries);
  const visibleTopics = topics.map((topic) => speechTopicDisplayName(topic, normalizedMode));
  const labelList = visibleTopics.length > 4
    ? `${joinGermanList(visibleTopics.slice(0, 4))} sowie weitere Sprachbereiche`
    : joinGermanList(visibleTopics);
  const nextSuggestion = {
    ...suggestion,
    istStand: keepPilotIstStand ? suggestion.istStand : applySpeechTermDisplayToText(suggestion.istStand, normalizedMode),
    ziele: applySpeechTermDisplayToText(suggestion.ziele, normalizedMode),
    massnahmen: applySpeechTermDisplayToText(suggestion.massnahmen, normalizedMode),
    evaluation: applySpeechTermDisplayToText(suggestion.evaluation, normalizedMode)
  };
  if (keepPilotIstStand) return nextSuggestion;
  if (topics.length === 1) {
    const lead = capitalizeFirst(speechTopicPhrase(topics[0], normalizedMode));
    nextSuggestion.istStand = nextSuggestion.istStand.replace(/^Im Bereich Sprache und Kommunikation\b/, lead);
  } else if (topics.length > 1 && labelList) {
    nextSuggestion.istStand = nextSuggestion.istStand.replace(
      /^Im Bereich Sprache und Kommunikation\b/,
      `Im Bereich Sprache und Kommunikation (${labelList})`
    );
  }
  return nextSuggestion;
}

function competenceSummaryItems(chains = [], rating) {
  return chains
    .filter((chain) => chain.rating === rating)
    .map((chain) => topicPhrase(chain.composerTopic || chain.kompetenz))
    .filter(Boolean);
}

function allObservationTextsForChains(chains = []) {
  return chains.flatMap((chain) => {
    const details = normalizeCompetenceObservationEntry(chain.observationDetails);
    return [...details.selected, details.custom].map((text) => String(text || "").trim()).filter(Boolean);
  });
}

function selectConditionFromObservations(area, observations = []) {
  const combined = observations.join(" ");
  const matches = observationConditionPatterns
    .filter((entry) => entry.pattern.test(combined))
    .map((entry) => entry.text);
  return removeRepeatedSentences(matches)[0] || areaIstStandContexts[area]?.conditionPrefix || "klare Struktur und wiederkehrende Orientierung";
}

function normalizeObservationForIstStand(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";
  return raw
    .replace(/^_ /, "")
    .replace(/^#er\/sie# /i, "")
    .replace(/^#Er\/Sie# /, "")
    .replace(/[.!?]+$/, "");
}

function observationSituationSentence(area, activeChains = []) {
  const observations = allObservationTextsForChains(activeChains).map(normalizeObservationForIstStand).filter(Boolean);
  const custom = activeChains
    .map((chain) => normalizeCompetenceObservationEntry(chain.observationDetails).custom.trim())
    .find(Boolean);
  if (custom) {
    return `In der Unterrichtsbeobachtung zeigt sich: ${completeAnchorSentence(custom)}`;
  }
  const selected = removeRepeatedSentences(observations)
    .filter((item) => !/unterstütz|hilf|erleichter|orientierung|visualis|wiederhol|strategiekarte|merkhilfe/i.test(item))
    .slice(0, 2);
  if (!selected.length) return "";
  return `Konkret zeigt sich: ${selected.map(completeAnchorSentence).join(" ")}`;
}

function resourceSentenceFromCompetenceData(area, secured = [], partial = []) {
  const resources = secured.length ? secured.slice(0, 2) : partial.slice(0, 1);
  if (!resources.length) return "";
  const context = areaIstStandContexts[area] || areaIstStandContexts["Weitere Fächer"];
  if (secured.length) {
    return `${context.intro} zeigt _ ${joinGermanList(resources)} bereits sichere Ansätze.`;
  }
  return `In vertrauten Situationen zeigen sich ${joinGermanList(resources)} bereits erste Ansätze.`;
}

function supportSentenceFromCompetenceData(area, uncertain = [], partial = []) {
  const context = areaIstStandContexts[area] || areaIstStandContexts["Weitere Fächer"];
  const priority = [...uncertain.slice(0, 2), ...partial.slice(0, 2)].slice(0, 3);
  if (!priority.length) return "";
  if (uncertain.length && partial.length) {
    return `${context.intro} ${context.supportVerb}. Die Sicherheit ist besonders ${joinGermanList(uncertain.slice(0, 2))} noch eingeschränkt. Erste Ansätze zeigen sich ${joinGermanList(partial.slice(0, 2))}.`;
  }
  if (uncertain.length) {
    return `${context.intro} ${context.supportVerb}. Die Sicherheit ist besonders ${joinGermanList(priority)} noch eingeschränkt.`;
  }
  return `${context.intro} zeigen sich ${joinGermanList(priority)} noch Unsicherheiten.`;
}

function competenceRecordsForIstStand(entries = [], selectedChains = [], area = "") {
  return entries
    .map((entry) => {
      const matching = selectedChains.find((chain) =>
        normalizeMatchValue(chain.composerTopic || chain.kompetenz) === normalizeMatchValue(entry.topic)
        && chain.rating === entry.rating
      );
      return {
        ...(matching || {}),
        bereich: matching?.bereich || area,
        kompetenz: matching?.kompetenz || entry.topic,
        composerTopic: matching?.composerTopic || entry.topic,
        gruppe: matching?.gruppe || entry.topic,
        rating: entry.rating,
        observation: matching?.observation || entry.observation || "",
        observationDetails: matching?.observationDetails || entry.observationDetails || { selected: [], custom: "", relatedRating: "" }
      };
    })
    .filter((record) => competenceRatingOptions.includes(record.rating) && record.rating !== "nicht einschätzbar");
}

function buildCompetenceBasedIstStandSentences({ area, gradeBand, selectedChains = [], variantOffset = 0 }) {
  const activeChains = activeSupportChainsForIstStand(selectedChains);
  if (!selectedChains.length) return [];
  if (!activeChains.length) {
    const secured = competenceSummaryItems(selectedChains, "gesichert");
    return secured.length
      ? [`${areaIstStandContexts[area]?.intro || "Im ausgewählten Bereich"} zeigt _ bei ${joinGermanList(secured.slice(0, 3))} sichere Kompetenzen.`]
      : [];
  }
  if (area === "Sprache / Kommunikation") {
    const categories = distributedSpeechObservationCategories(activeChains, 4);
    const custom = activeChains
      .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
      .find(Boolean);
    const target = speechIstStandTargetLength(activeChains.length) + (custom ? 1 : 0);
    const synthesized = speechSynthesizedIstStandSentences(categories, custom, variantOffset, target);
    if (synthesized.length) return synthesized;
  }
  const secured = competenceSummaryItems(selectedChains, "gesichert");
  const partial = competenceSummaryItems(activeChains, "teilweise unsicher");
  const uncertain = competenceSummaryItems(activeChains, "unsicher");
  const observations = allObservationTextsForChains(activeChains);
  const condition = selectConditionFromObservations(area, observations);
  const context = areaIstStandContexts[area] || areaIstStandContexts["Weitere Fächer"];
  const target = compactComposerIstStandTargetLength(activeChains);
  const sentences = [
    resourceSentenceFromCompetenceData(area, secured, uncertain.length ? [] : partial),
    supportSentenceFromCompetenceData(area, uncertain, partial),
    observationSituationSentence(area, activeChains),
    condition ? `${capitalizeFirst(condition)} geben #ihm/ihr# Orientierung.` : "",
    context.perspective
  ].filter(Boolean);
  return reduceIstStandRepetitions(sentences, target);
}

function removeGradeBandReferencesFromIstStandSentences(sentences = []) {
  return sentences
    .map((sentence) => String(sentence || "")
      .replace(/\s+auf dem Niveau Klasse\s+[0-9/]+/gi, "")
      .replace(/\bKlasse\s+[0-9/]+\s*·\s*/gi, "")
      .replace(/\s{2,}/g, " ")
      .trim())
    .filter(Boolean);
}

function compactTopicMarker(topic = "") {
  return normalizeMatchValue(String(topic || "")
    .replace(/^beim\s+/i, "")
    .replace(/^bei\s+der\s+/i, "")
    .replace(/^bei\s+dem\s+/i, "")
    .replace(/^bei\s+/i, "")
    .replace(/^beim Nutzen von\s+/i, "")
    .replace(/^beim Behalten\s+/i, ""));
}

function coverageMarkersForCompetenceTopic(topic = "", phrase = "") {
  const markers = {
    "Wörter lesen": ["wort", "erlesen", "lese"],
    "Lautgetreues Schreiben": ["lautgetreu", "laut", "verschrift"],
    Rechenstrategien: ["rechenstrateg"],
    Sachaufgaben: ["sachaufgab"],
    Aufgabenbeginn: ["aufgabenbeginn", "ersterarbeitsschritt", "einstieg"],
    Selbstständigkeit: ["selbststandig", "eigenstandig"],
    Merkfähigkeit: ["neueinhalt", "behalten", "merk"],
    Strategien: ["strategie"]
  };
  return [
    ...(markers[topic] || []),
    compactTopicMarker(phrase),
    compactTopicMarker(topic)
  ].map(normalizeMatchValue).filter(Boolean);
}

function ensureIstStandCoversActiveCompetenceNeeds(sentences = [], selectedChains = []) {
  const activeChains = activeSupportChainsForIstStand(selectedChains);
  if (!sentences.length || !activeChains.length) return sentences;
  const combined = normalizeMatchValue(sentences.join(" "));
  const missing = activeChains
    .map((chain) => ({
      rating: chain.rating,
      topic: chain.composerTopic || chain.kompetenz,
      phrase: topicPhrase(chain.composerTopic || chain.kompetenz),
      markers: coverageMarkersForCompetenceTopic(chain.composerTopic || chain.kompetenz, topicPhrase(chain.composerTopic || chain.kompetenz))
    }))
    .filter((item) => item.markers.length && !item.markers.some((marker) => combined.includes(marker)))
    .slice(0, 2);
  if (!missing.length) return sentences;
  const asGrammaticalAreaPhrase = (phrase = "") => String(phrase || "")
    .replace(/^beim\s+/i, "im ")
    .replace(/^bei der\s+/i, "in der ")
    .replace(/^bei dem\s+/i, "in dem ")
    .replace(/^bei\s+/i, "im Bereich ");
  const uncertain = missing.filter((item) => item.rating === "unsicher").map((item) => asGrammaticalAreaPhrase(item.phrase));
  const partial = missing.filter((item) => item.rating === "teilweise unsicher").map((item) => asGrammaticalAreaPhrase(item.phrase));
  const additions = [
    uncertain.length ? `Die Sicherheit ist außerdem ${joinGermanList(uncertain)} noch eingeschränkt.` : "",
    partial.length ? `Auch ${joinGermanList(partial)} zeigen sich erste Ansätze, die noch gefestigt werden müssen.` : ""
  ].filter(Boolean);
  return [
    sentences[0],
    ...additions,
    ...sentences.slice(1)
  ];
}

function removeBlockedIstStandStarts(sentences = []) {
  const blockedStarts = new Set(blockedIstStandStarts.map((sentence) => normalizeMatchValue(sentence)));
  return removeRepeatedSentences(sentences.map(completeAnchorSentence).filter(Boolean))
    .filter((sentence, index) => index !== 0 || !blockedStarts.has(normalizeMatchValue(sentence)));
}

function activeSupportChainsForIstStand(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.rating === "teilweise unsicher" || chain.rating === "unsicher"
  ));
}

function firstCustomObservationSentenceForChains(chains = []) {
  return activeSupportChainsForIstStand(chains)
    .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
    .find(Boolean) || "";
}

function shapeGeneralIstStandSentences(sentences = [], selectedChains = [], area = "") {
  const active = activeSupportChainsForIstStand(selectedChains);
  const target = compactComposerIstStandTargetLength(active);
  if (!target) return removeBlockedIstStandStarts(sentences);

  const custom = firstCustomObservationSentenceForChains(active);
  const condition = helpfulCompetenceConditions[area] || "";
  const perspective = developmentPerspectiveByArea[area] || "";
  const tailSentences = [condition, perspective].filter(Boolean);
  const baseLimit = Math.max(1, target - (custom ? 1 : 0) - tailSentences.length);
  const shaped = [];
  const add = (sentence, limit = baseLimit) => {
    const value = completeAnchorSentence(sentence);
    if (!value || shaped.length >= limit) return;
    if (shaped.some((existing) => normalizeMatchValue(existing) === normalizeMatchValue(value))) return;
    shaped.push(value);
  };

  removeBlockedIstStandStarts(sentences).forEach((sentence) => add(sentence));
  tailSentences.forEach((sentence) => add(sentence, custom ? target - 1 : target));

  if (custom) {
    const value = completeAnchorSentence(custom);
    if (value && !shaped.some((existing) => normalizeMatchValue(existing) === normalizeMatchValue(value))) {
      shaped.push(value);
    }
  }
  return removeRepeatedSentences(shaped).slice(0, target);
}

function activeEmotionalChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.rating === "teilweise unsicher" || chain.rating === "unsicher"
  ));
}

function emotionalIstStandTargetLength(activeCount) {
  if (activeCount <= 1) return 5;
  if (activeCount === 2) return 5;
  return 6;
}

function distributedEmotionalObservationAnchors(chains = [], max = 3, variantOffset = 0) {
  const active = activeEmotionalChains(chains).filter((chain) =>
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.length
  );
  const selected = [];
  let round = 0;
  while (selected.length < max && round < 5) {
    let addedInRound = false;
    active.forEach((chain) => {
      if (selected.length >= max) return;
      const details = normalizeCompetenceObservationEntry(chain.observationDetails);
      const observation = details.selected[round];
      if (!observation) return;
      selected.push({
        chain,
        observation,
        anchor: emotionalObservationAnchor(observation, variantOffset, selected.length)
      });
      addedInRound = true;
    });
    if (!addedInRound) break;
    round += 1;
  }
  return selected;
}

const emotionalTopicCategories = {
  "Emotionsregulation": "regulation",
  "Frustrationstoleranz": "frustration",
  "Konfliktverhalten": "conflict",
  "Kontaktverhalten": "contact",
  "Regelverhalten": "rules",
  "Kooperationsverhalten": "cooperation"
};

const emotionalCategoryPriority = ["regulation", "frustration", "conflict", "contact", "rules", "cooperation"];

function emotionalCategoryForText(text = "", fallbackTopic = "") {
  const normalized = normalizeMatchValue(text);
  if (/beruhig|belast|anspann|gefühl|wut|traurig|angst|enttäusch|ampel|skala|rückkehr|ruhe|pause/.test(normalized)) {
    return "regulation";
  }
  if (/fehler|misserfolg|frustration|schwierigkeit|abbruch|ärger|rückzug|teilschritt|weiterarbeit/.test(normalized)) {
    return "frustration";
  }
  if (/konflikt|streit|stopp|gespräch|sichtweise|zuhören|klärung/.test(normalized)) {
    return "conflict";
  }
  if (/kontakt|soziale|vertraut|gesprächsanfang/.test(normalized)) {
    return "contact";
  }
  if (/regel|erinner|übergang|konsequenz|visualisiert/.test(normalized)) {
    return "rules";
  }
  if (/partner|gruppe|rolle|absprache|kooperativ|materialteilen|warten/.test(normalized)) {
    return "cooperation";
  }
  return emotionalTopicCategories[fallbackTopic] || "";
}

function emotionalCategorySet(active = [], distributed = []) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  distributed.forEach(({ chain, observation }) =>
    add(emotionalCategoryForText(observation, chain?.composerTopic || chain?.kompetenz))
  );
  active.forEach((chain) => add(emotionalTopicCategories[chain.composerTopic || chain.kompetenz]));
  return emotionalCategoryPriority.filter((category) => categories.includes(category));
}

function emotionalBundleKey(categories = []) {
  const has = (category) => categories.includes(category);
  if (has("regulation") && has("frustration") && has("conflict")) return "regulation-frustration-conflict";
  if (has("regulation") && has("conflict")) return "regulation-conflict";
  if (has("regulation") && has("frustration")) return "regulation-frustration";
  if (has("frustration") && has("conflict")) return "frustration-conflict";
  if (has("contact") && has("cooperation")) return "contact-cooperation";
  if (has("rules") && has("cooperation")) return "rules-cooperation";
  if (has("contact") && has("conflict")) return "contact-conflict";
  return categories[0] || "general";
}

