function pickEmotionalBundle(map, key, variantOffset = 0, index = 0) {
  const variants = map[key] || map.general || [];
  return pickCompleteVariant("", variants, variantOffset, index);
}

function emotionalObservationIstStandSentencesForChains(chains = [], variantOffset = 0, composedSentences = []) {
  const active = activeEmotionalChains(chains);
  const target = compactComposerIstStandTargetLength(active);
  const distributed = distributedEmotionalObservationAnchors(active, 3, variantOffset);
  const categories = emotionalCategorySet(active, distributed);
  const key = emotionalBundleKey(categories);

  const mainNeed = pickEmotionalBundle(emotionalMainNeedBundles, key, variantOffset, 0)
    || firstUniqueSentence(composedSentences || []);
  const custom = active
    .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
    .find(Boolean);
  return layeredObservationIstStandSentences({
    target,
    main: removeRepeatedSentences([
      mainNeed,
      ...completeBundleVariants(emotionalMainNeedBundles, key, variantOffset),
      ...composedSentences
    ]),
    concrete: removeRepeatedSentences([
      ...completeBundleVariants(emotionalConcreteBundles, key, variantOffset),
      ...distributed.map(({ anchor }) => anchor.istStand)
    ]),
    condition: removeRepeatedSentences([
      ...completeBundleVariants(emotionalConditionBundles, key, variantOffset),
      ...distributed.map(({ anchor }) => anchor.bedingung),
      ...active.map((chain) => emotionalTopicFrame(chain.composerTopic || chain.kompetenz).bedingung)
    ]),
    custom,
    perspective: removeRepeatedSentences([
      ...completeBundleVariants(emotionalPerspectiveBundles, key, variantOffset),
      ...distributed.map(({ anchor }) => anchor.entwicklung),
      ...active.map((chain) => emotionalTopicFrame(chain.composerTopic || chain.kompetenz).entwicklung)
    ])
  });
}

const learningCategoryPriority = ["start", "attention", "endurance", "independence", "organization"];
const speechCategoryPriority = [
  "articulation",
  "phonology",
  "understanding",
  "vocabulary",
  "sentence",
  "narration",
  "conversation",
  "voice",
  "fluency"
];

function activeLearningChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.bereich === "Lern- und Leistungsverhalten"
    && (chain.rating === "teilweise unsicher" || chain.rating === "unsicher")
  ));
}

function distributedLearningObservationCategories(chains = [], max = 3) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  activeLearningChains(chains).forEach((chain) => {
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.slice(0, max).forEach((observation) =>
      add(learningCategoryForText(observation, chain.composerTopic || chain.kompetenz))
    );
  });
  activeLearningChains(chains).forEach((chain) =>
    add(learningTopicCategories[chain.composerTopic || chain.kompetenz])
  );
  return learningCategoryPriority.filter((category) => categories.includes(category)).slice(0, max);
}

function learningBundleKey(categories = []) {
  const has = (category) => categories.includes(category);
  if (has("start") && has("attention") && has("independence")) return "start-attention-independence";
  if (has("start") && has("attention")) return "start-attention";
  if (has("start") && has("independence")) return "start-independence";
  if (has("attention") && has("endurance")) return "attention-endurance";
  if (has("attention") && has("independence")) return "attention-independence";
  if (has("organization") && has("independence")) return "organization-independence";
  return categories[0] || "general";
}

