function pickLearningBundle(map, key, variantOffset = 0, index = 0) {
  const variants = map[key] || map.general || [];
  return pickCompleteVariant("", variants, variantOffset, index);
}

function learningIstStandTargetLength(activeCount) {
  if (activeCount <= 1) return 3;
  if (activeCount === 2) return 4;
  return 5;
}

function learningObservationIstStandSentencesForChains(chains = [], variantOffset = 0) {
  const active = activeLearningChains(chains);
  if (!active.length) return [];
  const categories = distributedLearningObservationCategories(active, 3);
  const key = learningBundleKey(categories);
  const target = compactComposerIstStandTargetLength(active);
  const custom = active
    .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
    .find(Boolean);
  return layeredObservationIstStandSentences({
    target,
    main: completeBundleVariants(learningMainNeedBundles, key, variantOffset),
    concrete: completeBundleVariants(learningConcreteBundles, key, variantOffset),
    condition: completeBundleVariants(learningConditionBundles, key, variantOffset),
    custom,
    perspective: completeBundleVariants(learningPerspectiveBundles, key, variantOffset)
  });
}

function activeSpeechChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.bereich === "Sprache / Kommunikation"
    && (chain.rating === "teilweise unsicher" || chain.rating === "unsicher")
  ));
}

function distributedSpeechObservationCategories(chains = [], max = 3) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  activeSpeechChains(chains).forEach((chain) => {
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.slice(0, max).forEach((observation) =>
      add(speechCategoryForText(observation, chain.composerTopic || chain.kompetenz))
    );
  });
  activeSpeechChains(chains).forEach((chain) =>
    add(speechTopicCategories[chain.composerTopic || chain.kompetenz])
  );
  return speechCategoryPriority.filter((category) => categories.includes(category)).slice(0, max);
}

function speechBundleKey(categories = []) {
  const has = (category) => categories.includes(category);
  if (has("understanding") && has("vocabulary") && has("sentence")) return "understanding-vocabulary-sentence";
  if (has("understanding") && has("vocabulary")) return "understanding-vocabulary";
  if (has("understanding") && has("sentence")) return "understanding-sentence";
  if (has("vocabulary") && has("sentence")) return "vocabulary-sentence";
  if (has("sentence") && has("conversation")) return "sentence-conversation";
  if (has("vocabulary") && has("conversation")) return "vocabulary-conversation";
  return categories[0] || "general";
}

