function perceptionTopicOrderIndex(topic = "") {
  const canonical = canonicalPerceptionCompetenceTopic(topic);
  const index = perceptionCompetenceTopics.indexOf(canonical);
  return index >= 0 ? index : 999;
}

function sortedPerceptionChainsByTopic(chains = []) {
  const ratingWeight = { unsicher: 2, "teilweise unsicher": 1 };
  return activePerceptionChains(chains).sort((left, right) =>
    perceptionTopicOrderIndex(left.composerTopic || left.kompetenz) - perceptionTopicOrderIndex(right.composerTopic || right.kompetenz)
    || (ratingWeight[right.rating] || 0) - (ratingWeight[left.rating] || 0)
  );
}

function perceptionObservationSentencesForTopic(chain, limit = 2) {
  const details = normalizeCompetenceObservationEntry(chain.observationDetails);
  const selected = removeRepeatedSentences(details.selected.map(cleanSuggestionSentence).filter(Boolean));
  const custom = customObservationSentence(details.custom);
  return [
    ...selected.slice(0, limit),
    custom
  ].filter(Boolean);
}

function perceptionTopicParagraph(chain, variantOffset = 0, index = 0, total = 1) {
  const topic = canonicalPerceptionCompetenceTopic(chain.composerTopic || chain.kompetenz);
  const intro = perceptionTopicIstStandIntros[topic]
    || `Im Bereich ${topicDisplayName(topic)} zeigt sich noch Unterstützungsbedarf.`;
  const observations = perceptionObservationSentencesForTopic(chain, total > 3 ? 1 : 2)
    .filter((sentence) => normalizeMatchValue(sentence) !== normalizeMatchValue(intro));
  const condition = perceptionTopicConditionSentences[topic] || "";
  const body = observations.length
    ? observations.slice(0, total > 3 ? 1 : 2)
    : condition
      ? [condition]
      : [];
  return removeRepeatedSentences([intro, ...body].map(completeAnchorSentence).filter(Boolean)).join(" ");
}

function perceptionObservationIstStandSentencesForChains(chains = [], variantOffset = 0) {
  const active = activePerceptionChains(chains);
  if (!active.length) return [];
  const ordered = sortedPerceptionChainsByTopic(active);
  return ordered
    .map((chain, index) => perceptionTopicParagraph(chain, variantOffset, index, ordered.length))
    .filter(Boolean);
}

const cognitionCategoryPriority = ["memory", "strategies", "problem", "transfer"];

function activeCognitionChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.bereich === "Kognition"
    && (chain.rating === "teilweise unsicher" || chain.rating === "unsicher")
  ));
}

function distributedCognitionObservationCategories(chains = [], max = 3) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  activeCognitionChains(chains).forEach((chain) => {
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.slice(0, max).forEach((observation) =>
      add(cognitionCategoryForText(observation, chain.composerTopic || chain.kompetenz))
    );
  });
  activeCognitionChains(chains).forEach((chain) =>
    add(cognitionTopicCategories[chain.composerTopic || chain.kompetenz])
  );
  return cognitionCategoryPriority.filter((category) => categories.includes(category)).slice(0, max);
}

function cognitionBundleKey(categories = []) {
  const has = (category) => categories.includes(category);
  if (has("memory") && has("strategies") && has("transfer")) return "memory-strategies-transfer";
  if (has("memory") && has("strategies")) return "memory-strategies";
  if (has("memory") && has("transfer")) return "memory-transfer";
  if (has("strategies") && has("problem")) return "strategies-problem";
  if (has("strategies") && has("transfer")) return "strategies-transfer";
  if (has("problem") && has("transfer")) return "problem-transfer";
  return categories[0] || "general";
}

