function pickCognitionBundle(map, key, variantOffset = 0, index = 0) {
  const variants = map[key] || map.general || [];
  return pickCompleteVariant("", variants, variantOffset, index);
}

function cognitionIstStandTargetLength(activeCount) {
  if (activeCount <= 1) return 3;
  if (activeCount === 2) return 4;
  return 5;
}

function cognitionObservationIstStandSentencesForChains(chains = [], variantOffset = 0) {
  const active = activeCognitionChains(chains);
  if (!active.length) return [];
  const categories = distributedCognitionObservationCategories(active, 3);
  const key = cognitionBundleKey(categories);
  const target = compactComposerIstStandTargetLength(active);
  const custom = active
    .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
    .find(Boolean);
  return layeredObservationIstStandSentences({
    target,
    main: completeBundleVariants(cognitionMainNeedBundles, key, variantOffset),
    concrete: completeBundleVariants(cognitionConcreteBundles, key, variantOffset),
    condition: completeBundleVariants(cognitionConditionBundles, key, variantOffset),
    custom,
    perspective: completeBundleVariants(cognitionPerspectiveBundles, key, variantOffset)
  });
}

const germanCategoryPriority12 = ["reading-basic", "reading-comprehension", "phonetic-writing", "copy-control", "spelling-basic", "sentence-writing"];
const germanCategoryPriority34 = ["reading-fluency", "text-comprehension", "reading-strategy", "text-writing", "spelling-strategy", "grammar", "text-control"];

function activeGermanChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.bereich === "Deutsch"
    && (chain.rating === "teilweise unsicher" || chain.rating === "unsicher")
  ));
}

function distributedGermanObservationCategories(chains = [], gradeBand = gradeBandForPlan(), max = 3) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  activeGermanChains(chains).forEach((chain) => {
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.slice(0, max).forEach((observation) =>
      add(germanCategoryForText(observation, chain.composerTopic || chain.kompetenz, gradeBand))
    );
  });
  activeGermanChains(chains).forEach((chain) =>
    add(germanTopicCategoriesForGrade(gradeBand)[chain.composerTopic || chain.kompetenz])
  );
  const priority = gradeBand === "Klasse 3/4" ? germanCategoryPriority34 : germanCategoryPriority12;
  return priority.filter((category) => categories.includes(category)).slice(0, max);
}

function germanBundleKey(categories = [], gradeBand = gradeBandForPlan()) {
  const has = (category) => categories.includes(category);
  if (gradeBand === "Klasse 3/4") {
    if (has("reading-fluency") && has("text-comprehension") && has("spelling-strategy")) return "fluency-comprehension-spelling";
    if (has("reading-fluency") && has("text-comprehension")) return "fluency-comprehension";
    if (has("text-comprehension") && has("reading-strategy")) return "comprehension-strategy";
    if (has("text-writing") && has("spelling-strategy")) return "textwriting-spelling";
    if (has("grammar") && has("text-control")) return "grammar-control";
  }
  if (has("reading-basic") && has("phonetic-writing") && has("copy-control")) return "reading-writing-copy";
  if (has("reading-basic") && has("phonetic-writing")) return "reading-phonetic";
  if (has("reading-basic") && has("reading-comprehension")) return "basic-comprehension";
  if (has("phonetic-writing") && has("spelling-basic")) return "writing-spelling";
  if (has("copy-control") && has("spelling-basic")) return "copy-spelling";
  if (has("sentence-writing") && has("spelling-basic")) return "sentence-spelling";
  return categories[0] || "general";
}

