function germanBundleMapForGrade(map12, map34, gradeBand = gradeBandForPlan()) {
  return gradeBand === "Klasse 3/4" ? { ...map12, ...map34 } : map12;
}

function germanObservationIstStandSentencesForChains(chains = [], gradeBand = gradeBandForPlan(), variantOffset = 0) {
  const active = activeGermanChains(chains);
  if (!active.length) return [];
  const categories = distributedGermanObservationCategories(active, gradeBand, 3);
  const key = germanBundleKey(categories, gradeBand);
  const target = compactComposerIstStandTargetLength(active);
  const custom = active
    .map((chain) => customObservationSentence(normalizeCompetenceObservationEntry(chain.observationDetails).custom))
    .find(Boolean);
  return layeredObservationIstStandSentences({
    target,
    main: completeBundleVariants(germanBundleMapForGrade(germanMainNeedBundles12, germanMainNeedBundles34, gradeBand), key, variantOffset),
    concrete: completeBundleVariants(germanConcreteBundles, key, variantOffset),
    condition: completeBundleVariants(germanConditionBundles, key, variantOffset),
    custom,
    perspective: completeBundleVariants(germanPerspectiveBundles, key, variantOffset)
  });
}

const mathCategoryPriority12 = ["number", "decomposition", "operation", "transition", "strategy", "mental", "word", "geometry", "material"];
const mathCategoryPriority34 = ["number", "place", "operation", "written", "multiplication", "strategy", "word", "measurement", "geometry", "data"];

function activeMathChains(chains = []) {
  return sortChainsBySupportNeed(chains.filter((chain) =>
    chain.bereich === "Mathematik"
    && (chain.rating === "teilweise unsicher" || chain.rating === "unsicher")
  ));
}

function distributedMathObservationCategories(chains = [], gradeBand = gradeBandForPlan(), max = 3) {
  const categories = [];
  const add = (category) => {
    if (category && !categories.includes(category)) categories.push(category);
  };
  activeMathChains(chains).forEach((chain) => {
    normalizeCompetenceObservationEntry(chain.observationDetails).selected.slice(0, max).forEach((observation) =>
      add(mathCategoryForText(observation, chain.composerTopic || chain.kompetenz, gradeBand))
    );
  });
  activeMathChains(chains).forEach((chain) =>
    add(mathTopicCategoriesForGrade(gradeBand)[chain.composerTopic || chain.kompetenz])
  );
  const priority = gradeBand === "Klasse 3/4" ? mathCategoryPriority34 : mathCategoryPriority12;
  return priority.filter((category) => categories.includes(category)).slice(0, max);
}

function mathBundleKey(categories = [], gradeBand = gradeBandForPlan()) {
  const has = (category) => categories.includes(category);
  if (gradeBand === "Klasse 3/4") {
    if (has("place") && has("written") && has("word")) return "place-written-word";
    if (has("number") && has("place")) return "number-place";
    if (has("operation") && has("written")) return "operation-written";
    if (has("multiplication") && has("strategy")) return "multiplication-strategy";
    if (has("word") && has("measurement")) return "word-measurement";
    if (has("geometry") && has("data")) return "geometry-data";
  }
  if (has("number") && has("operation") && has("strategy")) return "number-operation-strategy";
  if (has("number") && has("decomposition")) return "number-decomposition";
  if (has("operation") && has("transition")) return "operation-transition";
  if (has("operation") && has("strategy")) return "operation-strategy";
  if (has("word") && has("operation")) return "word-operation";
  if (has("geometry") && has("material")) return "geometry-material";
  return categories[0] || "general";
}

