function latestDraftsByBaseId() {
  const grouped = new Map();
  loadDrafts().forEach((item) => {
    const parsed = parseVersionedPlanId(item.displayId);
    const baseId = item.baseId || parsed?.baseId || planBaseId(item) || item.displayId;
    const current = grouped.get(baseId);
    const version = Number(item.planVersion) || parsed?.version || planVersionNumber(item);
    const currentVersion = current ? Number(current.planVersion) || parseVersionedPlanId(current.displayId)?.version || planVersionNumber(current) : 0;
    if (!current || version > currentVersion || (version === currentVersion && String(item.updatedAt).localeCompare(String(current.updatedAt)) > 0)) {
      grouped.set(baseId, item);
    }
  });
  return [...grouped.entries()]
    .map(([baseId, item]) => ({ baseId, item }))
    .sort((left, right) => left.baseId.localeCompare(right.baseId, "de", { numeric: true }));
}

function idMappingRows() {
  const rows = latestDraftsByBaseId().map(({ baseId, item }) => ({
    baseId,
    versionId: item.displayId || versionedDisplayId(baseId, item.planVersion || 1),
    klasse: item.meta?.klasse || ""
  }));
  const minimumRows = 8;
  while (rows.length < minimumRows) rows.push({ baseId: "", versionId: "", klasse: "" });
  return rows;
}

