function pilotGroupEvidenceText(group) {
  return [
    ...(group.entries || []).flatMap((entry) => [
      entry.observation,
      ...(entry.selectedObservations || []),
      entry.customObservation
    ]),
    ...(group.modules || []).map((module) => normalizeTextModuleEntry(module).text)
  ].filter(Boolean).join(" ");
}

function activePilotGroups(area, entries = [], modules = [], groupDefinitions = []) {
  const normalizedEntries = entries.map((entry) => ({
    ...entry,
    topic: canonicalCompetenceTopic(area, entry.topic)
  }));
  const normalizedModules = modules.map(normalizeTextModuleEntry).filter((module) => module.text);
  return groupDefinitions.map((definition) => {
    const topicSet = new Set(definition.topics.map((topic) => canonicalCompetenceTopic(area, topic)));
    const groupEntries = normalizedEntries.filter((entry) => topicSet.has(entry.topic));
    const groupModules = normalizedModules.filter((module) =>
      topicSet.has(canonicalCompetenceTopic(area, module.topic))
    );
    return {
      ...definition,
      entries: groupEntries,
      modules: groupModules,
      topics: [...topicSet],
      evidence: pilotGroupEvidenceText({ entries: groupEntries, modules: groupModules })
    };
  }).filter((group) => group.entries.length || group.modules.length);
}

function pilotTextHas(group, pattern) {
  return pattern.test(group.evidence || "");
}

function pilotActiveTopicsForGroup(area, group) {
  return [...new Set([
    ...(group.entries || []).map((entry) => canonicalCompetenceTopic(area, entry.topic)),
    ...(group.modules || []).map((module) => canonicalCompetenceTopic(area, module.topic))
  ].filter(Boolean))];
}

