function activeSpeechPilotIstStandTopics(entries = [], modules = []) {
  const selected = new Set([
    ...entries.map((entry) => canonicalCompetenceTopic("Sprache / Kommunikation", entry.topic)),
    ...modules.map((module) => canonicalCompetenceTopic("Sprache / Kommunikation", normalizeTextModuleEntry(module).topic))
  ].filter(Boolean));
  return speechPilotIstStandTopicOrder.filter((topic) => selected.has(topic));
}

function speechSupportChainVariantsForTopic(topic = "") {
  const chainEntry = speechSupportChainLibrary[topic];
  if (!chainEntry) return [];
  return Array.isArray(chainEntry) ? chainEntry : [chainEntry];
}

function speechSupportChainForTopic(topic = "", variantOffset = 0) {
  const variants = speechSupportChainVariantsForTopic(topic);
  if (!variants.length) return null;
  const index = ((variantOffset % variants.length) + variants.length) % variants.length;
  return {
    topic,
    ...variants[index]
  };
}

function composeSpeechSupportChainIstStand(chains = []) {
  const mode = speechTermMode();
  return chains.map((chain) => {
    const heading = speechPilotIstStandHeading(chain.topic, mode);
    const text = finalizeClearIstStandText(chain.istStand || speechPilotIstStandSectionText(chain.topic, mode));
    return [heading, text].filter(Boolean).join("\n");
  }).filter(Boolean).join("\n\n");
}

function selectedSpeechSupportChains(entries = [], modules = [], variantOffset = 0) {
  return activeSpeechPilotIstStandTopics(entries, modules)
    .map((topic) => speechSupportChainForTopic(topic, variantOffset))
    .filter((chain) => chain.id);
}

function speechSupportChainSuggestion(entries = [], modules = [], variantOffset = 0) {
  const chains = selectedSpeechSupportChains(entries, modules, variantOffset);
  if (!chains.length) return null;
  return {
    chains,
    selectedTopics: chains.map((chain) => chain.topic),
    visibleTopics: chains.map((chain) => speechPilotIstStandHeading(chain.topic)),
    suggestion: {
      istStand: composeSpeechSupportChainIstStand(chains),
      ziele: formatGoalListWithIntro(chains.map((chain) => chain.ziele)),
      massnahmen: chains.map((chain) => bulletSuggestion(chain.massnahmen)).join("\n"),
      evaluation: formatEvaluationList(chains.map((chain) => chain.evaluation))
    }
  };
}

function speechPilotIstStandHeading(topic, mode = speechTermMode()) {
  const normalizedMode = normalizeSpeechTermDisplayMode(mode);
  return speechPilotIstStandHeadings[topic]?.[normalizedMode] || speechTopicDisplayName(topic, normalizedMode);
}

function speechPilotIstStandSectionText(topic, mode = speechTermMode()) {
  const normalizedMode = normalizeSpeechTermDisplayMode(mode);
  return speechPilotIstStandSectionTexts[topic]?.[normalizedMode]
    || speechPilotIstStandSectionTexts[topic]?.plain
    || "";
}

function pilotIntroSentence(area, focuses = []) {
  const cleanFocuses = focuses.filter(Boolean);
  const focus = cleanFocuses.length > 2
    ? `${cleanFocuses.slice(0, -1).join(", ")} sowie ${cleanFocuses.at(-1)}`
    : joinGermanList(cleanFocuses);
  if (area === "Sprache / Kommunikation") {
    return focus
      ? `Im Bereich Sprache und Kommunikation zeigt sich Unterstützungsbedarf ${focus}.`
      : "";
  }
  if (area === "Kognition") {
    return focus
      ? `Im Bereich Kognition zeigt sich Unterstützungsbedarf ${focus}.`
      : "";
  }
  return "";
}

function composeSpeechPilotIstStand(entries = [], modules = []) {
  const mode = speechTermMode();
  const topics = activeSpeechPilotIstStandTopics(entries, modules);
  if (!topics.length) return "";
  return topics.map((topic) => {
    const heading = speechPilotIstStandHeading(topic, mode);
    const text = finalizeClearIstStandText(speechPilotIstStandSectionText(topic, mode));
    return [heading, text].filter(Boolean).join("\n");
  }).filter(Boolean).join("\n\n");
}

function composeSpeechSelectedIstStandModules(selectedItems = []) {
  const entries = (selectedItems || [])
    .map((item, index) => selectedModuleEntryFromValue(item, index))
    .filter((entry) => entry.text)
    .map((entry) => ({
      ...entry,
      area: "Sprache / Kommunikation",
      topic: canonicalCompetenceTopic("Sprache / Kommunikation", entry.topic)
    }));
  if (!entries.length) return "";
  return composeSpeechPilotIstStand([], entries)
    || composeBundledIstStandModules(entries);
}

function composeCognitionPilotIstStand(entries = [], modules = []) {
  const groups = activePilotGroups("Kognition", entries, modules, cognitionPilotIstStandGroups);
  if (!groups.length) return "";
  const keys = new Set(groups.map((group) => group.key));
  const cognitionFocuses = [];
  if (keys.has("memory")) cognitionFocuses.push("beim Aufnehmen und Behalten von Lerninhalten");
  if (keys.has("transfer")) cognitionFocuses.push("beim Übertragen von Lerninhalten");
  if (!cognitionFocuses.length && keys.has("strategies")) cognitionFocuses.push("bei der Auswahl von Strategien und beim Problemlösen");
  if (!cognitionFocuses.length && keys.has("symbols")) cognitionFocuses.push("beim Verknüpfen von Symbolen und Ordnungssystemen mit ihrer Bedeutung");
  const sentences = [groups.length > 1 && (keys.has("memory") || keys.has("transfer"))
    ? "Im Bereich Kognition benötigt _ Unterstützung beim Aufnehmen, Behalten und Übertragen von Lerninhalten."
    : pilotIntroSentence("Kognition", cognitionFocuses)];

  if (keys.has("memory")) {
    sentences.push("Kurze Aufträge und neue Inhalte gelingen sicherer, wenn sie visualisiert und in klare Schritte gegliedert werden.");
    const memoryGroup = groups.find((group) => group.key === "memory");
    const activeMemoryTopics = pilotActiveTopicsForGroup("Kognition", memoryGroup || {});
    if (activeMemoryTopics.includes("Langfristiges Behalten / Abruf")) {
      sentences.push("Geübte Informationen werden nach mehreren Tagen noch nicht durchgängig sicher abgerufen.");
    }
  }
  if (keys.has("strategies")) {
    sentences.push("Bei neuen oder mehrschrittigen Aufgaben braucht #er/sie# Orientierung, um passende Strategien auszuwählen und Lösungswege zu entwickeln.");
  }
  if (keys.has("transfer")) {
    sentences.push("Das Übertragen bekannter Inhalte auf veränderte Aufgaben und das Erkennen von Zusammenhängen gelingen mit Unterstützung.");
  }
  if (keys.has("symbols")) {
    sentences.push("Symbole, Zeichen, Piktogramme oder Ordnungssysteme müssen weiter gezielt mit ihrer Bedeutung verknüpft werden.");
  }
  return finalizeClearIstStandText(removeRepeatedSentences(sentences.filter(Boolean)).join(" "));
}

