function learningFocusTemplatePool() {
  return [...learningBroadSupportChainLibrary, ...learningFocusTemplateLibrary];
}

function normalizedLearningTemplateTopics(template) {
  return (template.topics || []).map((topic) => canonicalLearningCompetenceTopic(topic)).filter(Boolean);
}

function selectedLearningTemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalCompetenceTopic("Lern- und Leistungsverhalten", entry.topic))
    .filter((topic) => learningCompetenceTopics.includes(topic)));
  return learningCompetenceTopics.filter((topic) => selected.has(topic));
}

function learningFocusTemplateScore(template, selectedTopics = []) {
  const selectedSet = new Set(selectedTopics);
  const templateTopics = normalizedLearningTemplateTopics(template);
  if (!templateTopics.length) return 0;
  const overlap = templateTopics.filter((topic) => selectedSet.has(topic)).length;
  const missing = templateTopics.length - overlap;
  const extra = selectedTopics.length - overlap;
  if (template.broadChain) {
    const exact = missing === 0 && extra === 0;
    if (exact && templateTopics.length >= 5) return 50000 + (templateTopics.length * 1000);
    if (selectedTopics.length >= 5 && overlap >= 5) {
      return 2000 + (overlap * 100) + (templateTopics.length * 10) - (missing * 20) - (extra * 5);
    }
    return 0;
  }
  if (template.broad) {
    if (selectedTopics.length >= 7) return 900 + selectedTopics.length;
    if (selectedTopics.length >= 4) return 80 + selectedTopics.length;
    return 0;
  }
  if (missing > 0) return 0;
  const exactBonus = extra === 0 ? 120 : 0;
  const sizeBonus = templateTopics.length * 8;
  return 400 + exactBonus + sizeBonus - (extra * 5);
}

function matchingLearningFocusTemplates(entries = []) {
  const selectedTopics = selectedLearningTemplateTopics(entries);
  if (!selectedTopics.length) return [];
  if (selectedTopics.length === 1) {
    const singleTemplate = learningSingleFocusTemplate(selectedTopics[0]);
    return singleTemplate ? [singleTemplate] : [];
  }
  const scoredTemplates = learningFocusTemplatePool()
    .map((template, index) => ({
      template,
      index,
      score: learningFocusTemplateScore(template, selectedTopics)
    }))
    .filter((item) => item.score > 0);
  const hasSpecificTemplate = scoredTemplates.some((item) => !item.template.broad);
  return scoredTemplates
    .filter((item) => !item.template.broad || !hasSpecificTemplate)
    .sort((left, right) => right.score - left.score || left.index - right.index)
    .map((item) => item.template);
}

function selectedLearningFocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingLearningFocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function bulletSuggestion(value = "") {
  const text = String(value || "").trim().replace(/^[–—•*-]\s*/, "");
  const item = capitalizeListItemText(text);
  return item ? `- ${item}` : "";
}

function normalizeGoalListPresentation(value = "") {
  return String(value || "")
    .replace(/\r/g, "")
    .replace(/^(\s*(?:Im Förderzeitraum soll [^\n:]+ zunehmend|Ziele für den Förderzeitraum):)[ \t]+(?=[–—•*-]\s+)/gmi, "$1\n\n")
    .replace(/^(\s*)Im Förderzeitraum soll _ zunehmend:[ \t]*$/gmi, "$1Ziele für den Förderzeitraum:")
    .replace(/^(\s*[–—•*-]\s*)(\p{Ll})/gmu, (_, prefix, firstLetter) =>
      `${prefix}${firstLetter.toLocaleUpperCase("de-DE")}`
    );
}

function rasterPresentationText(columnKey = "", value = "") {
  return columnKey === "ziele" ? normalizeGoalListPresentation(value) : String(value || "");
}

function stripLeadingListMarkers(value = "") {
  return String(value || "").replace(/^\s*(?:[–—•*-]\s*)+/u, "").trim();
}

function printListPresentationText(columnKey = "", value = "") {
  if (!['ziele', 'massnahmen', 'evaluation'].includes(columnKey)) return String(value || "");
  const source = columnKey === "ziele"
    ? normalizeGoalListPresentation(value)
    : String(value || "").replace(/\r/g, "");
  const introLines = [];
  const itemLines = [];
  source.split("\n").forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed) return;
    if (columnKey === "ziele" && /^(?:Im Förderzeitraum soll\b.+|Ziele für den Förderzeitraum):\s*$/i.test(trimmed)) {
      introLines.push(trimmed);
      return;
    }
    const item = stripLeadingListMarkers(trimmed);
    if (item) itemLines.push(item);
  });
  if (!itemLines.length) return introLines.join("\n");
  return [
    ...introLines,
    ...(introLines.length ? [""] : []),
    ...itemLines.map((item) => `- ${item}`)
  ].join("\n");
}

function lowerSentenceStart(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  return text.charAt(0).toLocaleLowerCase("de-DE") + text.slice(1);
}

function actionSentence(value = "") {
  return cleanSuggestionSentence(value).replace(/[.!?]$/, "");
}

function cleanGoalActionText(value = "") {
  return String(value || "")
    .replace(/\bzunehmend\s+/gi, "")
    .replace(/\bschrittweise\s+/gi, "")
    .replace(/\bimmer häufiger\s+/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function goalSentenceToAction(value = "") {
  let body = cleanSuggestionSentence(value)
    .replace(/^[–—•*-]\s*/, "")
    .replace(/[.!?]$/, "")
    .trim();
  body = body
    .replace(/^Im Förderzeitraum soll _ zunehmend:?\s*/i, "")
    .replace(/^Im Förderzeitraum soll _\s+/i, "")
    .replace(/^_\s+soll\s+/i, "")
    .replace(/^#er\/sie#\s+soll\s+/i, "")
    .replace(/^Darüber hinaus soll #er\/sie#\s+/i, "")
    .replace(/^_\s+/i, "");
  body = cleanGoalActionText(body).replace(/^und\s+/i, "");
  const directInfinitive = body.match(/^(sich\s+.+\s+einlassen|.+\s+(?:erfassen|beginnen|aufrechterhalten|nutzen|organisieren|kontrollieren|bearbeiten|erkennen|fortführen|vorbereiten|ableiten|arbeiten|bleiben|stellen|richten))$/i);
  if (directInfinitive) return cleanSuggestionSentence(lowerSentenceStart(body));
  const patterns = [
    [/^bildet\s+(.+?)\s+und überträgt\s+(.+)$/i, (_, first, second) => `${first} bilden und ${second} übertragen`],
    [/^bildet\s+(.+?)\s+und verwendet\s+(.+)$/i, (_, first, second) => `${first} bilden und ${second} verwenden`],
    [/^bildet\s+(.+)$/i, (_, first) => `${first} bilden`],
    [/^verwendet\s+(.+)$/i, (_, first) => `${first} verwenden`],
    [/^erkennt und unterscheidet\s+(.+)$/i, (_, first) => `${first} erkennen und unterscheiden`],
    [/^unterscheidet\s+(.+)$/i, (_, first) => `${first} unterscheiden`],
    [/^versteht und nutzt\s+(.+)$/i, (_, first) => `${first} verstehen und nutzen`],
    [/^erweitert\s+(.+?)\s+und nutzt\s+(.+)$/i, (_, first, second) => `${first} erweitern und ${second} nutzen`],
    [/^versteht\s+(.+?)\s+und setzt\s+(.+)$/i, (_, first, second) => `${first} verstehen und ${second} umsetzen`],
    [/^nutzt\s+(.+?)\s+und bildet\s+(.+)$/i, (_, first, second) => `${first} nutzen und ${second} bilden`],
    [/^erzählt\s+(.+)$/i, (_, first) => `${first} erzählen`],
    [/^beteiligt sich\s+(.+?)\s+und reagiert\s+(.+)$/i, (_, first, second) => `sich ${first} beteiligen und ${second} reagieren`],
    [/^passt\s+(.+?)\s+an$/i, (_, first) => `${first} anpassen`],
    [/^findet\s+(.+?)\s+und formuliert\s+(.+)$/i, (_, first, second) => `${first} finden und ${second} formulieren`],
    [/^erfasst\s+(.+?)\s+und beginnt mit\s+(.+)$/i, (_, first, second) => `${first} erfassen und mit ${second} beginnen`],
    [/^erfasst\s+(.+)$/i, (_, first) => `${first} erfassen`],
    [/^hält\s+(.+?)\s+aufrecht(?:\s+und nutzt\s+(.+))?$/i, (_, first, second) => `${first} aufrechterhalten${second ? ` und ${cleanGoalActionText(second)} nutzen` : ""}`],
    [/^richtet\s+(.+?)\s+auf\s+(.+)$/i, (_, first, second) => `${first} auf ${second} richten`],
    [/^nutzt\s+(.+)$/i, (_, first) => `${first} nutzen`],
    [/^organisiert\s+(.+)$/i, (_, first) => `${first} organisieren`],
    [/^kontrolliert\s+(.+)$/i, (_, first) => `${first} kontrollieren`],
    [/^bearbeitet\s+(.+)$/i, (_, first) => `${first} bearbeiten`],
    [/^erkennt\s+(.+)$/i, (_, first) => `${first} erkennen`],
    [/^beginnt\s+(.+)$/i, (_, first) => `${first} beginnen`],
    [/^bleibt\s+(.+)$/i, (_, first) => `${first} bleiben`],
    [/^führt\s+(.+?)\s+fort(?:\s+und nutzt\s+(.+))?$/i, (_, first, second) => `${first} fortführen${second ? ` und ${cleanGoalActionText(second)} nutzen` : ""}`],
    [/^bereitet\s+(.+?)\s+vor(?:\s+und nutzt\s+(.+))?$/i, (_, first, second) => `${first} vorbereiten${second ? ` und ${cleanGoalActionText(second)} nutzen` : ""}`],
    [/^leitet\s+(.+?)\s+ab$/i, (_, first) => `${first} ableiten`],
    [/^stellt\s+(.+)$/i, (_, first) => `${first} stellen`],
    [/^lässt sich auf\s+(.+?)\s+ein(?:\s+und arbeitet\s+(.+))?$/i, (_, first, second) => `sich auf ${first} einlassen${second ? ` und ${cleanGoalActionText(second)} arbeiten` : ""}`]
  ];
  for (const [pattern, replacement] of patterns) {
    const match = body.match(pattern);
    if (match) return cleanSuggestionSentence(replacement(...match));
  }
  return cleanSuggestionSentence(lowerSentenceStart(body));
}

function formatGoalListWithIntro(items = []) {
  const goals = removeExactRepeatedSentences((items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean));
  if (goals.length <= 1) return goals.map((goal) => bulletSuggestion(cleanSuggestionSentence(goal))).join("\n");
  const actions = goals.map(goalSentenceToAction).filter(Boolean);
  return [
    "Ziele für den Förderzeitraum:",
    "",
    ...actions.map((action) => `- ${capitalizeListItemText(action)}`)
  ].join("\n");
}

function normalizeEvaluationOpening(value = "", index = 0, options = {}) {
  const openings = options.avoidVerglichen
    ? ["Beobachtet", "Dokumentiert", "Überprüft"]
    : ["Beobachtet", "Dokumentiert", "Überprüft", "Verglichen"];
  let sentence = normalizeSelectedEvaluationSentence(value);
  const opening = openings[index % openings.length];
  if (/^(Beobachtet|Dokumentiert|Überprüft|Verglichen)\s+wird,\s+ob\b/i.test(sentence)) {
    return sentence.replace(/^(Beobachtet|Dokumentiert|Überprüft|Verglichen)\s+wird,\s+ob/i, `${opening} wird, ob`);
  }
  if (/^Es wird\s+(beobachtet|dokumentiert|überprüft|verglichen),\s+ob\b/i.test(sentence)) {
    return sentence.replace(/^Es wird\s+(beobachtet|dokumentiert|überprüft|verglichen),\s+ob/i, `${opening} wird, ob`);
  }
  return sentence;
}

function formatEvaluationList(items = [], options = {}) {
  return removeExactRepeatedSentences((items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean))
    .map((item, index) => `- ${normalizeEvaluationOpening(item, index, options)}`)
    .join("\n");
}

function learningFocusTemplateFieldItems(template, fieldKey = "") {
  const value = template?.[fieldKey];
  const values = Array.isArray(value) ? value : [value];
  return values
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
}

function learningFocusOutputLimits(selectedTopicCount = 0) {
  if (selectedTopicCount <= 1) {
    return { ziele: 1, massnahmen: 1, evaluation: 1 };
  }
  if (selectedTopicCount <= 2) {
    return { ziele: 2, massnahmen: 2, evaluation: 2 };
  }
  if (selectedTopicCount <= 5) {
    return { ziele: 3, massnahmen: 4, evaluation: 2 };
  }
  return { ziele: 5, massnahmen: 5, evaluation: 3 };
}

function learningEntriesForTopics(entries = [], topics = []) {
  const activeEntries = activeComposerModuleEntries(entries.map((entry) => ({
    ...entry,
    area: "Lern- und Leistungsverhalten"
  })));
  const byTopic = new Map(activeEntries.map((entry, index) => [
    canonicalLearningCompetenceTopic(entry.topic),
    { ...entry, index: Number.isInteger(entry.index) ? entry.index : index }
  ]));
  return (topics || []).map((topic, index) => {
    const canonicalTopic = canonicalLearningCompetenceTopic(topic);
    return byTopic.get(canonicalTopic) || {
      area: "Lern- und Leistungsverhalten",
      topic: canonicalTopic,
      rating: "teilweise unsicher",
      index
    };
  }).filter((entry) => entry.topic);
}

function learningFocusModuleItems(entries = [], topics = [], fieldKey = "", variantOffset = 0) {
  return learningEntriesForTopics(entries, topics)
    .map((entry, index) => composerModuleForField(
      "Lern- und Leistungsverhalten",
      "",
      { ...entry, index },
      fieldKey,
      variantOffset + index
    ))
    .filter(Boolean)
    .map((module) => String(module.text || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
}

function uniqueLearningFocusItems(items = []) {
  const unique = [];
  items.forEach((item) => {
    const text = String(item || "").trim().replace(/^[–—•*-]\s*/, "");
    if (!text) return;
    const candidate = { text };
    if (unique.some((existing) => selectedModulesAreSimilar(candidate, { text: existing }))) return;
    unique.push(text);
  });
  return unique;
}

function learningFallbackTemplateItemsForField(template, selectedTopics = [], fieldKey = "") {
  const selectedSet = new Set((selectedTopics || []).map((topic) => canonicalLearningCompetenceTopic(topic)).filter(Boolean));
  if (!selectedSet.size) return [];
  const candidates = learningFocusTemplateLibrary
    .filter((candidate) => candidate !== template)
    .map((candidate, index) => {
      const topics = normalizedLearningTemplateTopics(candidate);
      const overlap = candidate.broad ? selectedSet.size : topics.filter((topic) => selectedSet.has(topic)).length;
      const subset = candidate.broad || (topics.length > 0 && overlap === topics.length);
      const items = learningFocusTemplateFieldItems(candidate, fieldKey);
      return {
        candidate,
        index,
        overlap,
        subset,
        broad: Boolean(candidate.broad),
        items
      };
    })
    .filter((item) => item.items.length && item.overlap > 0)
    .sort((left, right) =>
      Number(right.subset) - Number(left.subset)
      || Number(left.broad) - Number(right.broad)
      || right.overlap - left.overlap
      || left.index - right.index
    );
  return candidates.flatMap((item) => item.items);
}

function learningFocusItemsForField({ template, entries = [], selectedTopics = [], templateTopics = [], fieldKey = "", variantOffset = 0 }) {
  if (template?.broadChain) {
    return uniqueLearningFocusItems(learningFocusTemplateFieldItems(template, fieldKey));
  }
  const limits = learningFocusOutputLimits(selectedTopics.length);
  const maxItems = limits[fieldKey] || 1;
  const sourceTopics = template?.broad ? selectedTopics : templateTopics;
  const templateItems = learningFocusTemplateFieldItems(template, fieldKey);
  const fallbackTemplateItems = learningFallbackTemplateItemsForField(template, selectedTopics, fieldKey);
  const moduleItems = learningFocusModuleItems(entries, sourceTopics, fieldKey, variantOffset);
  return uniqueLearningFocusItems([...templateItems, ...fallbackTemplateItems, ...moduleItems]).slice(0, maxItems);
}

function learningFocusListSuggestion(items = [], fieldKey = "") {
  const cleaned = (items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
  if (fieldKey === "ziele") return formatGoalListWithIntro(cleaned);
  if (fieldKey === "evaluation") return formatEvaluationList(cleaned, { avoidVerglichen: true });
  return cleaned
    .map((item) => bulletSuggestion(item))
    .filter(Boolean)
    .join("\n");
}

function learningBroadFocusIstStand(selectedTopics = []) {
  const selected = new Set((selectedTopics || []).map((topic) => canonicalLearningCompetenceTopic(topic)).filter(Boolean));
  const has = (topic) => selected.has(topic);
  const sentences = [
    "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim Erfassen von Aufgaben, beim Arbeitsbeginn und bei der Steuerung der Arbeitsphase."
  ];

  if (has("Lernbereitschaft / Motivation") || has("Aufgabenverständnis") || has("Aufgabenbeginn")) {
    const details = [];
    if (has("Lernbereitschaft / Motivation")) details.push("neue Lernangebote");
    if (has("Aufgabenverständnis")) details.push("mehrschrittige Arbeitsaufträge");
    if (has("Aufgabenbeginn")) details.push("erste Handlungsschritte");
    const subject = details.length ? capitalizeSentenceStart(joinGermanList(details)) : "Arbeitsaufträge";
    const verb = details.length === 1 ? "gelingt" : "gelingen";
    sentences.push(`${subject} ${verb} sicherer, wenn Anforderungen klar gegliedert, zentrale Begriffe geklärt und erste Schritte sichtbar gemacht werden.`);
  }

  if (has("Konzentration / Aufmerksamkeit") || has("Ausdauer") || has("Arbeitstempo / Arbeitszeit nutzen")) {
    const aspects = [];
    if (has("Konzentration / Aufmerksamkeit")) aspects.push("die Aufmerksamkeit aufrechtzuerhalten");
    if (has("Ausdauer")) aspects.push("begonnene Aufgaben fortzuführen");
    if (has("Arbeitstempo / Arbeitszeit nutzen")) aspects.push("das Arbeitstempo passend zu steuern");
    sentences.push(`In Arbeitsphasen braucht #er/sie# Orientierung, um ${joinGermanList(aspects)}.`);
  }

  if (has("Selbstständigkeit") || has("Arbeitsorganisation / Material")) {
    if (has("Selbstständigkeit") && has("Arbeitsorganisation / Material")) {
      sentences.push("Material, Arbeitsplatz und passende Hilfen müssen noch gemeinsam vorbereitet und geordnet genutzt werden.");
    } else if (has("Selbstständigkeit")) {
      sentences.push("Vereinbarte Hilfen und Rückfragewege unterstützen #ihn/sie# dabei, Aufgaben selbstständiger fortzuführen.");
    } else {
      sentences.push("Material und Arbeitsplatz müssen noch übersichtlich vorbereitet und geordnet genutzt werden.");
    }
  }

  if (has("Sorgfalt / Genauigkeit")) {
    sentences.push("Eigene Ergebnisse werden sorgfältiger überprüft, wenn Kontrollpunkte sichtbar sind und Rückmeldungen zeitnah erfolgen.");
  }

  if (selected.size >= 7) {
    sentences.push("Feste Routinen, kurze Zwischenziele und klare Rückfragewege unterstützen #ihn/sie# dabei, Arbeitsprozesse zunehmend selbstständiger zu steuern.");
  } else if (selected.size >= 5) {
    sentences.push("Kurze Zwischenziele und verlässliche Routinen helfen #ihm/ihr#, den Arbeitsprozess überschaubar zu halten.");
  }

  return finalizeClearIstStandText(removeRepeatedSentences(sentences).join(" "));
}

function learningFocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedLearningFocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedLearningTemplateTopics(entries);
  const templateTopics = template.broad ? selectedTopics : normalizedLearningTemplateTopics(template);
  const visibleTopics = templateTopics.map((topic) => learningTopicDisplayName(topic));
  const istStand = template.broad
    ? learningBroadFocusIstStand(selectedTopics)
    : finalizeClearIstStandText(template.istStand);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics,
    suggestion: {
      istStand,
      ziele: learningFocusListSuggestion(learningFocusItemsForField({ template, entries, selectedTopics, templateTopics, fieldKey: "ziele", variantOffset }), "ziele"),
      massnahmen: learningFocusListSuggestion(learningFocusItemsForField({ template, entries, selectedTopics, templateTopics, fieldKey: "massnahmen", variantOffset }), "massnahmen"),
      evaluation: learningFocusListSuggestion(learningFocusItemsForField({ template, entries, selectedTopics, templateTopics, fieldKey: "evaluation", variantOffset }), "evaluation")
    }
  };
}

