function parseCognitionIstStandCombinationTemplates(source = "") {
  return String(source || "")
    .trim()
    .split(/\n(?=ID:\s*)/)
    .map((block) => {
      const id = block.match(/^ID:\s*([^\n]+)/)?.[1]?.trim();
      const keys = block.match(/Kompetenzen:\s*([^\n]+)/)?.[1]
        ?.split(",")
        .map((key) => key.trim())
        .filter(Boolean) || [];
      const istStand = block.match(/Ist-Stand:\s*\n([\s\S]*)/)?.[1]?.trim();
      const topics = keys.map((key) => cognitionCompetenceKeyTopics[key]).filter(Boolean);
      if (!id || !topics.length || !istStand) return null;
      return {
        id,
        label: `Kognition: ${topics.map((topic) => cognitionTopicDisplayName(topic)).join(" + ")}`,
        combinationOnly: true,
        topicKeys: keys,
        topics,
        istStand
      };
    })
    .filter(Boolean);
}

const cognitionIstStandCombinationTemplates = parseCognitionIstStandCombinationTemplates(cognitionIstStandCombinationSource);

function cognitionFocusTemplatePool() {
  return [...cognitionBroadSupportChainLibrary, ...cognitionIstStandCombinationTemplates, ...cognitionFocusTemplateLibrary];
}

function normalizedCognitionTemplateTopics(template) {
  const topics = template.topicKeys
    ? template.topicKeys.map((key) => cognitionCompetenceKeyTopics[key]).filter(Boolean)
    : template.topics || [];
  return topics.map((topic) => canonicalCognitionCompetenceTopic(topic)).filter(Boolean);
}

function selectedCognitionTemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalCompetenceTopic("Kognition", entry.topic))
    .filter((topic) => cognitionCompetenceTopics.includes(topic)));
  return cognitionCompetenceTopics.filter((topic) => selected.has(topic));
}

function cognitionFocusTemplateScore(template, selectedTopics = []) {
  const selectedSet = new Set(selectedTopics);
  if (template.broad) {
    if (selectedTopics.length >= 4) return 1;
    return 0;
  }
  const templateTopics = normalizedCognitionTemplateTopics(template);
  if (!templateTopics.length) return 0;
  const overlap = templateTopics.filter((topic) => selectedSet.has(topic)).length;
  const missing = templateTopics.length - overlap;
  if (template.broadChain && selectedTopics.length >= 5) {
    const exact = missing === 0 && selectedTopics.length === templateTopics.length;
    const extra = Math.max(0, selectedTopics.length - overlap);
    if (exact) return 30000 + (templateTopics.length * 1000);
    if (overlap >= 4) return 1000 + (overlap * 20) - (missing * 8) - extra;
    return 0;
  }
  if (template.broadChain) {
    if (missing > 0) return 0;
    const exact = selectedTopics.length === templateTopics.length;
    if (exact) return 25000 + (templateTopics.length * 1000);
    return 0;
  }
  if (missing > 0) return 0;
  const extra = selectedTopics.length - templateTopics.length;
  const exactBonus = extra === 0 ? 10000 : 0;
  const sizeBonus = templateTopics.length * 100;
  const combinationBonus = template.combinationOnly ? 10 : 0;
  return exactBonus + sizeBonus + combinationBonus - extra;
}

function matchingCognitionFocusTemplates(entries = []) {
  const selectedTopics = selectedCognitionTemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const scoredTemplates = cognitionFocusTemplatePool()
    .map((template, index) => ({
      template,
      index,
      score: cognitionFocusTemplateScore(template, selectedTopics),
      topicKey: normalizedCognitionTemplateTopics(template).join("|")
    }))
    .filter((item) => item.score > 0);
  const hasSpecificTemplate = scoredTemplates.some((item) => !item.template.broad);
  const combinationTopicKeys = new Set(scoredTemplates
    .filter((item) => item.template.combinationOnly)
    .map((item) => item.topicKey));
  const broadChainTopicKeys = new Set(scoredTemplates
    .filter((item) => item.template.broadChain)
    .map((item) => item.topicKey));
  return scoredTemplates
    .filter((item) => !item.template.broad || !hasSpecificTemplate)
    .filter((item) =>
      item.template.broadChain
      || item.template.combinationOnly
      || (!combinationTopicKeys.has(item.topicKey) && !broadChainTopicKeys.has(item.topicKey))
    )
    .sort((left, right) => right.score - left.score || left.index - right.index)
    .map((item) => item.template);
}

function selectedCognitionFocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingCognitionFocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function cognitionFocusTemplateFieldItems(template, fieldKey = "") {
  const sourceTemplate = template?.[fieldKey] ? template : cognitionSupportTemplateFor(template);
  const value = sourceTemplate?.[fieldKey];
  const values = Array.isArray(value) ? value : [value];
  return values
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
}

function cognitionSupportTemplateFor(template) {
  if (!template || template.ziele || template.massnahmen || template.evaluation) return template;
  const templateTopics = normalizedCognitionTemplateTopics(template);
  if (!templateTopics.length) return cognitionFocusTemplateLibrary.find((item) => item.broad) || template;
  const templateSet = new Set(templateTopics);
  return cognitionFocusTemplateLibrary
    .filter((item) => !item.broad)
    .map((item, index) => {
      const supportTopics = normalizedCognitionTemplateTopics(item);
      const overlap = supportTopics.filter((topic) => templateSet.has(topic)).length;
      const missing = templateTopics.filter((topic) => !supportTopics.includes(topic)).length;
      const exact = missing === 0 && supportTopics.length === templateTopics.length ? 1 : 0;
      return {
        item,
        index,
        score: exact * 1000 + overlap * 100 - Math.abs(supportTopics.length - templateTopics.length) * 5
      };
    })
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score || left.index - right.index)[0]?.item
    || cognitionFocusTemplateLibrary.find((item) => item.broad)
    || template;
}

function cognitionFocusListSuggestion(items = [], fieldKey = "") {
  const cleaned = (items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
  if (fieldKey === "ziele") return formatGoalListWithIntro(cleaned);
  return cleaned
    .map((item) => bulletSuggestion(cleanSuggestionSentence(item)))
    .filter(Boolean)
    .join("\n");
}

function cognitionFocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedCognitionFocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedCognitionTemplateTopics(entries);
  const templateTopics = template.broad ? selectedTopics : normalizedCognitionTemplateTopics(template);
  const visibleTopics = templateTopics.map((topic) => cognitionTopicDisplayName(topic));
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: cognitionFocusListSuggestion(cognitionFocusTemplateFieldItems(template, "ziele"), "ziele"),
      massnahmen: cognitionFocusListSuggestion(cognitionFocusTemplateFieldItems(template, "massnahmen"), "massnahmen"),
      evaluation: cognitionFocusListSuggestion(cognitionFocusTemplateFieldItems(template, "evaluation"), "evaluation")
    }
  };
}

