function canonicalGerman12CompetenceTopic(topic = "") {
  const value = String(topic || "").trim();
  return germanCompetenceTopics["Klasse 1/2"].includes(value) ? value : value;
}

function normalizedGerman12TemplateTopics(template = {}) {
  return (template.topics || [])
    .map(canonicalGerman12CompetenceTopic)
    .filter((topic) => germanCompetenceTopics["Klasse 1/2"].includes(topic));
}

function selectedGerman12TemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalGerman12CompetenceTopic(entry.topic))
    .filter((topic) => germanCompetenceTopics["Klasse 1/2"].includes(topic)));
  return germanCompetenceTopics["Klasse 1/2"].filter((topic) => selected.has(topic));
}

function german12TemplatePriority(template = {}) {
  const count = normalizedGerman12TemplateTopics(template).length;
  if (template.broad) return 5000;
  if (count === 4) return 4000;
  if (count === 3) return 3000;
  if (count === 2) return 2000;
  if (count === 1) return 1000;
  return 0;
}

function matchingGerman12FocusTemplates(entries = []) {
  const selectedTopics = selectedGerman12TemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const selectedKey = selectedTopics.join("|");
  return german12FocusTemplateLibrary
    .map((template, index) => {
      const templateTopics = normalizedGerman12TemplateTopics(template);
      return {
        template,
        index,
        templateTopics,
        exact: templateTopics.join("|") === selectedKey,
        priority: german12TemplatePriority(template)
      };
    })
    .filter((item) => item.exact)
    .sort((left, right) => right.priority - left.priority || left.index - right.index)
    .map((item) => item.template);
}

function selectedGerman12FocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingGerman12FocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function german12TemplateFieldItems(template = {}, fieldKey = "") {
  const value = template?.[fieldKey];
  const values = Array.isArray(value) ? value : [value];
  return values
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
}

function german12GoalListSuggestion(items = []) {
  const cleaned = (items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
  if (cleaned.length <= 1) return cleaned.map((item) => bulletSuggestion(cleanSuggestionSentence(item))).join("\n");
  const [first, ...rest] = cleaned;
  const broadIntroMatch = first.match(/^Im Förderzeitraum soll _ zunehmend\s+(.+)$/i);
  if (broadIntroMatch) {
    return [
      "Ziele für den Förderzeitraum:",
      "",
      `- ${capitalizeListItemText(cleanGoalActionText(broadIntroMatch[1]))}`,
      ...rest.map((item) => `- ${capitalizeListItemText(cleanGoalActionText(item))}`)
    ].join("\n");
  }
  return formatGoalListWithIntro(cleaned);
}

function german12FocusListSuggestion(items = [], fieldKey = "") {
  const cleaned = (items || [])
    .map((item) => String(item || "").trim().replace(/^[–—•*-]\s*/, ""))
    .filter(Boolean);
  if (fieldKey === "ziele") return german12GoalListSuggestion(cleaned);
  if (fieldKey === "evaluation") return formatEvaluationList(cleaned, { avoidVerglichen: true });
  return cleaned
    .map((item) => bulletSuggestion(item))
    .filter(Boolean)
    .join("\n");
}

function german12FocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedGerman12FocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedGerman12TemplateTopics(entries);
  const templateTopics = normalizedGerman12TemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: german12FocusListSuggestion(german12TemplateFieldItems(template, "ziele"), "ziele"),
      massnahmen: german12FocusListSuggestion(german12TemplateFieldItems(template, "massnahmen"), "massnahmen"),
      evaluation: german12FocusListSuggestion(german12TemplateFieldItems(template, "evaluation"), "evaluation")
    }
  };
}

