function canonicalGerman34CompetenceTopic(topic = "") {
  const value = String(topic || "").trim();
  const aliases = {
    "Lesestrategien": "Lesestrategien nutzen",
    "Texte kontrollieren": "Texte kontrollieren und überarbeiten"
  };
  return aliases[value] || value;
}

function normalizedGerman34TemplateTopics(template = {}) {
  return (template.topics || [])
    .map(canonicalGerman34CompetenceTopic)
    .filter((topic) => germanCompetenceTopics["Klasse 3/4"].includes(topic));
}

function selectedGerman34TemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalGerman34CompetenceTopic(entry.topic))
    .filter((topic) => germanCompetenceTopics["Klasse 3/4"].includes(topic)));
  return germanCompetenceTopics["Klasse 3/4"].filter((topic) => selected.has(topic));
}

function german34TemplatePriority(template = {}) {
  const count = normalizedGerman34TemplateTopics(template).length;
  if (template.broad) return 9000;
  if (count === 7) return 8000;
  if (count === 6) return 7000;
  if (count === 5) return 6000;
  if (count === 4) return 5000;
  if (count === 3) return 4000;
  if (count === 2) return 3000;
  if (count === 1) return 2000;
  return 0;
}

function matchingGerman34FocusTemplates(entries = []) {
  const selectedTopics = selectedGerman34TemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const selectedKey = selectedTopics.join("|");
  return german34FocusTemplateLibrary
    .map((template, index) => {
      const templateTopics = normalizedGerman34TemplateTopics(template);
      return {
        template,
        index,
        templateTopics,
        exact: templateTopics.join("|") === selectedKey,
        priority: german34TemplatePriority(template)
      };
    })
    .filter((item) => item.exact)
    .sort((left, right) => right.priority - left.priority || left.index - right.index)
    .map((item) => item.template);
}

function selectedGerman34FocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingGerman34FocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function german34FocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedGerman34FocusTemplate(entries, variantOffset);
  if (!template) return null;
  const selectedTopics = selectedGerman34TemplateTopics(entries);
  const templateTopics = normalizedGerman34TemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: german12FocusListSuggestion(german12TemplateFieldItems(template, "ziele"), "ziele"),
      massnahmen: german12FocusListSuggestion(german12TemplateFieldItems(template, "massnahmen"), "massnahmen"),
      evaluation: german12FocusListSuggestion(german12TemplateFieldItems(template, "evaluation"), "evaluation")
    }
  };
}

