function canonicalMath12CompetenceTopic(topic = "") {
  const value = String(topic || "").trim();
  const aliases = {
    "Zahlverständnis": "Mengen und Zahlverständnis",
    "Mengen/Zahlen zuordnen": "Mengen und Zahlverständnis",
    "Zählen und Zahlwortreihe": "Mengen und Zahlverständnis",
    "Ziffern und Zahlzuordnung": "Mengen und Zahlverständnis",
    "Zahlenreihe/Zahlordnung": "Zahlraum und Stellenwert",
    "Orientierung im Zahlenraum": "Zahlraum und Stellenwert",
    "Zahlbeziehungen": "Zahlzerlegung und Zahlbeziehungen",
    "Zahlzerlegung": "Zahlzerlegung und Zahlbeziehungen",
    "Zerlegung": "Zahlzerlegung und Zahlbeziehungen",
    Addition: "Addition und Subtraktion",
    Subtraktion: "Addition und Subtraktion",
    "Addition und Subtraktion": "Addition und Subtraktion",
    Zehnerübergang: "Rechenstrategien und Zehnerübergang",
    Rechenstrategien: "Rechenstrategien und Zehnerübergang",
    Kopfrechnen: "Rechenstrategien und Zehnerübergang",
    Sachaufgaben: "Aufgaben verstehen und Sachrechnen",
    "Sachrechnen / Größen optional": "Aufgaben verstehen und Sachrechnen",
    "Aufgabenverständnis Mathematik": "Aufgaben verstehen und Sachrechnen",
    Größen: "Größen und Messen",
    "Geometrie/Formen/Muster": "Geometrie, Muster und Raumvorstellung",
    Geometrie: "Geometrie, Muster und Raumvorstellung",
    "Umgang mit Material": "Mengen und Zahlverständnis"
  };
  return aliases[value] || value;
}

function normalizedMath12TemplateTopics(template = {}) {
  return (template.topics || [])
    .map(canonicalMath12CompetenceTopic)
    .filter((topic) => mathCompetenceTopics12.includes(topic));
}

function selectedMath12TemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalMath12CompetenceTopic(entry.topic))
    .filter((topic) => mathCompetenceTopics12.includes(topic)));
  return mathCompetenceTopics12.filter((topic) => selected.has(topic));
}

function math12TemplatePriority(template = {}) {
  const count = normalizedMath12TemplateTopics(template).length;
  if (template.broad) return 10000;
  if (count === 8) return 9000;
  if (count === 7) return 8000;
  if (count === 6) return 7000;
  if (count === 5) return 6000;
  if (count === 4) return 5000;
  if (count === 3) return 4000;
  if (count === 2) return 3000;
  if (count === 1) return 2000;
  return 0;
}

function matchingMath12FocusTemplates(entries = []) {
  const selectedTopics = selectedMath12TemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const selectedKey = selectedTopics.join("|");
  return math12FocusTemplateLibrary
    .map((template, index) => {
      const templateTopics = normalizedMath12TemplateTopics(template);
      return {
        template,
        index,
        templateTopics,
        exact: templateTopics.join("|") === selectedKey,
        priority: math12TemplatePriority(template)
      };
    })
    .filter((item) => item.exact)
    .sort((left, right) => right.priority - left.priority || left.index - right.index)
    .map((item) => item.template);
}

function selectedMath12FocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingMath12FocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function math12BaseTemplateForTopic(topic = "") {
  const canonicalTopic = canonicalMath12CompetenceTopic(topic);
  return math12FocusTemplateLibrary.find((template) => {
    const templateTopics = normalizedMath12TemplateTopics(template);
    return !template.broad && templateTopics.length === 1 && templateTopics[0] === canonicalTopic;
  }) || null;
}

function composeMath12SelectionIstStand(selectedTopics = []) {
  const topics = new Set(selectedTopics);
  const sentences = [];
  const numberTopics = [
    "Mengen und Zahlverständnis",
    "Zahlraum und Stellenwert",
    "Zahlzerlegung und Zahlbeziehungen"
  ].filter((topic) => topics.has(topic));
  const operationTopics = [
    "Addition und Subtraktion",
    "Rechenstrategien und Zehnerübergang"
  ].filter((topic) => topics.has(topic));
  const applicationTopics = [
    "Aufgaben verstehen und Sachrechnen",
    "Größen und Messen",
    "Geometrie, Muster und Raumvorstellung"
  ].filter((topic) => topics.has(topic));

  const focusParts = [];
  if (numberTopics.length) focusParts.push("beim Aufbau tragfähiger Zahlvorstellungen");
  if (operationTopics.length) focusParts.push("beim sicheren Anwenden von Rechenoperationen und Rechenstrategien");
  if (applicationTopics.length) focusParts.push("beim Übertragen mathematischer Kenntnisse auf Aufgabenstellungen");
  if (focusParts.length) {
    const last = focusParts.pop();
    const focusText = focusParts.length ? `${focusParts.join(", ")} und ${last}` : last;
    sentences.push(`Im Lernbereich Mathematik benötigt _ Unterstützung ${focusText}.`);
  }

  if (numberTopics.length) {
    const details = [];
    if (topics.has("Mengen und Zahlverständnis")) details.push("Mengen und Zahlen sicher zu erfassen und darzustellen");
    if (topics.has("Zahlraum und Stellenwert")) details.push("sich im Zahlraum zu orientieren und Stellenwerte zu nutzen");
    if (topics.has("Zahlzerlegung und Zahlbeziehungen")) details.push("Zahlen zu zerlegen und Zahlbeziehungen zu erkennen");
    sentences.push(`Noch nicht durchgängig gelingt es #ihm/ihr#, ${details.join(", ").replace(/, ([^,]*)$/, " und $1")}.`);
  }

  if (operationTopics.length) {
    const details = [];
    if (topics.has("Addition und Subtraktion")) details.push("Additions- und Subtraktionsaufgaben sicher zu lösen");
    if (topics.has("Rechenstrategien und Zehnerübergang")) details.push("passende Rechenstrategien auszuwählen und beim Zehnerübergang anzuwenden");
    sentences.push(`Beim Rechnen benötigt _ Unterstützung, um ${details.join(" und ")}.`);
  }

  if (applicationTopics.length) {
    const details = [];
    if (topics.has("Aufgaben verstehen und Sachrechnen")) details.push("Aufgabenstellungen zu verstehen und Sachaufgaben zu strukturieren");
    if (topics.has("Größen und Messen")) details.push("Größen zu vergleichen, zu messen und passende Einheiten zu verwenden");
    if (topics.has("Geometrie, Muster und Raumvorstellung")) details.push("Formen, Muster und räumliche Beziehungen sicherer zu erfassen");
    sentences.push(`Mit anschaulichen Hilfen kann #er/sie# zunehmend ${details.join(", ").replace(/, ([^,]*)$/, " und $1")}.`);
  }

  return sentences.join(" ");
}

function composedMath12SelectionSuggestion(entries = []) {
  const selectedTopics = selectedMath12TemplateTopics(entries);
  if (!selectedTopics.length) return null;
  const baseTemplates = selectedTopics.map((topic) => ({
    topic,
    template: math12BaseTemplateForTopic(topic)
  }));
  if (baseTemplates.some((entry) => !entry.template)) return null;

  const firstFieldItem = (template, fieldKey) => german12TemplateFieldItems(template, fieldKey)[0] || "";

  return {
    template: {
      id: "",
      label: "Ausgewählte Mathematikbereiche Klasse 1/2"
    },
    composedFromBaseTemplates: true,
    selectedTopics,
    templateTopics: selectedTopics,
    visibleTopics: selectedTopics,
    suggestion: {
      istStand: composeMath12SelectionIstStand(selectedTopics),
      ziele: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "ziele")), "ziele"),
      massnahmen: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "massnahmen")), "massnahmen"),
      evaluation: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "evaluation")), "evaluation")
    }
  };
}

function math12FocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedMath12FocusTemplate(entries, variantOffset);
  if (!template) return composedMath12SelectionSuggestion(entries);
  const selectedTopics = selectedMath12TemplateTopics(entries);
  const templateTopics = normalizedMath12TemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: german12FocusListSuggestion(german12TemplateFieldItems(template, "ziele"), "ziele"),
      massnahmen: german12FocusListSuggestion(german12TemplateFieldItems(template, "massnahmen"), "massnahmen"),
      evaluation: german12FocusListSuggestion(german12TemplateFieldItems(template, "evaluation"), "evaluation")
    }
  };
}

