function canonicalMath34CompetenceTopic(topic = "") {
  const value = String(topic || "").trim();
  const aliases = {
    "Zahlenraum und Zahlvorstellung": "Zahlraum und Stellenwert",
    "Stellenwertverständnis": "Zahlraum und Stellenwert",
    "Schriftliche Rechenverfahren": "Rechenstrategien und schriftliche Verfahren",
    "Rechenstrategien und Kopfrechnen": "Rechenstrategien und schriftliche Verfahren",
    "Sachaufgaben": "Sachrechnen und Modellieren",
    Größen: "Größen und Messen",
    Geometrie: "Geometrie und Raumvorstellung"
  };
  return aliases[value] || value;
}

function normalizedMath34TemplateTopics(template = {}) {
  return (template.topics || [])
    .map(canonicalMath34CompetenceTopic)
    .filter((topic) => mathCompetenceTopics34.includes(topic));
}

function selectedMath34TemplateTopics(entries = []) {
  const selected = new Set(entries
    .map((entry) => canonicalMath34CompetenceTopic(entry.topic))
    .filter((topic) => mathCompetenceTopics34.includes(topic)));
  return mathCompetenceTopics34.filter((topic) => selected.has(topic));
}

function math34TemplatePriority(template = {}) {
  const count = normalizedMath34TemplateTopics(template).length;
  if (template.broad) return 10000;
  if (count === 8) return 9000;
  if (count === 7) return 8000;
  if (count === 6) return 7000;
  if (count === 5) return 6000;
  if (count === 4) return 5000;
  if (count === 3) return 4000;
  if (count === 2) return 3000;
  if (count === 1) return 2000;
  return 0;
}

function matchingMath34FocusTemplates(entries = []) {
  const selectedTopics = selectedMath34TemplateTopics(entries);
  if (!selectedTopics.length) return [];
  const selectedKey = selectedTopics.join("|");
  return math34FocusTemplateLibrary
    .map((template, index) => {
      const templateTopics = normalizedMath34TemplateTopics(template);
      return {
        template,
        index,
        templateTopics,
        exact: templateTopics.join("|") === selectedKey,
        priority: math34TemplatePriority(template)
      };
    })
    .filter((item) => item.exact)
    .sort((left, right) => right.priority - left.priority || left.index - right.index)
    .map((item) => item.template);
}

function selectedMath34FocusTemplate(entries = [], variantOffset = 0) {
  const matches = matchingMath34FocusTemplates(entries);
  if (!matches.length) return null;
  const index = ((variantOffset % matches.length) + matches.length) % matches.length;
  return matches[index];
}

function math34BaseTemplateForTopic(topic = "") {
  const canonicalTopic = canonicalMath34CompetenceTopic(topic);
  return math34FocusTemplateLibrary.find((template) => {
    const templateTopics = normalizedMath34TemplateTopics(template);
    return !template.broad && templateTopics.length === 1 && templateTopics[0] === canonicalTopic;
  }) || null;
}

function composedMath34SelectionSuggestion(entries = []) {
  const selectedTopics = selectedMath34TemplateTopics(entries);
  if (!selectedTopics.length) return null;
  const baseTemplates = selectedTopics.map((topic) => ({ topic, template: math34BaseTemplateForTopic(topic) }));
  if (baseTemplates.some((entry) => !entry.template)) return null;

  const istStandModules = baseTemplates.map(({ topic, template }, index) => ({
    area: "Mathematik",
    grade: "Klasse 3/4",
    topic,
    index,
    text: splitGeneratedFieldText(template.istStand)[0] || template.istStand
  }));
  const firstFieldItem = (template, fieldKey) => german12TemplateFieldItems(template, fieldKey)[0] || "";

  return {
    template: { id: "", label: "Ausgewählte Mathematikbereiche Klasse 3/4" },
    composedFromBaseTemplates: true,
    selectedTopics,
    templateTopics: selectedTopics,
    visibleTopics: selectedTopics,
    suggestion: {
      istStand: composeSelectedModuleText(istStandModules, "istStand"),
      ziele: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "ziele")), "ziele"),
      massnahmen: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "massnahmen")), "massnahmen"),
      evaluation: german12FocusListSuggestion(baseTemplates.map(({ template }) => firstFieldItem(template, "evaluation")), "evaluation")
    }
  };
}

function math34FocusTemplateSuggestion(entries = [], variantOffset = 0) {
  const template = selectedMath34FocusTemplate(entries, variantOffset);
  if (!template) return composedMath34SelectionSuggestion(entries);
  const selectedTopics = selectedMath34TemplateTopics(entries);
  const templateTopics = normalizedMath34TemplateTopics(template);
  return {
    template,
    selectedTopics,
    templateTopics,
    visibleTopics: templateTopics,
    suggestion: {
      istStand: finalizeClearIstStandText(template.istStand),
      ziele: german12FocusListSuggestion(german12TemplateFieldItems(template, "ziele"), "ziele"),
      massnahmen: german12FocusListSuggestion(german12TemplateFieldItems(template, "massnahmen"), "massnahmen"),
      evaluation: german12FocusListSuggestion(german12TemplateFieldItems(template, "evaluation"), "evaluation")
    }
  };
}

function selectedLearningModuleTopics(entries = []) {
  const selected = new Set((entries || [])
    .filter((entry) => entry.area === "Lern- und Leistungsverhalten")
    .map((entry) => canonicalLearningCompetenceTopic(entry.topic))
    .filter((topic) => learningCompetenceTopics.includes(topic)));
  return learningCompetenceTopics.filter((topic) => selected.has(topic));
}

function exactLearningFocusTemplateForTopics(topics = []) {
  const selectedTopics = (topics || []).map((topic) => canonicalLearningCompetenceTopic(topic)).filter(Boolean);
  if (!selectedTopics.length) return null;
  if (selectedTopics.length === 1) return learningSingleFocusTemplate(selectedTopics[0]);
  const selectedKey = selectedTopics.join("|");
  return learningFocusTemplatePool().find((template) => {
    if (template.broad) return false;
    const templateTopics = normalizedLearningTemplateTopics(template);
    return templateTopics.length === selectedTopics.length && templateTopics.join("|") === selectedKey;
  }) || null;
}

function broadLearningFocusTemplate() {
  return learningFocusTemplateLibrary.find((template) => template.id === "breiter-unterstuetzungsbedarf") || null;
}

function learningTemplateIstStandForTopics(topics = []) {
  const selectedTopics = (topics || []).map((topic) => canonicalLearningCompetenceTopic(topic)).filter(Boolean);
  if (!selectedTopics.length) return "";
  const entries = selectedTopics.map((topic, index) => ({
    area: "Lern- und Leistungsverhalten",
    topic,
    rating: "unsicher",
    index
  }));
  const template = selectedLearningFocusTemplate(entries, 0);
  if (!template) return "";
  if (template.broad) return learningBroadFocusIstStand(selectedTopics);
  if (template.istStand) return finalizeClearIstStandText(template.istStand);
  return "";
}

function composeLearningSelectedIstStandModules(selectedItems = []) {
  const entries = (selectedItems || [])
    .map((item, index) => selectedModuleEntryFromValue(item, index))
    .filter((entry) => entry.text)
    .map((entry) => ({
      ...entry,
      area: "Lern- und Leistungsverhalten",
      topic: canonicalLearningCompetenceTopic(entry.topic)
    }))
    .filter((entry) => entry.topic);
  if (!entries.length) return "";

  const selectedTopics = selectedLearningModuleTopics(entries);
  const templateText = learningTemplateIstStandForTopics(selectedTopics);
  if (templateText) return templateText;

  const themeGroups = selectedIstStandThemeGroups(entries);
  const intro = selectedIstStandIntroForThemes("Lern- und Leistungsverhalten", themeGroups)
    || "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim strukturierten Arbeiten.";
  return composeSelectedIstStandParagraphs(intro, themeGroups);
}

function activeLearningPilotIstStandTopics(entries = [], modules = []) {
  const selected = new Set([
    ...entries.map((entry) => canonicalCompetenceTopic("Lern- und Leistungsverhalten", entry.topic)),
    ...modules.map((module) => canonicalCompetenceTopic("Lern- und Leistungsverhalten", normalizeTextModuleEntry(module).topic))
  ].filter(Boolean));
  return learningCompetenceTopics.filter((topic) => selected.has(topic));
}

function capitalizeSentenceStart(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  return text.charAt(0).toLocaleUpperCase("de-DE") + text.slice(1);
}

function learningPilotIntroForTopics({ taskAccess = false, attention = false, organization = false }) {
  if (taskAccess && attention && organization) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim Erfassen von Aufgaben, beim konzentrierten Arbeiten und bei der strukturierten Organisation.";
  }
  if (taskAccess && attention) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim Erfassen von Aufgaben, beim Arbeitsbeginn und beim Dranbleiben.";
  }
  if (taskAccess && organization) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim Aufgabenverständnis, beim Arbeitsbeginn und beim strukturierten Arbeiten.";
  }
  if (attention && organization) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim konzentrierten Arbeiten, bei der Nutzung der Arbeitszeit und bei der Arbeitsorganisation.";
  }
  if (taskAccess) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim Erfassen von Aufgaben und beim sicheren Einstieg in die Arbeit.";
  }
  if (attention) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung dabei, Aufmerksamkeit, Ausdauer und Arbeitszeit passend zu steuern.";
  }
  if (organization) {
    return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim selbstständigen, sorgfältigen und strukturierten Arbeiten.";
  }
  return "Im Lern- und Leistungsverhalten benötigt _ Unterstützung beim strukturierten Arbeiten.";
}

function composeLearningPilotIstStand(entries = [], modules = []) {
  const topics = activeLearningPilotIstStandTopics(entries, modules);
  if (!topics.length) return "";
  if (topics.length === 1) {
    return finalizeClearIstStandText(learningPilotIstStandSections[topics[0]] || "");
  }

  const has = (topic) => topics.includes(topic);
  const taskAccess = topics.some((topic) =>
    ["Lernbereitschaft / Motivation", "Aufgabenverständnis", "Aufgabenbeginn"].includes(topic)
  );
  const attention = topics.some((topic) =>
    ["Konzentration / Aufmerksamkeit", "Ausdauer", "Arbeitstempo / Arbeitszeit nutzen"].includes(topic)
  );
  const organization = topics.some((topic) =>
    ["Selbstständigkeit", "Arbeitsorganisation / Material", "Sorgfalt / Genauigkeit"].includes(topic)
  );
  const focusLabels = {
    "Lernbereitschaft / Motivation": "bei Lernbereitschaft und Motivation",
    Aufgabenverständnis: "beim Aufgabenverständnis",
    Aufgabenbeginn: "beim Aufgabenbeginn",
    "Konzentration / Aufmerksamkeit": "bei Konzentration und Aufmerksamkeit",
    Ausdauer: "bei Ausdauer",
    Selbstständigkeit: "bei Selbstständigkeit",
    "Arbeitsorganisation / Material": "bei Arbeitsorganisation und Material",
    "Sorgfalt / Genauigkeit": "bei Sorgfalt und Genauigkeit",
    "Arbeitstempo / Arbeitszeit nutzen": "bei Arbeitstempo und Nutzung der Arbeitszeit"
  };
  const focuses = topics.map((topic) => focusLabels[topic]).filter(Boolean);
  const intro = topics.length > 3
    ? learningPilotIntroForTopics({ taskAccess, attention, organization })
    : `Im Lern- und Leistungsverhalten benötigt _ Unterstützung ${joinGermanList(focuses)}.`;
  const sentences = [intro];
  if (taskAccess) {
    const parts = [];
    if (has("Lernbereitschaft / Motivation")) parts.push("das Einlassen auf neue Lernangebote");
    if (has("Aufgabenverständnis")) parts.push("das sichere Erfassen von Aufgabenstellungen");
    if (has("Aufgabenbeginn")) parts.push("der Aufgabenbeginn");
    const verb = parts.length === 1 ? "gelingt" : "gelingen";
    sentences.push(`${capitalizeSentenceStart(joinGermanList(parts))} ${verb} besser, wenn Anforderungen klar gegliedert und erste Schritte überschaubar sind.`);
  }
  if (attention) {
    const parts = [];
    if (has("Konzentration / Aufmerksamkeit")) parts.push("das Halten der Aufmerksamkeit");
    if (has("Ausdauer")) parts.push("das Dranbleiben bei Schwierigkeiten");
    if (has("Arbeitstempo / Arbeitszeit nutzen")) parts.push("die passende Nutzung der Arbeitszeit");
    const verb = parts.length === 1 ? "gelingt" : "gelingen";
    sentences.push(`${capitalizeSentenceStart(joinGermanList(parts))} ${verb} verlässlicher, wenn Arbeitsphasen kurz strukturiert, Zwischenziele sichtbar gemacht und Rückmeldungen zeitnah gegeben werden.`);
  }
  if (organization) {
    const parts = [];
    if (has("Selbstständigkeit")) parts.push("das eigenständigere Fortführen bekannter Arbeitsschritte");
    if (has("Arbeitsorganisation / Material")) parts.push("die Ordnung von Material und Arbeitsplatz");
    if (has("Sorgfalt / Genauigkeit")) parts.push("die sorgfältige Kontrolle eigener Ergebnisse");
    const verb = parts.length === 1 ? "wird" : "werden";
    sentences.push(`${capitalizeSentenceStart(joinGermanList(parts))} ${verb} durch feste Routinen, Checklisten und übersichtliche Vorlagen unterstützt.`);
  }
  return finalizeClearIstStandText(removeRepeatedSentences(sentences).join(" "));
}

function composePilotIstStandFromCompetenceModules({ area, entries = [], modules = [] }) {
  if (area === "Sprache / Kommunikation") return composeSpeechPilotIstStand(entries, modules);
  if (area === "Kognition") return composeCognitionPilotIstStand(entries, modules);
  if (area === "Lern- und Leistungsverhalten") return composeLearningPilotIstStand(entries, modules);
  return "";
}

function smoothSelectedIstStandSentences(sentences = []) {
  const unique = removeRepeatedSentences(sentences.map(cleanSelectedIstStandSentence).filter(Boolean));
  return unique.map((sentence, index) => index === 0
    ? sentence
    : selectedModuleFollowUpSentence(sentence, index)
  );
}

function connectSelectedIstStandSentences(sentences = [], startIndex = 0) {
  const unique = removeRepeatedSentences(sentences.map(cleanSelectedIstStandSentence).filter(Boolean));
  const connected = [];
  unique.forEach((sentence, index) => {
    const position = startIndex + index;
    let result = sentence;
    if (position === 0) {
      connected.push(result);
      return;
    }
    if (/^(?:Dabei|Außerdem|Weiterhin|Besonders|In vertrauten Situationen|Mit Unterstützung)\b/i.test(sentence)) {
      result = sentence;
    } else if (/^Beim\s+/i.test(sentence)) {
      result = sentence.replace(/^Beim\s+/i, "Auch beim ");
    } else if (/^Bei\s+/i.test(sentence)) {
      result = sentence.replace(/^Bei\s+/i, "Auch bei ");
    } else if (sentence.startsWith("_ ")) {
      result = selectedModuleFollowUpSentence(sentence, position);
    } else {
      result = sentence.replace(/\s+_\s+/g, " #er/sie# ");
    }
    const previousStart = connected.at(-1)?.match(/^(Dabei|Außerdem|Weiterhin|Auch|Besonders)\b/i)?.[1]?.toLocaleLowerCase("de-DE");
    const currentStart = result.match(/^(Dabei|Außerdem|Weiterhin|Auch|Besonders)\b/i)?.[1]?.toLocaleLowerCase("de-DE");
    if (previousStart && currentStart === previousStart) {
      const replacement = currentStart === "dabei" ? "Außerdem" : currentStart === "außerdem" ? "Weiterhin" : currentStart === "auch" ? "Besonders" : "Dabei";
      result = result.replace(/^(Dabei|Außerdem|Weiterhin|Auch|Besonders)\b/i, replacement);
    }
    connected.push(result);
  });
  return connected;
}

function selectedIstStandTheme(area = "", topic = "") {
  const normalized = canonicalCompetenceTopic(area, topic);
  if (area === "Emotionalität, Sozialverhalten") {
    if (["Emotionsregulation", "Frustrationstoleranz", "Selbstbild / Selbstwirksamkeit", "Selbstkontrolle / Impulssteuerung"].includes(normalized)) return "emotional";
    if (normalized === "Belastbarkeit / Rückkehr in die Situation") return "recovery";
    if (["Kontaktverhalten", "Kooperationsverhalten", "Empathie / Hilfsbereitschaft"].includes(normalized)) return "cooperation";
    return "rules-feedback";
  }
  if (area === "Lern- und Leistungsverhalten") {
    if (["Lernbereitschaft / Motivation", "Aufgabenverständnis", "Aufgabenbeginn"].includes(normalized)) return "task-access";
    if (["Konzentration / Aufmerksamkeit", "Ausdauer"].includes(normalized)) return "attention";
    return "work-execution";
  }
  if (area === "Sprache / Kommunikation") {
    if (["Aussprache / Artikulation", "Lautwahrnehmung / phonologische Bewusstheit", "Stimme / Sprechweise"].includes(normalized)) return "clear-speech";
    if (normalized === "Sprachverständnis / Arbeitsaufträge") return "understanding";
    if (["Wortschatz / Wortbedeutung", "Grammatik / Satzbildung", "Redefluss / Wortfindung"].includes(normalized)) return "formulation";
    return "communication";
  }
  if (area === "Motorik") {
    if (["Grobmotorik", "Feinmotorik", "Graphomotorik"].includes(normalized)) return "execution";
    if (["Bilaterale Koordination", "Gleichgewicht / vestibuläre Sicherheit"].includes(normalized)) return "coordination-balance";
    return "planning";
  }
  if (area === "Kognition") {
    if (/Merk|Gedächtnis|Behalten|Abruf/i.test(normalized)) return "memory";
    if (/Strateg|Problemlös/i.test(normalized)) return "problem-solving";
    if (/Transfer|Schlussfolger|Zusammenhänge/i.test(normalized)) return "transfer-reasoning";
    return "symbols";
  }
  if (area === "Wahrnehmung") {
    return perceptionCategoryForTopic(normalized);
  }
  if (area === "Mathematik") {
    if (/Zahl|Menge|Stellenwert/i.test(normalized)) return "numbers";
    if (/Rechenstrateg|Kopfrechnen/i.test(normalized)) return "strategies";
    if (/Addition|Subtraktion|Multiplikation|Division|Rechenverfahren|Zehner/i.test(normalized)) return "operations";
    return "application";
  }
  return "general";
}

function selectedIstStandThemeGroups(entries = []) {
  const groups = [];
  selectedModuleTopicGroups(entries).forEach((topicGroup) => {
    const theme = selectedIstStandTheme(topicGroup.area, topicGroup.topic);
    let group = groups.find((item) => item.theme === theme);
    if (!group) {
      group = { theme, entries: [] };
      groups.push(group);
    }
    group.entries.push(...topicGroup.entries.sort((left, right) => left.index - right.index));
  });
  return groups;
}

