function xmlEscape(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function wordText(text) {
  return `<w:r><w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r>`;
}

function wordParagraph(text = "", { style = "", bold = false, alignment = "", fontSize = 0 } = {}) {
  const pPr = [
    style ? `<w:pStyle w:val="${style}"/>` : "",
    alignment ? `<w:jc w:val="${alignment}"/>` : ""
  ].filter(Boolean).join("");
  const rPrParts = [
    bold ? "<w:b/>" : "",
    fontSize ? `<w:sz w:val="${fontSize}"/>` : ""
  ].filter(Boolean).join("");
  const rPr = rPrParts ? `<w:rPr>${rPrParts}</w:rPr>` : "";
  const lines = String(text || "").split(/\r?\n/);
  const runs = lines.length
    ? lines.map((line, index) => `${index ? "<w:r><w:br/></w:r>" : ""}<w:r>${rPr}<w:t xml:space="preserve">${xmlEscape(line)}</w:t></w:r>`).join("")
    : "";
  return `<w:p>${pPr ? `<w:pPr>${pPr}</w:pPr>` : ""}${runs}</w:p>`;
}

function wordListParagraphs(text = "", columnKey = "") {
  return printListPresentationText(columnKey, text)
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const listItem = line.match(/^[–—•*-]\s+(.+)$/);
      if (!listItem) return wordParagraph(line);
      return `<w:p><w:pPr><w:ind w:left="360" w:hanging="220"/><w:spacing w:after="40"/></w:pPr>${wordText(`• ${listItem[1].trim()}`)}</w:p>`;
    })
    .join("") || wordParagraph("");
}

function wordCell(text = "", { bold = false, shade = "", width = 2400, listColumnKey = "", fontSize = 0 } = {}) {
  const paragraphs = listColumnKey
    ? wordListParagraphs(text, listColumnKey)
    : String(text || "").trim()
    ? String(text || "").split(/\n{2,}/).map((part) => wordParagraph(part, { bold, fontSize })).join("")
    : wordParagraph("");
  return `
    <w:tc>
      <w:tcPr>
        <w:tcW w:w="${width}" w:type="dxa"/>
        <w:vAlign w:val="top"/>
        <w:tcMar>
          <w:top w:w="40" w:type="dxa"/>
          <w:start w:w="80" w:type="dxa"/>
          <w:bottom w:w="40" w:type="dxa"/>
          <w:end w:w="80" w:type="dxa"/>
        </w:tcMar>
        ${shade ? `<w:shd w:fill="${shade}"/>` : ""}
      </w:tcPr>
      ${paragraphs}
    </w:tc>
  `;
}

function wordTable(rows = [], widths = [], { repeatFirstRow = false } = {}) {
  const totalWidth = widths.reduce((sum, item) => sum + item, 0);
  return `
    <w:tbl>
      <w:tblPr>
        <w:tblW w:w="${totalWidth}" w:type="dxa"/>
        <w:tblLayout w:type="fixed"/>
        <w:tblBorders>
          <w:top w:val="single" w:sz="6" w:space="0" w:color="000000"/>
          <w:left w:val="single" w:sz="6" w:space="0" w:color="000000"/>
          <w:bottom w:val="single" w:sz="6" w:space="0" w:color="000000"/>
          <w:right w:val="single" w:sz="6" w:space="0" w:color="000000"/>
          <w:insideH w:val="single" w:sz="6" w:space="0" w:color="000000"/>
          <w:insideV w:val="single" w:sz="6" w:space="0" w:color="000000"/>
        </w:tblBorders>
        <w:tblLook w:firstRow="1" w:lastRow="0" w:firstColumn="0" w:lastColumn="0"/>
      </w:tblPr>
      <w:tblGrid>${widths.map((width) => `<w:gridCol w:w="${width}"/>`).join("")}</w:tblGrid>
      ${rows.map((row, rowIndex) => `
        <w:tr>
          ${repeatFirstRow && rowIndex === 0 ? "<w:trPr><w:tblHeader/></w:trPr>" : ""}
          ${row.map((cell, index) => wordCell(cell.text || "", {
            bold: Boolean(cell.bold),
            shade: cell.shade || "",
            width: widths[index] || 2400,
            listColumnKey: cell.listColumnKey || "",
            fontSize: cell.fontSize || 0
          })).join("")}
        </w:tr>
      `).join("")}
    </w:tbl>
  `;
}

