function wordDocumentPackage(temporaryIdentity = {}) {
  return {
    "[Content_Types].xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
      <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
        <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
        <Default Extension="xml" ContentType="application/xml"/>
        <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
        <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
      </Types>`,
    "_rels/.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
      <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
        <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
      </Relationships>`,
    "word/_rels/document.xml.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
      <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>`,
    "word/document.xml": buildWordDocumentXml(temporaryIdentity),
    "word/styles.xml": wordStylesXml()
  };
}

function crc32(bytes) {
  let table = crc32.table;
  if (!table) {
    table = Array.from({ length: 256 }, (_, index) => {
      let value = index;
      for (let bit = 0; bit < 8; bit += 1) value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
      return value >>> 0;
    });
    crc32.table = table;
  }
  let crc = 0xffffffff;
  bytes.forEach((byte) => {
    crc = table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  });
  return (crc ^ 0xffffffff) >>> 0;
}

function writeUint32(target, offset, value) {
  target[offset] = value & 0xff;
  target[offset + 1] = (value >>> 8) & 0xff;
  target[offset + 2] = (value >>> 16) & 0xff;
  target[offset + 3] = (value >>> 24) & 0xff;
}

function writeUint16(target, offset, value) {
  target[offset] = value & 0xff;
  target[offset + 1] = (value >>> 8) & 0xff;
}

function dosDateTime(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  return {
    time: (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2),
    date: ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()
  };
}

function concatBytes(parts) {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const output = new Uint8Array(total);
  let offset = 0;
  parts.forEach((part) => {
    output.set(part, offset);
    offset += part.length;
  });
  return output;
}

function createZipBlob(files) {
  const encoder = new TextEncoder();
  const localParts = [];
  const centralParts = [];
  const { time, date } = dosDateTime();
  let offset = 0;
  Object.entries(files).forEach(([name, content]) => {
    const nameBytes = encoder.encode(name);
    const dataBytes = encoder.encode(content);
    const crc = crc32(dataBytes);
    const local = new Uint8Array(30 + nameBytes.length);
    writeUint32(local, 0, 0x04034b50);
    writeUint16(local, 4, 20);
    writeUint16(local, 6, 0x0800);
    writeUint16(local, 8, 0);
    writeUint16(local, 10, time);
    writeUint16(local, 12, date);
    writeUint32(local, 14, crc);
    writeUint32(local, 18, dataBytes.length);
    writeUint32(local, 22, dataBytes.length);
    writeUint16(local, 26, nameBytes.length);
    writeUint16(local, 28, 0);
    local.set(nameBytes, 30);
    localParts.push(local, dataBytes);

    const central = new Uint8Array(46 + nameBytes.length);
    writeUint32(central, 0, 0x02014b50);
    writeUint16(central, 4, 20);
    writeUint16(central, 6, 20);
    writeUint16(central, 8, 0x0800);
    writeUint16(central, 10, 0);
    writeUint16(central, 12, time);
    writeUint16(central, 14, date);
    writeUint32(central, 16, crc);
    writeUint32(central, 20, dataBytes.length);
    writeUint32(central, 24, dataBytes.length);
    writeUint16(central, 28, nameBytes.length);
    writeUint16(central, 30, 0);
    writeUint16(central, 32, 0);
    writeUint16(central, 34, 0);
    writeUint16(central, 36, 0);
    writeUint32(central, 38, 0);
    writeUint32(central, 42, offset);
    central.set(nameBytes, 46);
    centralParts.push(central);
    offset += local.length + dataBytes.length;
  });
  const centralStart = offset;
  const centralBytes = concatBytes(centralParts);
  const end = new Uint8Array(22);
  writeUint32(end, 0, 0x06054b50);
  writeUint16(end, 4, 0);
  writeUint16(end, 6, 0);
  writeUint16(end, 8, Object.keys(files).length);
  writeUint16(end, 10, Object.keys(files).length);
  writeUint32(end, 12, centralBytes.length);
  writeUint32(end, 16, centralStart);
  writeUint16(end, 20, 0);
  return new Blob([concatBytes([...localParts, centralBytes, end])], {
    type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
  });
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function supportsSaveFilePicker() {
  return !!window.isSecureContext && typeof window.showSaveFilePicker === "function";
}

async function saveJsonFileWithPickerOrDownload(payload, filename) {
  const content = typeof payload === "string" ? payload : JSON.stringify(payload, null, 2);
  const blob = new Blob([content], { type: "application/json" });
  if (supportsSaveFilePicker()) {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: filename,
        types: [{
          description: "JSON-Datei",
          accept: { "application/json": [".json"] }
        }]
      });
      const writable = await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return { status: "picker", filename: handle.name || filename };
    } catch (error) {
      if (error?.name === "AbortError") return { status: "cancelled", filename: "" };
      console.warn("JSON save picker failed; using browser download instead", error);
      downloadBlob(blob, filename);
      return { status: "download", filename };
    }
  }
  downloadBlob(blob, filename);
  return { status: "download", filename };
}

function exportSaveStatus(label, result) {
  if (result.status === "cancelled") return "Speichern abgebrochen.";
  if (result.status === "download") {
    return `${label} gespeichert. Der Browser unterstützt keine freie Speicherortauswahl. Die Datei wird über den normalen Download gespeichert.`;
  }
  if (result.status === "picker") return `${label} gespeichert.`;
  return `${label} konnte nicht gespeichert werden.`;
}

function openWordExportDialog() {
  syncVisibleInputs();
  if (!wordExportDialog) {
    exportWordPlanAfterIdentityCheck({});
    return;
  }
  wordExportFirstNameInput.value = "";
  wordExportLastNameInput.value = "";
  wordExportDialogStatus.textContent = "";
  wordExportDialog.classList.remove("hidden");
  wordExportFirstNameInput.focus();
}

function closeWordExportDialog() {
  wordExportDialog?.classList.add("hidden");
  if (wordExportFirstNameInput) wordExportFirstNameInput.value = "";
  if (wordExportLastNameInput) wordExportLastNameInput.value = "";
  if (wordExportDialogStatus) wordExportDialogStatus.textContent = "";
}

function confirmWordExportIdentity() {
  const temporaryIdentity = {
    firstName: String(wordExportFirstNameInput?.value || "").trim(),
    lastName: String(wordExportLastNameInput?.value || "").trim()
  };
  if (!temporaryIdentity.firstName) {
    wordExportDialogStatus.textContent = "Bitte den Vornamen für diese Word-Ausgabe eintragen.";
    wordExportFirstNameInput?.focus();
    return;
  }
  closeWordExportDialog();
  exportWordPlanAfterIdentityCheck(temporaryIdentity);
}

function exportWordPlanAfterIdentityCheck(temporaryIdentity = {}) {
  saveCurrentPlan({ silent: true });
  const blob = createZipBlob(wordDocumentPackage(temporaryIdentity));
  const filename = `${filenamePlanId(plan.displayId)}-${new Date().toISOString().slice(0, 10)}.docx`;
  downloadBlob(blob, filename);
  statusMessage = "Word-Datei wurde lokal erzeugt. Bitte nur an einem geschützten Ort speichern.";
  if (currentStep === "print") renderPrintPage();
}

function configurePrintDialog(mode = "plan") {
  const title = printDialog.querySelector("#print-dialog-title");
  const description = printDialog.querySelector("p");
  const printsEmptyCompetenceTemplate = mode === "competence" && !hasCompetenceData();
  if (title) {
    title.textContent = mode === "competence"
      ? (printsEmptyCompetenceTemplate ? "Kompetenzraster-Vorlage drucken" : "Name für das Kompetenzraster prüfen")
      : "Name für den Ausdruck prüfen";
  }
  if (description) {
    description.textContent = printsEmptyCompetenceTemplate
      ? "Es wurden keine ausgefüllten Kompetenzdaten gefunden. Es wird eine leere Kompetenzraster-Vorlage gedruckt. Optional kann ein Name nur für diesen Ausdruck eingetragen werden."
      : mode === "competence"
      ? "Optional kann ein Name nur für diesen Kompetenzraster-Ausdruck eingetragen werden. Diese Eingabe wird nicht gespeichert."
      : "Falls nötig, kann der Name für diesen Ausdruck abweichend eingetragen werden. Diese Eingabe wird nicht zusätzlich gespeichert.";
  }
}

function openPrintDialog(mode = "plan") {
  saveCurrentPlan({ silent: true });
  pendingPrintMode = mode === "competence" ? "competence" : "plan";
  configurePrintDialog(pendingPrintMode);
  clearTemporaryPrintNames();
  printDialog.classList.remove("hidden");
  printFirstNameInput.focus();
}

function closePrintDialog() {
  clearTemporaryPrintNames();
  pendingPrintMode = "plan";
  printDialog.classList.add("hidden");
}

function clearTemporaryPrintNames() {
  pendingPrintFirstName = "";
  pendingPrintLastName = "";
  printFirstNameInput.value = "";
  printLastNameInput.value = "";
}

function printWithTemporaryName() {
  pendingPrintFirstName = printFirstNameInput.value.trim();
  pendingPrintLastName = printLastNameInput.value.trim();
  const printMode = pendingPrintMode;
  const temporaryIdentity = {
    firstName: pendingPrintFirstName,
    lastName: pendingPrintLastName
  };
  printFirstNameInput.value = "";
  printLastNameInput.value = "";
  printDialog.classList.add("hidden");
  printRoot.innerHTML = printMode === "competence"
    ? renderCompetenceRasterPrintDocument(temporaryIdentity)
    : renderPrintDocument(temporaryIdentity);
  const previousTitle = document.title;
  document.title = printMode === "competence" ? "Kompetenzraster" : planTypeLabel();
  let cleaned = false;
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    clearTemporaryPrintNames();
    pendingPrintMode = "plan";
    printRoot.innerHTML = "";
    document.title = previousTitle;
    statusMessage = printMode === "competence"
      ? "Das Kompetenzraster wurde nur für diese Ausgabe mit der temporären Namenseingabe erstellt. Der Name wurde nicht gespeichert."
      : "Die abweichende Namenseingabe wurde nur für diese Ausgabe verwendet und nicht zusätzlich gespeichert.";
    window.removeEventListener("afterprint", cleanup);
    if (currentStep === "print") renderPrintPage();
  };
  window.addEventListener("afterprint", cleanup);
  window.print();
  setTimeout(cleanup, 900);
}

function printIdMappingList() {
  const rows = collectIdMappingPrintRows();
  printRoot.innerHTML = renderIdMappingPrintDocument(rows);
  const previousTitle = document.title;
  document.title = "ID-Zuordnungsliste";
  let cleaned = false;
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    printRoot.innerHTML = "";
    document.title = previousTitle;
    statusMessage = "Die ID-Zuordnungsliste wurde nur für den Ausdruck erstellt. Temporäre Namenseingaben wurden verworfen.";
    window.removeEventListener("afterprint", cleanup);
    if (currentStep === "idMapping") renderIdMappingList();
  };
  window.addEventListener("afterprint", cleanup);
  window.print();
  setTimeout(cleanup, 900);
}

function renderAfterStorageAction() {
  if (currentStep === "storage") renderStoragePage();
  else if (currentStep === "raster") renderRaster();
  else if (currentStep === "drafts") renderDrafts();
  else if (currentStep === "print") renderPrintPage();
  else renderStart();
}

async function exportCustomModules() {
  const modules = loadCustomModules();
  const payload = {
    type: "customTextModules",
    exportedAt: new Date().toISOString(),
    warning: "Eigene Bausteine können personenbezogene oder schulinterne Inhalte enthalten. Bitte sicher speichern.",
    modules
  };
  const filename = `foerderplanung-direkt-eigene-bausteine_${new Date().toISOString().slice(0, 10)}.json`;
  const result = await saveJsonFileWithPickerOrDownload(payload, filename);
  statusMessage = exportSaveStatus("Eigene Bausteine", result);
  renderAfterStorageAction();
}

function importCustomModules(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.addEventListener("load", () => {
    try {
      const parsed = JSON.parse(reader.result);
      const incoming = Array.isArray(parsed.modules) ? parsed.modules : Array.isArray(parsed) ? parsed : [];
      const normalized = incoming.map(normalizeCustomModule).filter(Boolean);
      if (!normalized.length) throw new Error("no custom modules");
      const existing = loadCustomModules();
      const merged = new Map(existing.map((item) => [item.id, item]));
      const duplicateKeys = new Set(existing.map(customModuleDuplicateKey));
      let added = 0;
      let skipped = incoming.length - normalized.length;
      normalized.forEach((item) => {
        const key = customModuleDuplicateKey(item);
        if (duplicateKeys.has(key)) {
          skipped += 1;
          return;
        }
        duplicateKeys.add(key);
        merged.set(item.id || customModuleId(), item);
        added += 1;
      });
      saveCustomModules([...merged.values()]);
      statusMessage = added
        ? `Eigene Bausteine wurden importiert. ${added} neu, ${skipped} übersprungen.`
        : "Keine neuen eigenen Bausteine importiert. Doppelte oder fehlerhafte Einträge wurden übersprungen.";
      renderAfterStorageAction();
    } catch (error) {
      console.error("Custom module import failed", error);
      statusMessage = "Die eigenen Bausteine konnten nicht importiert werden.";
      renderAfterStorageAction();
    }
  });
  reader.readAsText(file);
}

function teamFilePayloadForPlan(item) {
  const draft = sanitizeBeforeSave(normalizePlan(item));
  return {
    teamMeta: {
      appName: "FörderKompass",
      exportedAt: new Date().toISOString(),
      dataType: "team-file",
      containsRealNames: false,
      note: "Anonymisierte Team-Datei zur Weitergabe. Keine Live-Zusammenarbeit und keine Cloud-Synchronisation."
    },
    plans: [draft]
  };
}

async function exportTeamFileForPlan(item) {
  const payload = teamFilePayloadForPlan(item);
  const displayId = payload.plans[0]?.displayId || item?.displayId || plan.displayId || "foerderplan";
  const filename = `${teamFilenamePlanId(displayId)}_Teamdatei_${new Date().toISOString().slice(0, 10)}.json`;
  return saveJsonFileWithPickerOrDownload(payload, filename);
}

async function exportTeamFileById(id) {
  const found = loadDrafts().find((item) => item.id === id);
  if (!found) {
    statusMessage = "Der Entwurf konnte nicht als Team-Datei exportiert werden.";
    if (currentStep === "drafts") renderDrafts();
    else renderStart();
    return;
  }
  const result = await exportTeamFileForPlan(found);
  statusMessage = exportSaveStatus("Team-Datei", result);
  if (currentStep === "drafts") renderDrafts();
  else renderStart();
}

async function exportCurrentTeamFile() {
  syncVisibleInputs();
  saveCurrentPlan({ silent: true });
  const result = await exportTeamFileForPlan(plan);
  statusMessage = exportSaveStatus("Team-Datei", result);
  if (currentStep === "print") renderPrintPage();
  else if (currentStep === "drafts") renderDrafts();
  else if (currentStep === "storage") renderStoragePage();
  else if (currentStep === "start") renderStart();
}

async function exportBackup() {
  const drafts = loadDrafts().map(sanitizeBeforeSave);
  const customTextModules = loadCustomModules();
  const settings = backupLocalSettings();
  const exportedAt = new Date().toISOString();
  const payload = {
    backupMeta: {
      appName: "FörderKompass",
      appVersion: APP_VERSION,
      dataFormatVersion: "2",
      copyright: "© 2026 Ute Holzschneider-Riedl. Alle Rechte vorbehalten.",
      author: "Ute Holzschneider-Riedl",
      exportedAt,
      createdAt: exportedAt,
      backupType: "full-backup",
      dataType: "full-backup",
      containsRealNames: false
    },
    plans: drafts,
    customTextModules,
    settings
  };
  const filename = `${BACKUP_NAME}_${new Date().toISOString().slice(0, 10)}.json`;
  const result = await saveJsonFileWithPickerOrDownload(payload, filename);
  statusMessage = exportSaveStatus("Backup", result);
  renderAfterStorageAction();
}

function backupLocalSettings() {
  return {
    speechTermDisplayMode: storedSpeechTermDisplayMode()
  };
}

function localSettingsForWorkFile() {
  return {
    storageKey: STORAGE_KEY,
    customModuleStorageKey: CUSTOM_MODULE_STORAGE_KEY
  };
}

function supportsPersistentWorkFile() {
  return !!window.isSecureContext
    && typeof window.showOpenFilePicker === "function"
    && typeof window.showSaveFilePicker === "function"
    && "indexedDB" in window;
}

function supportsFileSystemAccess() {
  return !!window.isSecureContext
    && typeof window.showDirectoryPicker === "function"
    && typeof window.showOpenFilePicker === "function"
    && typeof window.showSaveFilePicker === "function"
    && "indexedDB" in window;
}

function rememberWorkFileName(name, { connected = false } = {}) {
  const cleanName = String(name || "").trim();
  if (!cleanName) return;
  localStorage.setItem(WORK_FILE_LAST_NAME_KEY, cleanName);
  if (connected) localStorage.setItem(WORK_FILE_CONNECTED_NAME_KEY, cleanName);
}

function getLastWorkFileName() {
  return localStorage.getItem(WORK_FILE_LAST_NAME_KEY) || "";
}

function getConnectedWorkFileName() {
  return localStorage.getItem(WORK_FILE_CONNECTED_NAME_KEY) || "";
}

function workFileHandleStore(mode = "readonly") {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(WORK_FILE_HANDLE_DB, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(WORK_FILE_HANDLE_STORE)) {
        db.createObjectStore(WORK_FILE_HANDLE_STORE);
      }
    };
    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const db = request.result;
      const transaction = db.transaction(WORK_FILE_HANDLE_STORE, mode);
      transaction.oncomplete = () => db.close();
      transaction.onerror = () => {
        db.close();
        reject(transaction.error);
      };
      resolve(transaction.objectStore(WORK_FILE_HANDLE_STORE));
    };
  });
}

async function saveConnectedWorkFileHandle(handle) {
  if (!supportsPersistentWorkFile()) return;
  const store = await workFileHandleStore("readwrite");
  await new Promise((resolve, reject) => {
    const request = store.put(handle, WORK_FILE_HANDLE_KEY);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
  rememberWorkFileName(handle?.name || WORK_FILE_NAME, { connected: true });
}

async function loadConnectedWorkFileHandle() {
  if (!supportsPersistentWorkFile()) return null;
  const store = await workFileHandleStore("readonly");
  return new Promise((resolve) => {
    const request = store.get(WORK_FILE_HANDLE_KEY);
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => resolve(null);
  });
}

async function clearConnectedWorkFileHandle() {
  if (!supportsPersistentWorkFile()) {
    connectedWorkFileHandle = null;
    workFilePermissionState = "unknown";
    localStorage.removeItem(WORK_FILE_CONNECTED_NAME_KEY);
    return;
  }
  const store = await workFileHandleStore("readwrite");
  await new Promise((resolve) => {
    const request = store.delete(WORK_FILE_HANDLE_KEY);
    request.onsuccess = () => resolve();
    request.onerror = () => resolve();
  });
  connectedWorkFileHandle = null;
  workFilePermissionState = "unknown";
  localStorage.removeItem(WORK_FILE_CONNECTED_NAME_KEY);
}

async function saveSelectedWorkDirectoryHandle(handle) {
  if (!supportsFileSystemAccess()) return;
  const store = await workFileHandleStore("readwrite");
  await new Promise((resolve, reject) => {
    const request = store.put(handle, WORK_DIRECTORY_HANDLE_KEY);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

async function loadSelectedWorkDirectoryHandle() {
  if (!supportsFileSystemAccess()) return null;
  const store = await workFileHandleStore("readonly");
  return new Promise((resolve) => {
    const request = store.get(WORK_DIRECTORY_HANDLE_KEY);
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => resolve(null);
  });
}

async function initializeSelectedWorkDirectory() {
  if (supportsFileSystemAccess()) {
    selectedWorkDirectoryHandle = await loadSelectedWorkDirectoryHandle();
    if (selectedWorkDirectoryHandle) {
      workDirectoryPermissionState = await queryWorkDirectoryPermission(selectedWorkDirectoryHandle);
      workDirectoryStatusMessage = workDirectoryPermissionState === "granted"
        ? `Arbeitsordner verbunden: ${selectedWorkDirectoryHandle.name}`
        : "Ein Arbeitsordner ist gespeichert. Der Zugriff muss nach einer bewussten Aktion erneut bestätigt werden.";
    }
  }
  if (supportsPersistentWorkFile()) {
    connectedWorkFileHandle = await loadConnectedWorkFileHandle();
    if (connectedWorkFileHandle) {
      workFilePermissionState = await queryWorkFilePermission(connectedWorkFileHandle, "readwrite");
      rememberWorkFileName(connectedWorkFileHandle.name || WORK_FILE_NAME, { connected: true });
    } else if (getConnectedWorkFileName()) {
      rememberWorkFileName(getConnectedWorkFileName());
      localStorage.removeItem(WORK_FILE_CONNECTED_NAME_KEY);
    }
  }
}

function isWorkDirectoryAutoSyncEnabled() {
  return localStorage.getItem(WORK_DIRECTORY_AUTO_SYNC_KEY) === "true";
}

function setWorkDirectoryAutoSync(enabled) {
  if (enabled && !selectedWorkDirectoryHandle) {
    localStorage.removeItem(WORK_DIRECTORY_AUTO_SYNC_KEY);
    return;
  }
  if (enabled) localStorage.setItem(WORK_DIRECTORY_AUTO_SYNC_KEY, "true");
  else localStorage.removeItem(WORK_DIRECTORY_AUTO_SYNC_KEY);
}

async function queryWorkDirectoryPermission(handle) {
  if (!handle || typeof handle.queryPermission !== "function") return "granted";
  try {
    return await handle.queryPermission({ mode: "readwrite" });
  } catch {
    return "prompt";
  }
}

async function ensureWorkDirectoryWritePermission(handle, { requestPermission = true } = {}) {
  if (!handle) return false;
  const permission = await queryWorkDirectoryPermission(handle);
  workDirectoryPermissionState = permission;
  if (permission === "granted") return true;
  if (requestPermission && typeof handle.requestPermission === "function") {
    workDirectoryPermissionState = await handle.requestPermission({ mode: "readwrite" });
    return workDirectoryPermissionState === "granted";
  }
  return false;
}

async function writeWorkFileToDirectory(handle, { requestPermission = true, allowExisting = false } = {}) {
  const hasPermission = await ensureWorkDirectoryWritePermission(handle, { requestPermission });
  if (!hasPermission) {
    const error = new Error("missing directory permission");
    error.code = "permission";
    throw error;
  }
  if (!allowExisting) {
    try {
      await handle.getFileHandle(WORK_FILE_NAME);
      const error = new Error("work file already exists");
      error.code = "exists";
      throw error;
    } catch (error) {
      if (error?.code === "exists") throw error;
      if (error?.name !== "NotFoundError") throw error;
    }
  }
  const fileHandle = await handle.getFileHandle(WORK_FILE_NAME, { create: true });
  const writable = await fileHandle.createWritable();
  await writable.write(JSON.stringify(workFilePayload({ skipSave: true }), null, 2));
  await writable.close();
  return { savedAt: new Date().toISOString(), fileHandle };
}

async function chooseWorkDirectory() {
  if (!supportsFileSystemAccess()) {
    workDirectoryStatusMessage = "Ihr Browser unterstützt die direkte Ordnerspeicherung nicht. Bitte verwenden Sie Microsoft Edge oder Google Chrome oder speichern Sie Arbeitsdateien wie bisher über den Downloadordner.";
    renderAfterStorageAction();
    return;
  }
  try {
    const pickerOptions = { mode: "readwrite" };
    if (selectedWorkDirectoryHandle) pickerOptions.startIn = selectedWorkDirectoryHandle;
    const handle = await window.showDirectoryPicker(pickerOptions);
    selectedWorkDirectoryHandle = handle;
    await saveSelectedWorkDirectoryHandle(handle);
    workDirectoryPermissionState = await queryWorkDirectoryPermission(handle);
    localStorage.removeItem(WORK_DIRECTORY_FILE_NAME_KEY);
    setWorkDirectoryAutoSync(false);
    workDirectoryStatusMessage = `Arbeitsordner ausgewählt: ${handle.name}`;
    renderAfterStorageAction();
  } catch (error) {
    if (error?.name !== "AbortError") {
      console.error("Work directory selection failed", error);
      workDirectoryStatusMessage = "Der Arbeitsordner konnte nicht ausgewählt werden.";
      renderAfterStorageAction();
    }
  }
}

async function saveWorkFileToSelectedDirectory({ silent = false, requestPermission = true, allowExisting = false } = {}) {
  if (!supportsFileSystemAccess()) {
    workDirectoryStatusMessage = "Ihr Browser unterstützt die direkte Ordnerspeicherung nicht. Bitte verwenden Sie Microsoft Edge oder Google Chrome oder speichern Sie Arbeitsdateien wie bisher über den Downloadordner.";
    if (!silent) renderAfterStorageAction();
    return false;
  }
  try {
    if (!selectedWorkDirectoryHandle) selectedWorkDirectoryHandle = await loadSelectedWorkDirectoryHandle();
    if (!selectedWorkDirectoryHandle) {
      workDirectoryStatusMessage = "Noch kein Arbeitsordner ausgewählt.";
      if (!silent) renderAfterStorageAction();
      return false;
    }
    const { savedAt, fileHandle } = await writeWorkFileToDirectory(selectedWorkDirectoryHandle, { requestPermission, allowExisting });
    connectedWorkFileHandle = fileHandle;
    await saveConnectedWorkFileHandle(fileHandle);
    workFilePermissionState = "granted";
    localStorage.setItem(WORK_DIRECTORY_FILE_NAME_KEY, WORK_FILE_NAME);
    setWorkDirectoryAutoSync(false);
    rememberWorkFileName(fileHandle.name || WORK_FILE_NAME, { connected: true });
    workDirectoryStatusMessage = `Arbeitsordner: ${selectedWorkDirectoryHandle.name}`;
    workFileStatusMessage = "Arbeitsdatei wurde gespeichert.";
    localStorage.setItem(WORK_FILE_NOTICE_KEY, "true");
    if (!silent) renderAfterStorageAction();
    return true;
  } catch (error) {
    if (!["permission", "exists"].includes(error?.code)) console.error("Work directory save failed", error);
    workDirectoryStatusMessage = error?.code === "permission"
      ? "Der Zugriff auf den Arbeitsordner fehlt. Bitte den Ordner erneut auswählen oder den Zugriff nach einem Klick bestätigen."
      : error?.code === "exists"
      ? `Im ausgewählten Ordner gibt es bereits ${WORK_FILE_NAME}. Bitte diese Datei über „Arbeitsdatei öffnen“ verbinden oder einen anderen Ordner wählen. Die vorhandene Datei wurde nicht überschrieben.`
      : "Die Arbeitsdatei konnte nicht im Arbeitsordner gespeichert werden. Bitte den Arbeitsordner erneut auswählen.";
    if (!silent) renderAfterStorageAction();
    return false;
  }
}

async function updateSelectedWorkDirectoryAfterSave({ manual = false } = {}) {
  if (!supportsFileSystemAccess() || !isWorkDirectoryAutoSyncEnabled() || workDirectorySyncInProgress) return "skipped";
  workDirectorySyncInProgress = true;
  try {
    const saved = await saveWorkFileToSelectedDirectory({ silent: true, requestPermission: manual, allowExisting: true });
    if (saved) {
      if (manual) {
        statusMessage = "Entwurf gespeichert. Arbeitsdatei aktualisiert.";
        render();
      } else {
        setAutosaveStatus("Automatisch gespeichert · Arbeitsdatei aktualisiert");
      }
    }
    if (manual && !saved) {
      statusMessage = "Entwurf lokal gespeichert. Die verbundene Arbeitsdatei konnte nicht aktualisiert werden.";
      render();
      renderWorkFileSaveFailureDialog();
    }
    return saved ? "updated" : "failed";
  } finally {
    workDirectorySyncInProgress = false;
  }
}

async function queryWorkFilePermission(handle, mode = "readwrite") {
  if (!handle || typeof handle.queryPermission !== "function") return "granted";
  try {
    return await handle.queryPermission({ mode });
  } catch {
    return "prompt";
  }
}

async function ensureWorkFileWritePermission(handle, { requestPermission = true } = {}) {
  if (!handle) return false;
  const options = { mode: "readwrite" };
  workFilePermissionState = await queryWorkFilePermission(handle, "readwrite");
  if (workFilePermissionState === "granted") return true;
  if (requestPermission && typeof handle.requestPermission === "function") {
    workFilePermissionState = await handle.requestPermission(options);
    return workFilePermissionState === "granted";
  }
  return false;
}

async function ensureWorkFileReadPermission(handle, { requestPermission = true } = {}) {
  if (!handle) return false;
  const options = { mode: "read" };
  const permission = await queryWorkFilePermission(handle, "read");
  if (permission === "granted") return true;
  if (requestPermission && typeof handle.requestPermission === "function") {
    return await handle.requestPermission(options) === "granted";
  }
  return false;
}

function workFilePayload({ skipSave = false } = {}) {
  syncVisibleInputs();
  if (!skipSave && currentStep !== "start") saveCurrentPlan({ silent: true, skipConnectedWorkFile: true, skipWorkDirectory: true });
  const now = new Date().toISOString();
  return {
    arbeitsdateiMeta: {
      appName: "FörderKompass",
      appVersion: APP_VERSION,
      exportedAt: now,
      updatedAt: now,
      dataType: "work-file",
      containsRealNames: false,
      note: "Lokale Arbeitsdatei mit Förderplanentwürfen und eigenen Bausteinen. Keine temporären Drucknamen enthalten."
    },
    drafts: loadDrafts().map(sanitizeBeforeSave),
    customModules: loadCustomModules(),
    settings: localSettingsForWorkFile()
  };
}

async function writeWorkFileToHandle(handle, { requestPermission = true } = {}) {
  const hasPermission = await ensureWorkFileWritePermission(handle, { requestPermission });
  if (!hasPermission) {
    const error = new Error("missing file permission");
    error.code = "permission";
    throw error;
  }
  const writable = await handle.createWritable();
  await writable.write(JSON.stringify(workFilePayload({ skipSave: true }), null, 2));
  await writable.close();
}

async function updateConnectedWorkFileAfterSave({ manual = false } = {}) {
  if (workFileSyncInProgress) return "busy";
  if (!hasConnectedWorkFileReference()) return "not-connected";
  if (!supportsPersistentWorkFile()) {
    workFileStatusMessage = "Entwurf lokal gespeichert. Die verbundene Arbeitsdatei konnte nicht aktualisiert werden.";
    if (manual) {
      statusMessage = workFileStatusMessage;
      render();
      renderWorkFileSaveFailureDialog();
    } else {
      setAutosaveStatus("Automatisch gespeichert · Arbeitsdatei nicht aktualisiert");
    }
    return "failed";
  }
  workFileSyncInProgress = true;
  try {
    if (!connectedWorkFileHandle) connectedWorkFileHandle = await loadConnectedWorkFileHandle();
    if (!connectedWorkFileHandle) throw new Error("missing connected work file handle");
    await writeWorkFileToHandle(connectedWorkFileHandle, { requestPermission: manual });
    rememberWorkFileName(connectedWorkFileHandle.name || WORK_FILE_NAME, { connected: true });
    workFileStatusMessage = "Verbundene Arbeitsdatei wurde aktualisiert.";
    if (manual) {
      statusMessage = "Entwurf gespeichert. Arbeitsdatei aktualisiert.";
      render();
    } else {
      setAutosaveStatus("Automatisch gespeichert · Arbeitsdatei aktualisiert");
    }
    return "updated";
  } catch (error) {
    if (error?.code !== "permission") console.error("Connected work file update failed", error);
    workFileStatusMessage = error?.code === "permission"
      ? "Entwurf lokal gespeichert. Der Zugriff auf die Arbeitsdatei muss nach einer bewussten Aktion erneut bestätigt werden."
      : "Entwurf lokal gespeichert. Die verbundene Arbeitsdatei konnte nicht aktualisiert werden.";
    if (manual) {
      statusMessage = workFileStatusMessage;
      render();
      renderWorkFileSaveFailureDialog();
    } else {
      setAutosaveStatus("Automatisch gespeichert · Arbeitsdatei nicht aktualisiert");
    }
    return "failed";
  } finally {
    workFileSyncInProgress = false;
  }
}

async function saveWorkFile() {
  if (supportsPersistentWorkFile()) {
    try {
      if (!connectedWorkFileHandle) connectedWorkFileHandle = await loadConnectedWorkFileHandle();
      if (connectedWorkFileHandle) {
        await writeWorkFileToHandle(connectedWorkFileHandle, { requestPermission: true });
        await saveConnectedWorkFileHandle(connectedWorkFileHandle);
        rememberWorkFileName(connectedWorkFileHandle.name || WORK_FILE_NAME, { connected: true });
        localStorage.setItem(WORK_FILE_NOTICE_KEY, "true");
        workFilePermissionState = "granted";
        workFileStatusMessage = "Arbeitsdatei wurde gespeichert.";
        statusMessage = workFileStatusMessage;
        renderAfterStorageAction();
        return;
      }
      if (!selectedWorkDirectoryHandle && supportsFileSystemAccess()) {
        selectedWorkDirectoryHandle = await loadSelectedWorkDirectoryHandle();
      }
      if (selectedWorkDirectoryHandle) {
        const saved = await saveWorkFileToSelectedDirectory({ requestPermission: true });
        statusMessage = saved
          ? workFileStatusMessage || "Arbeitsdatei wurde gespeichert."
          : workDirectoryStatusMessage || "Die Arbeitsdatei konnte nicht gespeichert werden.";
        renderAfterStorageAction();
        return;
      }
      await connectNewWorkFile();
      return;
    } catch (error) {
      if (error?.code !== "permission") console.error("Work file save failed", error);
      workFileStatusMessage = error?.code === "permission"
        ? "Der Zugriff auf die aktuelle Arbeitsdatei fehlt. Bitte die Arbeitsdatei erneut auswählen oder den Zugriff nach einem Klick bestätigen."
        : "Die Arbeitsdatei konnte nicht gespeichert werden.";
      statusMessage = workFileStatusMessage;
      renderAfterStorageAction();
      return;
    }
  }
  try {
    const result = await saveJsonFileWithPickerOrDownload(workFilePayload(), WORK_FILE_NAME);
    if (result.status === "cancelled") {
      statusMessage = "Speichern der Arbeitsdatei wurde abgebrochen.";
      renderAfterStorageAction();
      return;
    }
    if (result.status === "error") {
      statusMessage = "Die Arbeitsdatei konnte nicht gespeichert werden.";
      renderAfterStorageAction();
      return;
    }
    localStorage.setItem(WORK_FILE_NOTICE_KEY, "true");
    rememberWorkFileName(result.filename || WORK_FILE_NAME);
    statusMessage = result.status === "picker"
      ? "Arbeitsdatei wurde am gewählten Speicherort gespeichert."
      : "Arbeitsdatei wurde gespeichert. Der Browser unterstützt keine freie Speicherortauswahl. Die Datei wird über den normalen Download gespeichert.";
  } catch (error) {
    console.error("Work file export failed", error);
    statusMessage = "Die Arbeitsdatei konnte nicht gespeichert werden.";
  }
  renderAfterStorageAction();
}

async function openWorkFilePicker() {
  if (supportsPersistentWorkFile()) {
    try {
      const pickerOptions = {
        multiple: false,
        types: [{
          description: "FörderKompass Arbeitsdatei",
          accept: { "application/json": [".json"] }
        }]
      };
      if (selectedWorkDirectoryHandle) pickerOptions.startIn = selectedWorkDirectoryHandle;
      const [handle] = await window.showOpenFilePicker(pickerOptions);
      const file = await handle.getFile();
      importWorkFile(file, { connectedHandle: handle });
      return;
    } catch (error) {
      if (error?.name === "AbortError") return;
      console.error("Work file picker failed", error);
      workFileStatusMessage = "Die Arbeitsdatei konnte nicht ausgewählt werden. Bitte versuchen Sie es erneut.";
      renderAfterStorageAction();
      return;
    }
  }
  document.querySelector("#work-file")?.click();
}

async function connectedWorkFileHandleOrNull() {
  if (!supportsPersistentWorkFile()) return null;
  if (!connectedWorkFileHandle) connectedWorkFileHandle = await loadConnectedWorkFileHandle();
  return connectedWorkFileHandle;
}

