async function loadConnectedWorkFile() {
  if (!supportsPersistentWorkFile()) {
    workFileStatusMessage = "Dieser Browser unterstützt keine dauerhaft verbundene Arbeitsdatei. Bitte Arbeitsdatei manuell speichern und öffnen.";
    renderAfterStorageAction();
    return;
  }
  try {
    const handle = await connectedWorkFileHandleOrNull();
    if (!handle) {
      renderWorkFileAccessDialog();
      return;
    }
    const hasPermission = await ensureWorkFileReadPermission(handle);
    if (!hasPermission) {
      renderWorkFileAccessDialog();
      return;
    }
    const file = await handle.getFile();
    connectedWorkFileHandle = handle;
    rememberWorkFileName(file.name || handle.name || WORK_FILE_NAME, { connected: true });
    importWorkFile(file, { connectedHandle: handle });
  } catch (error) {
    console.error("Connected work file load failed", error);
    renderWorkFileAccessDialog();
  }
}

async function refreshConnectedWorkFile() {
  if (!supportsPersistentWorkFile()) {
    workFileStatusMessage = "Dieser Browser unterstützt keine dauerhaft verbundene Arbeitsdatei. Bitte Arbeitsdatei manuell speichern und öffnen.";
    renderAfterStorageAction();
    return;
  }
  try {
    const handle = await connectedWorkFileHandleOrNull();
    if (!handle) {
      renderWorkFileAccessDialog();
      return;
    }
    await writeWorkFileToHandle(handle);
    connectedWorkFileHandle = handle;
    await saveConnectedWorkFileHandle(handle);
    workFilePermissionState = "granted";
    localStorage.setItem(WORK_FILE_NOTICE_KEY, "true");
    workFileStatusMessage = "Verbundene Arbeitsdatei wurde aktualisiert.";
    renderAfterStorageAction();
  } catch (error) {
    if (error?.code !== "permission") console.error("Connected work file refresh failed", error);
    workFileStatusMessage = error?.code === "permission"
      ? "Der Zugriff auf die Arbeitsdatei muss erneut bestätigt werden. Bitte die Datei nach einem Klick erneut auswählen oder den Zugriff erlauben."
      : "Die verbundene Arbeitsdatei konnte nicht aktualisiert werden. Bitte die Datei erneut auswählen.";
    renderWorkFileAccessDialog();
  }
}

