    const panel = button.closest("[data-block-panel]");
    const card = button.closest("[data-block-module-card]");
    const module = parseSelectedModule(card?.dataset.moduleText || "");
    if (!panel || !module.text) return;
    applySuggestionToRasterField(
      panel.dataset.moduleRow,
      panel.dataset.moduleColumn,
      module.text,
      button.dataset.applyMode === "append" ? "append" : "replace"
    );
    button.closest("[data-block-module-choice]")?.classList.add("hidden");
    finishAuxiliaryTakeover(panel.dataset.moduleRow, panel.dataset.moduleColumn, panel, "Baustein eingefügt");
