    const panel = button.closest("[data-field-suggestion-panel]");
    const details = panel?.querySelector("[data-field-suggestion-details]");
    if (details) {
      const opening = details.classList.contains("hidden");
      if (opening) closeRasterAuxiliaryPanels(row, `field:${row}|massnahmen`);
      else closeMeasureHelpPanels(row, "");
      details.classList.toggle("hidden", !opening);
      button.textContent = opening ? "Vorschlag ausblenden" : "Vorschlag anzeigen";
      activeRasterPanel = opening ? { row, type: "field", key: `field:${row}|massnahmen` } : null;
    }
